window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cirurgia-cir-1"]={"block":"medcurso:medcurso-cirurgia-cir-1","label":"Medcurso · CIR 1","count":431,"questions":[{"id":"medcurso-cirurgia-cir-1-343817","number":"343817","sourceNumber":"343817","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Pac. ?, 22 anos, vítima de agressão por paulada. O ABC do trauma mostrava apenas\nequimose em abdome superior. O raios-x de abdome mostrava a sombra renal direita e músculo\npsoas direito bem delineados. Qual a hipótese diagnóstica?","options":{"A":"Hematoma retroperitonial.","B":"Lesão pancreática.","C":"Rotura renal.","D":"Lesão duodenal."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-291766","number":"291766","sourceNumber":"291766","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vítima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2 : 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor à palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem, Indique a principal suspeita diagnóstica que justifique o quadro clínico\ndescrito.","options":{"A":"Hematoma epidural.","B":"Hemorragia subaracnoide.","C":"Hematoma subdural.","D":"Hematoma intraparenquimatoso."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/291766.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-291767","number":"291767","sourceNumber":"291767","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vítima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2 : 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor à palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem, Identifique a fisiopatologia da alteração intracraniana identificada no exame\nde imagem.","options":{"A":"Ruptura da artéria meníngea média.","B":"Ruptura de vasos superficiais do córtex cerebral.","C":"Lesão do parênquima cerebral.","D":"Ruptura de vasos no espaço subaracnoide."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/291767.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-291768","number":"291768","sourceNumber":"291768","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vítima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2 : 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor à palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem, Indique a conduta terapêutica imediata mais adequada.","options":{"A":"Internação em unidade de terapia intensiva e suporte clínico para hipertensão intracraniana.","B":"Observação na sala de emergência e repetir a tomografia de crânio em 24 horas.","C":"Passar cateter para medir a pressão intracraniana e internar em unidade de terapia intensiva.","D":"Realizar craniotomia descompressiva à direita."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/291768.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283287","number":"283287","sourceNumber":"283287","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente internado na Unidade de Emergência de um hospital com traumatismo\ncranioencefálico (TCE). Na escala de coma de\nGlasgow ele apresenta as seguintes características:\nabertura ocular a dor, resposta verbal com palavras inapropriadas e resposta motora com\nlocalização da dor. Com base nesses dados é correto afirmar que os valores de escore atribuídos\nna escala correspondem respectivamente a:","options":{"A":"2, 3 e 5.","B":"2, 3 e 4.","C":"2, 2 e 5.","D":"2, 2 e 4."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283313","number":"283313","sourceNumber":"283313","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No trauma hepático grave, uma das principais manobras para conter a hemorragia, é o\npinçamento do pedículo hepático, \"manobra de Pringle\", que é realizada através de qual acidente\nanatômico?","options":{"A":"Recesso hepato-frênico.","B":"Hiato diafragmático.","C":"Retrocavidade dos epíplons.","D":"Forame de Winslow."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283324","number":"283324","sourceNumber":"283324","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Diante de um paciente vítima de trauma pélvico e com suspeita de lesão do trato\nurinário inferior, assinale a alternativa que apresenta a conduta INCORRETA:","options":{"A":"A cateterização imediata deve ser realizada quando há suspeita de ruptura contusa da bexiga.","B":"A presença de sangue no meato uretral ou o cateter uretral não passar facilmente indicam a\nrealização de uma uretrografia.","C":"As lesões do colo vesical indicam reparo cirúrgico imediato.","D":"As lesões extraperitoniais contusas, quando indicado, devem ser reparadas por suturas\nextravesicais e o hematoma pélvico perivesical deve ser drenado"},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-281160","number":"281160","sourceNumber":"281160","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente masculino, 47 anos, chega ao pronto socorro vítima de desabamento, ficando\npreso pelos membros inferiores durante 45\nminutos. Apresenta extensa laceração de membro\ninferior bilateral com sinais de lesão vascular associada. Submetido à fixação externa das fraturas\ne\nenxerto de interposição da veia safena em lesão da artéria poplítea esquerda. Internado em\nunidade de terapia intensiva apresenta os seguintes exames laboratoriais: hemoglobina: 9,9 g/dl,\ncreatinina 1,5 mg/dl, potássio: 7,8 mEq/L (VR: 3,5 a 5 mEq/L). Tomografia de tórax e abdome\nnormais. Membro inferior com pulsos distais palpáveis. Assinale a alternativa que indica a conduta\nadequada para minimizar o risco de eventos cardíacos adversos nesta paciente.","options":{"A":"Ringer lactato.","B":"Solução cristalóide.","C":"Sulfato de magnésio.","D":"Gluconato de cálcio.","E":"Inibidor da enzima de conversão da aldosterona."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-281162","number":"281162","sourceNumber":"281162","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem com 70kg com uma laceração na artéria braquial perde um total de 800ml\nde sangue. Em que classe de hemorragia o ACS\n(American College of Surgeons) classificaria isso?\nMarque a alternativa correta.","options":{"A":"Classe I.","B":"Classe II.","C":"Classe III.","D":"Classe IV.","E":"Classe V."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-281166","number":"281166","sourceNumber":"281166","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca do trauma torácico fechado, assinale a alternativa correta.","options":{"A":"Caracteristicamente, a contusão pulmonar sem fratura de costelas ocorre em pacientes idosos.","B":"A presença estimada de até 1.000 mL sangue no espaço pleural é uma contraindicação para a\ndrenagem torácica fechada.","C":"A ruptura do diafragma é mais comumente diagnosticada do lado esquerdo.","D":"O sinal de alargamento do mediastino é patognomônico de ruptura de aorta.","E":"A traqueia é o local mais acometido após o trauma torácico fechado."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-281169","number":"281169","sourceNumber":"281169","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 33 anos, vítima de colisão moto x anteparo, com TCE (trauma\ncrânioencefálico) com hematoma epidural, apresenta\nqueda da saturação de oxigênio, PA 80/40\nmmHg, FC 140 bpm e pulsos periféricos não palpáveis. Qual é a abordagem correta?","options":{"A":"Repetir a tomografia de crânio, para avaliar expansão do hematoma epidural.","B":"Craniotomia, para controle e hemostasia do sangramento intracraniano.","C":"Reavaliação do \"\"C\"\" (circulação), buscando fonte de hemorragia extracraniana.","D":"Drenagem imediata do hematoma epidural no centro cirúrgico.","E":"Tomografia de abdômen, tórax e pelve."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-251940","number":"251940","sourceNumber":"251940","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual é o principal mecanismo de trauma nas lesões contusas de intestino delgado?","options":{"A":"Queda de altura.","B":"Agressão.","C":"Acidente com veículos automotores.","D":"Trauma em esportes de contato."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-251945","number":"251945","sourceNumber":"251945","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente ?, 22 anos, vítima de trauma contuso de tórax. No ABCD foi identificado,\nenfisema subcutâneo em região cervical e\npneumotórax à direita. Foi realizado toracostomia no 5º\nespaço intercostal direito, linha axilar média, com escape aéreo importante. O paciente melhorou a\ndispnéia, mas no raios-X de tórax ainda demonstrava um pneumotórax importante (50%), foi\nintroduzido um segundo dreno e permanecia com escape aéreo e pneumotórax residual. Qual sua\nhipótese diagnóstica?","options":{"A":"Contusão pulmonar grave associada a lesão pleural.","B":"Fraturas costais múltiplas associada a lesão pleural.","C":"Lesão de traquéia ou brônquio fonte.","D":"Lesão pleural extensa associado à lesão diafragmática."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-217679","number":"217679","sourceNumber":"217679","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente sexo masculino, 24 anos, vítima de ferimento por uma arma branca no 4º\nespaço intercostal esquerdo, linha\nhemiclavicular. Ao exame físico, apresenta taquipneia, pulsos\nfiliformes, hipofonese de bulhas e turgência jugular. A partir desses achados, qual a hipótese\ndiagnóstica?","options":{"A":"Tamponamento cardíaco.","B":"Pneumotórax hipertensivo.","C":"Hemotórax maciço.","D":"Hemopneumotórax."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-217693","number":"217693","sourceNumber":"217693","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São indicações de investigação radiológica do sistema urinário no trauma, EXCETO\ntodas as lesões:","options":{"A":"Perfurantes no abdome.","B":"Contusas.","C":"Perfurantes no abdome com micro ou macro hematúria.","D":"Contusas associada a choque hipovolêmico e hematúria."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183201","number":"183201","sourceNumber":"183201","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"Hematoma pulsátil e sangramento ativo são sinais altamente compatíveis com lesão arterial.","B":"Lesão nervosa associada à ferida por arma de fogo na região inguinal é sinal patognomônico de\nlesão vascular.","C":"Em um membro com traumatismo ortopédico, a presença de pulso distal não descarta lesão\narterial associada.","D":"O espasmo arterial pode surgir em decorrência de traumatismo arterial, porém deve ser\nconsiderado diagnóstico de exclusão.","E":"A reconstrução vascular deve ser feita de preferência com enxerto autógeno."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183166","number":"183166","sourceNumber":"183166","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A rotura da uretra peníana na transição penoescrotal pode resultar no extravazamento\nde urina para todas as estruturas a seguir,\nEXCETO:","options":{"A":"A parede abdominal anterior até a clavícula.","B":"O escroto.","C":"O pênis, profundamente até a fascia de dartos.","D":"O períneo, em um padrão \"asa de borboleta\".","E":"As nádegas."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183159","number":"183159","sourceNumber":"183159","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Os erros mais comuns na ressuscitação de uma criança politraumatizada são falhas em\ntodas as alternativas abaixo, EXCETO:","options":{"A":"Abrir e manter a via aérea pérvia.","B":"Estabilizar e imobilizar a coluna cervical.","C":"Fornecer oxigenação e ventilação apropriadas.","D":"Fornecer ressuscitação volêmica adequada.","E":"Reconhecer o escore de coma de Glasgow modificado para pediatria."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182615","number":"182615","sourceNumber":"182615","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente masculino, 26 anos, vítima de ferida por arma de fogo, transfixante, orifício de\nentrada na altura do 3º espaço intercostal direito, linha hemiclavicular. Qual a sua conduta\nimediata?","options":{"A":"Drenagem pleural direita.","B":"Toracocentese à direita.","C":"ABCD do trauma.","D":"Toracotomia direita."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182623","number":"182623","sourceNumber":"182623","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente feminino, 36 anos, vítima de acidente automobilístico, colisão frontal a\n80Km/h, usava cinto de segurança no momento do\nacidente. Foi avaliada na sala de trauma e\ndeixada em observação, ABCD estava sem alterações, Glasgow 15/15. Após 12h recebeu alta.\nRetorna após 5 dias referindo dor abdominal difusa e palidez cutaneomucosa, FC: 120 bpm e PA\n80X60 mmHg. Qual a hipótese diagnóstica?","options":{"A":"Infarto agudo do miocárdio.","B":"Hemotórax.","C":"Hemoperitônio.","D":"Rotura tardia de víscera oca."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182630","number":"182630","sourceNumber":"182630","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considerando-se o trauma urológico, é CORRETO afirmar que:","options":{"A":"A melhor conduta, na suspeita de lesão uretral é o cateterismo uretral, que diminui a incidência\nde estenose e de infecção posteriores.","B":"Os traumas penetrantes de bexiga são mais comuns que os fechados.","C":"A presença de extravasamento de contraste do sistema coletor e de laceração grande da artéria\nrenal são indicações de tratamento cirúrgico nos casos de trauma renal.","D":"As lesões renais grau II correspondem àquelas com laceração de profundidade maior que 1 cm,\nsem ruptura do sistema excretor."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-159060","number":"159060","sourceNumber":"159060","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente adulto, masculino, politraumatizado, grave contusão do tórax, apresenta\ndispneia e movimento paradoxal do tórax à direita. Qual a medida imediata mais importante?","options":{"A":"Punção com agulha grossa no 2° espaço intercostal, linha médio-clavicular.","B":"Toracostomia com drenagem em selo d'água.","C":"Dois acessos venosos com abocath n° 14.","D":"Verificar a permeabilidade da via aérea."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-108726","number":"108726","sourceNumber":"108726","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O uso da videolaparoscopia no trauma tem indicação definida na seguinte condição:","options":{"A":"Suspeita de penetração abdominal em ferimento por arma branca na região lombar;","B":"Suspeita de penetração em ferimento por arma de fogo tangencial a parede abdominal;","C":"Lavado peritoneal diagnóstico positivo para restos vegetais;","D":"Hipotensão sem causa aparente em paciente inconsciente."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-108745","number":"108745","sourceNumber":"108745","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual é o principal mecanismo de trauma nas lesões contusas de intestino delgado?","options":{"A":"Queda de altura;","B":"Agressão;","C":"Acidente com veículos automotores;","D":"Trauma em esportes de contato."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-369533","number":"369533","sourceNumber":"369533","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"De acordo com o caso descrito, indique a conduta mais adequada que deveria ter sido\ntomada na cena do trauma, para o ferimento do abdome:","options":{"A":"Realizar curativo compressivo no abdome.","B":"Realizar manobra para reintrodução das vísceras na cavidade abdominal e curativo oclusivo.","C":"Cobrir as vísceras com compressas embebidas em soro fisiológico 0,9% e proteger com curativo\nsecundário.","D":"Lavar as vísceras com soro fisiológico 0,9%, realizar manobra para reintrodução das vísceras na\ncavidade abdominal e curativo oclusivo."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-369534","number":"369534","sourceNumber":"369534","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido ao Pronto-Socorro, vítima de\nferimento, com máquina industrial com corte no abdome há 30 minutos. Dá entrada no hospital,\nreferindo dor abdominal. Ao exame, A: Via aérea pérvia, colocado colar cervical, Sato2,: 98%; B:\nmurmúrios vesiculares bem distribuídos sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 98bpm, PA: 118x74mmHg, sem sinais de sangramentos externos, pelve\nestável e toque retal sem alterações; D: escala de coma de Glasgow-15, pupilas isocóricas e\nfotorreagentes; E: abdome com ferimento de cerca de 15cm na região de mesogástrio com\npresença de alças de intestino delgado extrusas. Indique a conduta mais adequada após a\navaliação inicial no Pronto-Socorro:","options":{"A":"Infundir 1000ml de ringer lactato por acessos periféricos calibrosos.","B":"Solicitar tomografia de abdome total com contraste.","C":"Realizar manobra para reintrodução das vísceras na cavidade abdominal e sutura da parede\nabdominal por camadas.","D":"Realizar laparotomia exploradora."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-372085","number":"372085","sourceNumber":"372085","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a síndrome compartimental abdominal (SCA) na população neonatal assinale a\nalternativa correta:","options":{"A":"A sepse e o íleo paralitico são excluídas como causas secundárias.","B":"A clínica é bem descrita, por isso há consenso de método diagnóstico.","C":"A hiperlactenemia, ainda que não prediga mortalidade, pode ser usada como indicativo de\ndesfecho desfavorável.","D":"A situação se associa a um quadro de aumento da motilidade intestinal."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-369535","number":"369535","sourceNumber":"369535","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 30 anos de idade, é trazido ao Pronto-Socorro, vítima de\nferimento, com máquina industrial com corte no abdome há 30 minutos. Dá entrada no hospital,\nreferindo dor abdominal. Ao exame, A: Via aérea pérvia, colocado colar cervical, Sato2,: 98%; B:\nmurmúrios vesiculares bem distribuídos sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 98bpm, PA: 118x74mmHg, sem sinais de sangramentos externos, pelve\nestável e toque retal sem alterações; D: escala de coma de Glasgow-15, pupilas isocóricas e\nfotorreagentes; E: abdome com ferimento de cerca de 15cm na região de mesogástrio com\npresença de alças de intestino delgado extrusas. Indique a conduta mais adequada, caso este\npaciente não apresentasse extrusão das alças intestinais durante a avaliação inicial:","options":{"A":"Solicitar tomografia computadorizada de abdome total com contraste.","B":"Realizar exploração digital do ferimento sob anestesia local.","C":"Realizar laparotomia exploradora.","D":"Realizar sutura da parede abdominal por camadas."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-341047","number":"341047","sourceNumber":"341047","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido por populares, após ser vítima de\ntrauma moto x anteparo, em via expressa, há 45 minutos. Dá entrada no Pronto-Socorro com\nrebaixamento do nível de consciência. Ao exame, A: via aérea pérvia, colocado colar cervical,\nSatO2:92%; B: murmúrios vesiculares bem distribuídos com diminuição em base esquerda, FR:\n22ipm; C: bulhas rítmicas e normofonéticas, FC: 112bpm, PA: 86x54mmHg, pulsos radiais\nassimétricos, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow: 7, pupilas isocóricas e fotorreagentes; E: escoriações e dor à palpação em\nhemitórax esquerdo. Foi realizado radiografia de tórax na sala de emergência. De acordo com o\ncaso e com o exame da imagem, indique a principal suspeita diagnóstica que justifique o quadro\nclínico.","options":{"A":"Hemotórax.","B":"Pneumotórax.","C":"Tamponamento cardíaco.","D":"Ruptura de aorta."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/341047.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-341048","number":"341048","sourceNumber":"341048","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido por populares, após ser vítima de\ntrauma moto x anteparo, em via expressa, há 45 minutos. Dá entrada no Pronto-Socorro com\nrebaixamento do nível de consciência. Ao exame, A: via aérea pérvia, colocado colar cervical,\nSatO2:92%; B: murmúrios vesiculares bem distribuídos com diminuição em base esquerda, FR:\n22ipm; C: bulhas rítmicas e normofonéticas, FC: 112bpm, PA: 86x54mmHg, pulsos radiais\nassimétricos, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow: 7, pupilas isocóricas e fotorreagentes; E: escoriações e dor à palpação em\nhemitórax esquerdo. Foi realizado radiografia de tórax na sala de emergência. Diante do caso,\nindique a primeira conduta que deve ser instituída no Pronto-Socorro:","options":{"A":"Toracostomia com drenagem em selo d'água.","B":"Pericardiocentese de alívio.","C":"Intubação orotraqueal com ventilação mecânica assistida.","D":"Transfusão de duas unidades de concentrado de hemácias."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/341048.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-341049","number":"341049","sourceNumber":"341049","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido por populares, após ser vítima de\ntrauma moto x anteparo, em via expressa, há 45 minutos. Dá entrada no Pronto-Socorro com\nrebaixamento do nível de consciência. Ao exame, A: via aérea pérvia, colocado colar cervical,\nSatO2:92%; B: murmúrios vesiculares bem distribuídos com diminuição em base esquerda, FR:\n22ipm; C: bulhas rítmicas e normofonéticas, FC: 112bpm, PA: 86x54mmHg, pulsos radiais\nassimétricos, abdome indolor à palpação, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow: 7, pupilas isocóricas e fotorreagentes; E: escoriações e dor à palpação em\nhemitórax esquerdo. Foi realizado radiografia de tórax na sala de emergência. Indique o exame\npadrão-ouro para confirmação diagnóstica do trauma apresentado pelo paciente:","options":{"A":"Tomografia computadorizada de tórax com contraste.","B":"Aortografia.","C":"Ecocardiografia transtorácica.","D":"Broncoscopia."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/341049.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-343193","number":"343193","sourceNumber":"343193","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A conduta mais adequada para este quadro é:","options":{"A":"Cirurgia de emergência.","B":"Correção de distúrbios hidroeletrolíticos e ácido-base, e cirurgia de urgência assim que\nestabilização clínico-laboratorial.","C":"Redução hidrostática ou pneumática.","D":"Correção de distúrbios hidroeletrolíticos e ácido-base e redução do volume da dieta em 30%,\ninibidor de bomba de prótons e reavaliação em 1 semana."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-315166","number":"315166","sourceNumber":"315166","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No paciente com traumatismo craniofacial, suspeita- se de fratura de base do crânio\nquando há:","options":{"A":"Otorragia.","B":"Otoliquorreia.","C":"Nasoliquorreia.","D":"Equimose periorbitária bilateral.","E":"Todas as alternativas estão corretas."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-314203","number":"314203","sourceNumber":"314203","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa correta sobre o atendimento do paciente com Traumatismo\nCrânioencefálico (TCE):","options":{"A":"Papiledema se presente, confirma o diagnóstico de hipertensão intracraniana, porém pode estar\nausente nos casos agudos.","B":"Deve-se administrar manitol, como protocolo, em todos os pacientes vítimas de TCE,\nindependente da gravidade, para evitar parada cardiorrespiratória por herniação.","C":"A monitorização da pressão intracraniana é recomendada quando lactentes e crianças\napresentam-se com escala de coma de Glasgow de 15.","D":"Recomenda-se manter a pressão de perfusão cerebral em crianças com TCE em torno de\n90mmHg."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-307048","number":"307048","sourceNumber":"307048","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, 46 anos de idade, sexo masculino, foi vítima de atropelamento em via\npública. Atendido pelo SAMU apresentava-se\ndispnéico, taquicárdico, hipotenso e com dificuldade\nde fala. À ausculta, foi percebido murmúrio vesicular abolido em hemitórax direito, com timpanismo\nà percussão, além de perceptível fratura de arco costal à palpação e ingurgitamento das veias\njugulares. Com base nos dados apresentados, indique o diagnóstico para esse caso.","options":{"A":"Hemotórax.","B":"Pneumotórax hipertensivo.","C":"Pneumotórax simples.","D":"Tórax instável."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-307050","number":"307050","sourceNumber":"307050","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, 46 anos de idade, sexo masculino, foi vítima de atropelamento em via\npública. Atendido pelo SAMU apresentava-se\ndispnéico, taquicárdico, hipotenso e com dificuldade\nde fala. À ausculta, foi percebido murmúrio vesicular abolido em hemitórax direito, com timpanismo\nà percussão, além de perceptível fratura de arco costal à palpação e ingurgitamento das veias\njugulares. Considerando que o paciente já está no 5º dia de internação com dreno de tórax em selo\nd'água, que está não oscilante, com débito de 25mL/dia, não borbulhante, e que a radiografia de\ntórax mostra dreno dobrado na base, com pulmão expandido, a conduta neste momento é:","options":{"A":"Trocar o dreno de tórax.","B":"Retirar o dreno de tórax.","C":"Instalar pressão negativa.","D":"Realizar abordagem cirúrgica."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283721","number":"283721","sourceNumber":"283721","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vitima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2: 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor a palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem. Indique a principal suspeita diagnóstica que justifique o quadro clínico\ndescrito.","options":{"A":"Hematoma epidural.","B":"Hemorragia subaracnoide.","C":"Hematoma subdural.","D":"Hematoma intraparenquimatoso."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/283721.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283722","number":"283722","sourceNumber":"283722","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vitima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2: 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor a palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem. Identifique a fisiopatologia da alteração intracraniana identificada no exame\nde imagem.","options":{"A":"Ruptura da artéria meníngea média.","B":"Ruptura de vasos superficiais do córtex cerebral.","C":"Lesão do parênquima cerebral.","D":"Ruptura de vasos no espaço subaracnoide."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/283722.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-283723","number":"283723","sourceNumber":"283723","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 24 anos de idade, é trazido, pelo SAMU, vitima de queda de\nmoto em via expressa há 30 minutos. Dá entrada no pronto socorro com colar cervical e prancha\nrígida, referindo cefaleia, náusea e vômitos. Ao exame, apresenta parâmetros ABCDE do trauma:\nA: Via aérea pérvia, mantido colar cervical, SatO2: 96% com cateter de O2 15L/min; B: murmúrios\nvesiculares bem distribuídos e sem ruídos adventícios, FR: 20ipm; C: Bulhas rítmicas e\nnormofonéticas, FC: 88bpm, PA: 118x74mmHg, abdome indolor a palpação, pelve estável e toque\nretal sem alterações; D: escala de coma de Glasgow = 9, pupila direita midriática e pouco reagente,\nhemiplegia esquerda; E: escoriações, abaulamento e dor à palpação em região parietotemporal\ndireita do couro cabeludo. Foi realizada tomografia de crânio. De acordo com o caso descrito e com\no exame de imagem. Indique a conduta terapêutica imediata mais adequada.","options":{"A":"Internação em unidade de terapia intensiva e suporte clínico para hipertensão intracraniana.","B":"Observação na sala de emergência e repetir a tomografia de crânio em 24 horas.","C":"Passar cateter para medir a pressão intracraniana e internar em unidade de terapia intensiva.","D":"Realizar craniotomia descompressiva à direita."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/283723.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-275982","number":"275982","sourceNumber":"275982","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente teve trauma vascular de membro inferior evoluindo com edema importante do\nmesmo membro, pé eqüino e perda da\nsensibilidade. Qual o seu diagnóstico provável?","options":{"A":"Fratura.","B":"Síndrome compartimental.","C":"Edema traumático.","D":"Rotura muscular.","E":"Trombose venosa."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-275984","number":"275984","sourceNumber":"275984","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 40 anos, vítima de queda de andaime, apresenta\ninstabilidade no tórax por múltiplas fraturas de arcos costais bilateral. Mesmo com drenagem\ntorácica bilateral, evolui com insuficiência respiratória. No exame de imagem, pulmões não\nexpandidos. Que conduta tomar inicialmente?","options":{"A":"Entubação orotraqueal com ventilação mecânica.","B":"Cirurgia para fixação dos arcos costais.","C":"Trocar os drenos torácicos.","D":"Oxigenioterapia sob Máscara de Venturi.","E":"Nenhuma das alternativas."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-280420","number":"280420","sourceNumber":"280420","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a Hemorragia Maciça e o Choque Hemorrágico, assinale a alternativa correta.","options":{"A":"A PA é muito sensível a perdas sanguíneas. Sabe-se que a hipotensão é sinal de gravidade\nprecoce de um sangramento não controlado.","B":"Frente a uma hemorragia maciça, a relação de hemocomponentes é para cada quatro bolsas de\nconcentrado de hemácias uma bolsa de plasma fresco congelado.","C":"Durante um choque hemorrágico, o uso de concentrado de hemácias tem como meta manter o\nnível de hemoglobina acima de 7g/dL.","D":"Frente a um quadro de hemorragia digestiva, a meta de plaquetas é mantê-las acima de\n\n100.000 plaquetas/mm3."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-278110","number":"278110","sourceNumber":"278110","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A instabilidade hemodinâmica por choque hemorrágico nos traumas contusos, se dão,\ngeralmente por trauma em qual órgão?","options":{"A":"Fígado.","B":"Duodeno.","C":"Mesentério.","D":"Baço."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-278112","number":"278112","sourceNumber":"278112","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Após 72 horas de toracostomia com drenagem pleural fechada em selo d?água por\nferimento penetrante por arma branca em região anterior do tórax a direita, o paciente permanece\ncom grande débito aéreo conferido pelas borbulhas no selo d?água. Mantém-se estável\nhemodinamicamente. Eupneico. A principal hipótese diagnóstica é:","options":{"A":"Pneumotórax de tensão.","B":"Lesão vascular.","C":"Lesão de traqueia.","D":"Fístula brônquica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-278114","number":"278114","sourceNumber":"278114","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a divisão anatômica da região cervical, assinale a correta.","options":{"A":"Zona I é o espaço entre a cartilagem cricóide à fossa supra-clavicular.","B":"Zona I envolve o espaço entre a base do crânio e a mandíbula.","C":"Zona II é o espaço entre o ângulo da mandíbula e a cartilagem tireóidea.","D":"Zona II é o espaço entre o ângulo da mandíbula e a cartilagem cricóide, região anatômica que\ngeralmente se associa com lesões intratorácicas."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-278645","number":"278645","sourceNumber":"278645","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 34 anos é vítima de acidente automobilístico e trazido ao pronto-socorro.\nDurante a avaliação queixou-se de dor\nabdominal importante e foi submetido ao exame ecográfico\nde emergência (FAST - Focused Assessment with Sonography for Trauma). Sinais vitais: PA:\n80x40 mmHg, FC: 130 bpm, FR: 35 irpm, Sat O2: 91%, T: 36,1ºC. Seguem algumas imagens do\nexame abaixo. A conduta adequada neste caso é:","options":{"A":"Tomografia de abdome com contraste endovenoso.","B":"Ecografia de abdome total.","C":"Laparotomia exploradora.","D":"Tratamento não operatório."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/278645.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-280436","number":"280436","sourceNumber":"280436","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos, há 50 minutos foi vítima de ferimento por arma branca em 4º\nespaço intercostal direito, na linha axilar\nanterior. É admitido em prancha rígida, sem colar cervical,\nem uso de cateter de oxigênio com fluxo de 4 litros/min, agitado. Sinais vitais da admissão em sala\nde emergência: pressão arterial: 90 x 40 mmHg, frequência cardíaca: 121 bpm, frequência\nrespiratória: 25 irpm, saturação de oxigênio periférica: 89%, temperatura axilar: 36,5º. Ao exame\nfísico: regular estado geral, ansioso, agitado, confuso, corado, hidratado. Murmúrio presente em\nhemitórax esquerdo, abolido à direita. Percussão em hemitórax direito hipertimpânica com\nexpansibilidade reduzida. Bulhas rítmicas, taquicárdicas, normofonéticas, sem sopros audíveis ou\nabafamento de bulhas. Presença de estase jugular patológica. A principal hipótese diagnóstica é:","options":{"A":"Tamponamento Cardíaco.","B":"Atelectasia.","C":"Pneumotórax Hipertensivo.","D":"Lesão Traumática de Aorta."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-280437","number":"280437","sourceNumber":"280437","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos, há 50 minutos foi vítima de ferimento por arma branca em 4º\nespaço intercostal direito, na linha axilar\nanterior. É admitido em prancha rígida, sem colar cervical,\nem uso de cateter de oxigênio com fluxo de 4 litros/min, agitado. Sinais vitais da admissão em sala\nde emergência: pressão arterial: 90 x 40 mmHg, frequência cardíaca: 121 bpm, frequência\nrespiratória: 25 irpm, saturação de oxigênio periférica: 89%, temperatura axilar: 36,5º. Ao exame\nfísico: regular estado geral, ansioso, agitado, confuso, corado, hidratado. Murmúrio presente em\nhemitórax esquerdo, abolido à direita. Percussão em hemitórax direito hipertimpânica com\nexpansibilidade reduzida. Bulhas rítmicas, taquicárdicas, normofonéticas, sem sopros audíveis ou\nabafamento de bulhas. Presença de estase jugular patológica. A conduta mais adequada neste\ncaso, conforme as últimas atualizações do suporte avançado de vida no trauma é:","options":{"A":"Radiografia de tórax.","B":"FAST (Focused Assessment with Sonography for Trauma).","C":"Toracotomia de urgência.","D":"Descompressão manual + toracostomia com drenagem em sistema fechado."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-280438","number":"280438","sourceNumber":"280438","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A lesão traumática evidenciada pela Tomografia de Crânio abaixo é:","options":{"A":"Hematoma epidural.","B":"Hematoma extradural.","C":"Hematoma subdural.","D":"Hemorragia subaracnóideo."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/280438.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249298","number":"249298","sourceNumber":"249298","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de trauma cranioencefálico, trazido pelo resgate anisocórico, sem\nabertura ocular a nenhum estímulo, com sons incompreensíveis, apresentando episódios de\ndecorticação ? padrão flexor anormal. A pontuação na escala de coma de Glasgow é:","options":{"A":"5","B":"6","C":"7","D":"8"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252894","number":"252894","sourceNumber":"252894","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo feminino, 19 anos de idade, é trazida pelo SAMU ao hospital Geral\nRegional, vítima de atropelamento por automóvel em alta velocidade, há 30 min. Dá entrada com\ncolar cervical, prancha rígida e cateter nasal de oxigênio. Paciente relata dor em abdome, em\nregião subescapular esquerda e em perna esquerda. No atendimento inicial: A: via aérea pérvia,\nmantido colar cervical, SatO?: 95% com cateter nasal 15l/min; B: Murmúrio vesicular bem\ndistribuído sem ruído adventício, FR: 22ipm; : Bulhas rítmicas e normofonéticas, por difusa à\npalpação abdominal, pelve estável, toque retal sem alterações, FC:122bpm, PA: 82x62mmHg; D:\nEscala de coma de Glasgow 14 e pupilas isocóricas e fotorreagentes; E: escoriações difusas,\nlaceração em couro cabeludo com sangramento ativo e desalinhamento em terço distal da perna\nesquerda. Após ressuscitação inicial com 2 litros de solução cristaloide, a paciente manteve as\nmesmas queixas, FC: 120bpm, PA: 84x60mmHg, FR: 22ipm, SatO?: 94%. De acordo com os\ndados, indique a principal causa que determina o quadro clínico.","options":{"A":"Sangramento ativo do couro cabeludo.","B":"Fratura da perna esquerda.","C":"Trauma renal esquerdo.","D":"Trauma esplênico."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249300","number":"249300","sourceNumber":"249300","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A conduta imediata a ser tomada ao se diagnosticar um pneumotórax hipertensivo é:","options":{"A":"radiografia de tórax.","B":"pericardiocentese de alívio (punção de Marfan).","C":"punção de alívio seguida de drenagem de tórax.","D":"intubação orotraqueal."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252895","number":"252895","sourceNumber":"252895","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo feminino, 19 anos de idade, é trazida pelo SAMU ao hospital Geral\nRegional, vítima de atropelamento por automóvel em alta velocidade, há 30 min. Dá entrada com\ncolar cervical, prancha rígida e cateter nasal de oxigênio. Paciente relata dor em abdome, em\nregião subescapular esquerda e em perna esquerda. No atendimento inicial: A: via aérea pérvia,\nmantido colar cervical, SatO?: 95% com cateter nasal 15l/min; B: Murmúrio vesicular bem\ndistribuído sem ruído adventício, FR: 22ipm; : Bulhas rítmicas e normofonéticas, por difusa à\npalpação abdominal, pelve estável, toque retal sem alterações, FC:122bpm, PA: 82x62mmHg; D:\nEscala de coma de Glasgow 14 e pupilas isocóricas e fotorreagentes; E: escoriações difusas,\nlaceração em couro cabeludo com sangramento ativo e desalinhamento em terço distal da perna\nesquerda. Após ressuscitação inicial com 2 litros de solução cristaloide, a paciente manteve as\nmesmas queixas, FC: 120bpm, PA: 84x60mmHg, FR: 22ipm, SatO?: 94%. Indique o exame\ncomplementar mais adequado para a confirmação do diagnóstico.","options":{"A":"Radiografia de tórax.","B":"Radiografia da perna esquerda.","C":"Ultrassonografia focada para o trauma (FAST).","D":"Tomografia computadorizada de abdome."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249201","number":"249201","sourceNumber":"249201","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa correta com relação à traqueostomia de urgência em crianças.","options":{"A":"Em qualquer situação, só deve ser realizada após várias tentativas de intubação.","B":"Deve ser realizada como procedimento de escolha para garantir a via aérea em todos os casos\nde sintomas obstrutivos altos.","C":"É um procedimento tecnicamente difícil em vias aéreas pequenas.","D":"Deve ser realizada, apenas, após a falha de uma cricotireoidostomia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252896","number":"252896","sourceNumber":"252896","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo feminino, 19 anos de idade, é trazida pelo SAMU ao hospital geral\nregional, vítima de atropelamento por automóvel em alta velocidade, há 30 min. Dá entrada com\ncolar cervical, prancha rígida e cateter nasal de oxigênio. Paciente relata dor em abdome, em\nregião subescapular esquerda e em perna esquerda. No atendimento inicial: A: via aérea pérvia,\nmantido colar cervical, SatO?: 95% com cateter nasal 15 L/min; B: Murmúrio vesicular bem\ndistribuído sem ruído adventício, FR: 22 ipm; Bulhas rítmicas e normofonéticas, por difusa à\npalpação abdominal, pelve estável, toque retal sem alterações, FC:122 bpm, PA: 82x62 mmHg; D:\nEscala de coma de Glasgow 14 e pupilas isocóricas e fotorreagentes; E: escoriações difusas,\nlaceração em couro cabeludo com sangramento ativo e desalinhamento em terço distal da perna\nesquerda. Após ressuscitação inicial com 2 litros de solução cristaloide, a paciente manteve as\nmesmas queixas, FC: 120 bpm, PA: 84x60 mmHg, FR: 22 ipm, SatO?: 94%. Após a confirmação\ndiagnóstica, indique a conduta cirúrgica mais adequada, no momento.","options":{"A":"Sutura do couro cabeludo.","B":"Laparotomia exploradora.","C":"Fixação cirúrgica da fratura da perna esquerda.","D":"Videolaparoscopia."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249202","number":"249202","sourceNumber":"249202","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Na avaliação neurológica da escala de coma de Glasgow, avaliamos todos os\nparâmetros abaixo, exceto","options":{"A":"reflexo córneo palpebral.","B":"decorticação.","C":"orientação no tempo e espaço.","D":"abertura ocular."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249305","number":"249305","sourceNumber":"249305","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São alterações esperadas no paciente com síndrome compartimental abdominal com\npressão intra-abdominal de 35 mmHg:","options":{"A":"oligúria, débito cardíaco reduzido, redução do retorno venoso.","B":"oligúria, débito cardíaco aumentado, aumento do retorno venoso.","C":"poliúria, débito cardíaco reduzido, aumento do retorno venoso.","D":"poliúria, débito cardíaco aumentado, redução do retorno venoso."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-231377","number":"231377","sourceNumber":"231377","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos sofreu acidente automobilístico, colisão carro x carro frontal. Ficou\npreso nas ferragens e os bombeiros já haviam efetuado a extricação do paciente. Ao chegar ao\nlocal a equipe do SAMU encontrou o paciente com sangramento em toda a face, abertura ocular\nespontânea, respondendo de forma desconexa às solicitações verbais, sem movimentar os\nmembros inferiores e localizava a dor. Ventilação bilateral, pulso cheio e enchimento capilar < que\n2?. Responda as questões de acordo com o caso acima: Qual a conduta mais adequada do pré ?\nhospitalar?","options":{"A":"Limpar o ferimento da face","B":"Máscara de 02","C":"Avaliar vias aéreas, imoblização padrão","D":"Avaliar vias aéreas, suplementação de O2, acesso venoso, imobilização padrão.","E":"Providenciar via aérea definitiva"},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-231378","number":"231378","sourceNumber":"231378","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos sofreu acidente automobilístico, colisão carro x carro frontal. Ficou\npreso nas ferragens e os bombeiros já haviam efetuado a extricação do paciente. Ao chegar ao\nlocal a equipe do SAMU encontrou o paciente com sangramento em toda a face, abertura ocular\nespontânea, respondendo de forma desconexa às solicitações verbais, sem movimentar os\nmembros inferiores e localizava a dor. Ventilação bilateral, pulso cheio e enchimento capilar < que\n2?. Responda as questões de acordo com o caso acima: Como classificamos o traumatismo\ncraniano de acordo com a escala de coma de Glasgow apresentada pelo paciente","options":{"A":"TCE leve","B":"TCE moderado","C":"TCE grave","D":"TCE gravíssimo","E":"TCE levíssimo"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249213","number":"249213","sourceNumber":"249213","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Das alternativas apresentadas abaixo, assinale aquela que não representa uma\nindicação para intubação orotraqueal em crianças vítimas de politraumatismo.","options":{"A":"Necessidade de suporte ventilatório prolongado, por exemplo, por lesões torácicas.","B":"Parada respiratória.","C":"Obstrução de vias aéreas.","D":"Escala de coma de Glasgow menor ou igual a 12."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-231379","number":"231379","sourceNumber":"231379","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos sofreu acidente automobilístico, colisão carro x carro frontal. Ficou\npreso nas ferragens e os bombeiros já haviam efetuado a extricação do paciente. Ao chegar ao\nlocal a equipe do SAMU encontrou o paciente com sangramento em toda a face, abertura ocular\nespontânea, respondendo de forma desconexa às solicitações verbais, sem movimentar os\nmembros inferiores e localizava a dor. Ventilação bilateral, pulso cheio e enchimento capilar < que\n2?. Responda as questões de acordo com o caso acima: Paciente apresentava paraplegia no local,\nqual segmento da coluna vertebral mais provavelmente foi lesionado?","options":{"A":"Segmento cervical (C1- C4)","B":"Segmento cervical (C5 ? C7)","C":"Segmento torácico (T6 ? T10)","D":"Segmento lombar (L3 ? L5)","E":"Nenhum segmento afetado"},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-231380","number":"231380","sourceNumber":"231380","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São sinais de fratura de base de crânio","options":{"A":"Sinal de Guaxinim, Battle e Murphy","B":"Otorrinoliquorréia, sinal de Guaxinim e Murphy","C":"Otorrinoliquorréia, sinal de Guaxinim e Battle","D":"Sinal de Murphy, Blumberg e Dunphy","E":"Sinal de Guaxinim, Murphy e Dunphy"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249415","number":"249415","sourceNumber":"249415","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 50 anos, após queda de andaime de aproxidamente 9 metros de altura,\nchega em sala de emergência com trauma\ntorácico importante, em franca insuficiência respiratória.\nA conduta imediata é:","options":{"A":"Traqueostomia de urgência.","B":"Cricotireoidostomia.","C":"Drenagem de tórax fechada.","D":"Intubação orotraqueal."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249420","number":"249420","sourceNumber":"249420","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 25 anos de idade, vítima de acidente moto hemorrágico, apresentando os\nseguintes sinais vitais: pressão arterial: 60 x 40 mmHg, frequência cardíaca: 135 bpm, frequênci\nrespiratória: 32 irpm, confuso. Segundo o protocolo do choque e a conduta indicada?","options":{"A":"Classe II - Reposição com cristaloides e hemoderivados.","B":"Classe III - Reposição com cristaloides e hemoderivados.","C":"Classe IV - Reposição com cristalóides, apenas.","D":"Classe IV - Reposição com cristaloides e hemoderivados."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249237","number":"249237","sourceNumber":"249237","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A principal hipótese diagnóstica em um paciente vítima de acidente motociclístico com\ntrauma em região de transição tóraco-abdominal a esquerda, associada à radiografia abaixo é:","options":{"A":"Avulsão esplênica.","B":"Hérnia diafragmática traumática.","C":"Hemotórax maciço.","D":"Pneumotórax hipertensivo."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/249237.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212143","number":"212143","sourceNumber":"212143","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, masculino, 20 anos, vítima de acidente automobilístico (estava no banco do\ncarona e com cinto de segurança, óbito do motorista na cena) há 1 hora, trazido por terceiros para\no hospital onde você é plantonista. Paciente foi transportado para a sala de emergência numa\nmaca, acordado, frequência respiratória de 30 irpm, expansibilidade simétrica, pulsos radiais\npalpáveis e filiformes, frequência cardíaca 132 bpm, pressão arterial de 95 x 56 mmHg, mucosas\ndescoradas (3+/4+) desorientado, responsivo, abertura ocular e movimentos espontâneos. Sobre a\ncondução do caso, qual a alternativa correta?","options":{"A":"Deve-se realizar drenagem torácica bilateral.","B":"A medida mais precoce a ser instituída é a colocação do colar cervical.","C":"Deve-se realizar toracotomia de reanimação na sala de trauma.","D":"Esse paciente tem indicação de intubação orotraqueal na sala de trauma.","E":"O paciente deverá ser encaminhado prontamente para a realização de tomografia de crânio,\ncoluna cervical, tórax e abdome."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-219880","number":"219880","sourceNumber":"219880","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 30 anos sofreu acidente automobilístico e, imediatamente após dar entrada\nna sala de emergência, é constatado\ndispneia, diminuição do murmúrio vesicular no lado direito e\nhipertimpanismo ipsilateral. Apresenta também sinais de choque com hipotensão e turgência\njugular, sendo feito diagnóstico clínico de pneumotórax hipertensivo. A CONDUTA\nRECOMENDADA É:","options":{"A":"Antes de adotar qualquer medida terapêutica é prudente a realização de radiografia de tórax\npara confirmar o diagnóstico","B":"Deve ser encaminhado imediatamente ao bloco cirúrgico para operação, pois o quadro clássico\ninclui tamponamento cardíaco","C":"Deve ser realizado toracocentese, seguida da drenagem em selo no hemitórax comprometido.","D":"Realizar intubação orotraqueal, pois a causa é decorrente de entrada maciça de ar na cavidade\npleural, que desvia o mediastino e grandes vasos torácicos."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212164","number":"212164","sourceNumber":"212164","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de acidente motociclístico em via pública foi admitido na sala de\nemergência do pronto-socorro. O veículo estava em alta velocidade no momento do acidente e o\ncondutor usava capacete. Atendido no pré-hospitalar pelo SAMU em Glasgow 15, com pressão\narterial sistólica de 90 mmHg. Administrado, inicialmente, Ringer Lactato, 1.000 mL, com resposta\nparcial. Na sala de emergência, apresentava o seguinte exame primário: vias aéreas pérvias, sem\ncervicalgia; murmúrio vesicular presente bilateralmente, diminuído na base esquerda, enfisema\nsubcutâneo no terço inferior do hemitórax esquerdo e crepitação à palpação nesse mesmo local;\nsaturação de oxigênio 82%; pulso femoral palpável bilateralmente e simétrico, pulsos pediosos e\nradiais não palpáveis, Frequência cardíaca 130 bpm, hipocorado, ansioso, abdome distendido,\npelve estável; glasgow 13, pupilas isocóricas e fotorreagentes; dor à palpação da transição\ntoracoabdominal a esquerda. Qual o diagnóstico mais provável, suporte na sala de emergência,\nexames e o tratamento mais adequado para o paciente em questão?","options":{"A":"Trauma torácico contuso com hemo/pneumotórax, fraturas de arcos costais ? suporte de\noxigênio por cateter, drenagem de tórax à esquerda e toracotomia na sala de emergência.","B":"Trauma torácico contuso com hemo/pneumotórax e trauma abdominal contuso ? intubação\norotraqueal, drenagem de tórax à esquerda e tratamento conservador para o trauma abdominal.","C":"Trauma torácico contuso com hemo/pneumotórax, fratura de arcos costais ? suporte de oxigênio\npor máscara 15 L/min, drenagem de tórax à\nesquerda, aguardar débito dreno de tórax para definir\npróxima conduta.","D":"Trauma torácico contuso com pneumotórax, fratura de arcos costais e trauma pélvico ?\ndrenagem de tórax à esquerda, US FAST ?\nnegativo, empacotamento pélvico extra-peritoneal; US\nFAST ? positivo, laparotomia exploradora.","E":"Trauma torácico contuso com hemo/pneumotórax, fratura de arcos costais e trauma abdominal\ncontuso ? suporte de oxigênio por máscara 15 L/min, drenagem de tórax à esquerda, US FAST na\nsala de emergência para confirmar líquido livre no abdome e laparotomia exploradora."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215212","number":"215212","sourceNumber":"215212","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação à lesão primária do traumatismo cranioencefálico, assinale a alternativa\nCORRETA.","options":{"A":"Decorre de hipóxia e hipovolemia, que se instalam no momento do trauma.","B":"Decorre de hipovolemia e hipertensão arterial, que ocorrem com o processo de desaceleração\nno momento do trauma.","C":"Decorre de perda de substância cerebral, rompimento das veias e estiramento de axônios com\nruptura no momento do trauma.","D":"Decorre do impacto e das forças de aceleração e desaceleração sobre a caixa craniana e o\nencéfalo no momento do trauma."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215215","number":"215215","sourceNumber":"215215","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Das alternativas citadas abaixo, qual é o instrumento utilizado para avaliar a gravidade\nde traumatismo cranioencefálico?","options":{"A":"Escala de coma de Glasgow.","B":"Mecanismo do trauma.","C":"Escala de coma de Jouvet.","D":"Escala de Ramsay."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215217","number":"215217","sourceNumber":"215217","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quais são os sinais clínicos de hipertensão intracraniana no traumatismo\ncranioencefálico grave?","options":{"A":"Bradicardia, hipotensão arterial e taquipneia.","B":"Vômitos, papiledema e hipóxia.","C":"Bradicardia, hipertensão arterial e bradipneia.","D":"Papiledema, anisocoria e hipóxia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215229","number":"215229","sourceNumber":"215229","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao Traumatismo Cranioencefálico\n(TCE).","options":{"A":"Os programas educacionais e de informação são essenciais para a conscientização tanto dos\npais quanto das crianças na prevenção do TCE.","B":"A tomografia de crânio é o exame de eleição para avaliar lesão intracraniana.","C":"A radiografia de crânio apresenta como vantagem a identificação da lesão intracraniana.","D":"A supervisão constante e ativa por um adulto é fundamental para evitar que a criança se\nexponha a situações de risco."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215468","number":"215468","sourceNumber":"215468","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Pacientes classificados como AZUL durante a triagem das vítimas em massa são\naqueles que apresentam:","options":{"A":"Lesões que ameaçam imediatamente a vida.","B":"Lesões que requerem tratamento em 6 horas.","C":"Feridos que conseguem deambular e pacientes psiquiátricos.","D":"Lesões incompatíveis com a vida ou com os recursos."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216297","number":"216297","sourceNumber":"216297","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à avaliação ultrassonográfica\ndirecionada para o trauma (FAST).","options":{"A":"Fratura de pelve pode diminuir a acurácia do FAST.","B":"A visualização pélvica é realizada melhor antes da inserção da sonda vesical de demora.","C":"Um FAST negativo exclui lesão intra-abdominal.","D":"As ondas sonoras não se deslocam bem pelo ar, aumentando a dificuldade em realizar o FAST\nem doentes com enfisema de subcutâneo."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-201766","number":"201766","sourceNumber":"201766","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No trauma abdominal contuso o método propedêutico de melhor especificidade é?","options":{"A":"Radiografia simples de abdome.","B":"Lavado peritoneal diagnóstico.","C":"FAST.","D":"Tomografia computadorizada com contraste.","E":"Ultrassonografia de abdome total."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-201769","number":"201769","sourceNumber":"201769","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quando não devemos solicitar radiografia de tórax?","options":{"A":"Hemotórax maciço.","B":"Fratura de costelas.","C":"Pneumoperitônio.","D":"Pneumotórax hipertensivo.","E":"Contusão torácica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-201774","number":"201774","sourceNumber":"201774","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quais os princípios básicos do tratamento do choque hipovolêmico?","options":{"A":"Vias aéreas + drenagem torácica.","B":"Cessar a hemorragia + reposição volêmica.","C":"Colar cervical + prancha longa.","D":"Adrenalina + atropina.","E":"Curativo em ?3 pontas? + máscara de O2 a 15 litros."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215499","number":"215499","sourceNumber":"215499","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das alternativas abaixo NÃO é indicação de toracotomia de urgência no\nhemotórax maciço?","options":{"A":"Necessidade persistente de transfusões sanguíneas.","B":"Sangue drenado na coloração vermelho vivo.","C":"Drenagem imediata maior que 1500 ml.","D":"Drenagem acima de 200 ml por hora, por duas a quatro horas."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-201782","number":"201782","sourceNumber":"201782","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em relação à hipotensão permissiva é correto afirmar:","options":{"A":"Devemos manter o paciente hemodinamicamente normal.","B":"Repor cristalóides até a atingirmos a PAS em 120 mmHg.","C":"Utilizar 1000 ml de cristalóides, podendo repetir 1000 ml e já iniciar componentes sanguíneos.","D":"Devemos utilizar derivados sanguíneos de início, principalmente no TCE.","E":"Não devemos nos preocupar com a hipotermia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215266","number":"215266","sourceNumber":"215266","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à hemorragia classe II em pacientes\nvítimas de trauma.","options":{"A":"Em um homem de 70 kg, a perda volêmica representa de 750 a 1500 ml de sangue.","B":"Entre os sintomas clínicos estão inclusos a taquicardia (frequência cardíaca acima de 100 no\nadulto) e a taquipneia.","C":"A pressão de pulso está normal ou aumentada.","D":"Apesar das significativas alterações cardiovasculares e da perda significativa de sangue, a\ndiurese está pouco alterada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215535","number":"215535","sourceNumber":"215535","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação ao pneumotórax simples traumático, assinale a alternativa INCORRETA.","options":{"A":"Uma radiografia de tórax anteroposterior, em inspiração, pode auxiliar no diagnóstico.","B":"O murmúrio vesicular está diminuído no lado afetado e a percussão demonstra hipertimpanismo.","C":"Os doentes que apresentam pneumotórax traumático ou que tenham risco de desenvolver um\npneumotórax hipertensivo no transoperatório, não devem ser submetidos à anestesia geral ou\nventilação com pressão positiva até que tenham seu tórax drenado.","D":"Doentes com pneumotórax que necessitem de transporte aéreo também devem ser drenados\npreviamente, mesmo em cabines pressurizadas."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215197","number":"215197","sourceNumber":"215197","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Os arcos costais são os componentes da caixa torácica mais comumente lesados em\npacientes traumatizados. Assinale a alternativa INCORRETA.","options":{"A":"Os arcos costais intermediários (10-12) sofrem a maioria dos traumas fechados.","B":"A dor à movimentação resulta em restrição dos movimentos respiratórios, o que prejudica a\nventilação, a oxigenação e a tosse.","C":"Os primeiros arcos costais (1-3) são protegidos pela estrutura óssea dos membros superiores.","D":"A presença de fraturas múltiplas de arcos costais em pacientes jovens implica em uma\ntransferência de força muito maior do que em doentes mais velhos."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216274","number":"216274","sourceNumber":"216274","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação à utilização da tomografia computadorizada (TC) em pacientes vítimas de\ntrauma, assinale a alternativa INCORRETA.","options":{"A":"É um processo que consome algum tempo e, portanto, deve ser utilizado apenas em pacientes\nhemodinamicamente estáveis e que não possuem nenhuma indicação de laparotomia de\nemergência.","B":"As contraindicações absolutas para a realização da TC incluem a demora em se obter um\ntomógrafo, a falta de colaboração de um doente que não pode ser sedado com segurança e a\nalergia a contraste iodado, quando o contraste não iônico não estiver disponível.","C":"A TC pode deixar de diagnosticar algumas alterações gastrointestinais, diafragmáticas e\npancreáticas.","D":"Na ausência de lesões hepáticas ou esplênicas, a presença de líquido livre na cavidade\nabdominal sugere lesão no trato gastrointestinal e/ou no mesentério."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215201","number":"215201","sourceNumber":"215201","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"?Swing Heart? é uma alteração ecocardiográfica sugestiva de:","options":{"A":"Hipertensão pulmonar.","B":"Tamponamento cardíaco.","C":"Falência de ventrículo direito.","D":"Insuficiência mitral secundária à ruptura de cordoalha."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215481","number":"215481","sourceNumber":"215481","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quantos arcos costais devem ser fraturados (no mínimo) para que ocorra o tórax\ninstável ou retalho costal móvel?","options":{"A":"Uma.","B":"Duas.","C":"Três.","D":"Quatro."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216285","number":"216285","sourceNumber":"216285","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A contusão pulmonar pode se apresentar com uma ampla variedade de sinais clínicos\nque, frequentemente, não se correlacionam com os\nachados da radiografia de tórax. Assinale a\nalternativa INCORRETA.","options":{"A":"Doentes com enfermidades associadas, como doença pulmonar obstrutiva crônica e\ninsuficiência renal devem ter a intubação postergada pelo maior risco de ventilação mecânica\nprolongada.","B":"Doentes com hipóxia significativa devem ser intubados e ventilados já na primeira hora após a\nlesão.","C":"A contusão pulmonar é a lesão torácica potencialmente letal mais comum em portadores de\nfraturas de arcos costais.","D":"Pode ocorrer sem fraturas de arcos costais em doentes jovens com arcos costais ainda não\ncalcificados por completo."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215209","number":"215209","sourceNumber":"215209","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A ruptura traumática de aorta é causa comum de morte súbita após colisões de\nveículos automotores ou de quedas de grande\naltura. Qual das alternativas abaixo NÃO é um sinal\nradiológico que indica maior probabilidade de lesão nos grandes vasos do tórax?","options":{"A":"Rebaixamento do brônquio-fonte principal esquerdo.","B":"Desvio do esôfago (sonda nasogástrica) para esquerda.","C":"Alargamento das interfaces paraespinhais.","D":"Elevação do brônquio-fonte direito."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216327","number":"216327","sourceNumber":"216327","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Traumatismos graves e hemorragias consomem os fatores de coagulação e podem\nlevar à coagulopatia precocemente. Assinale a alternativa INCORRETA.","options":{"A":"Podem estar presentes em até 30% dos pacientes gravemente traumatizados à admissão.","B":"A transfusão maciça com diluição de plaquetas e de fatores de coagulação e os efeitos adversos\nda hipotermia na agregação plaquetária e na\ncascata da coagulação são as causas mais comuns\nde coagulopatia no doente traumatizado.","C":"As medidas do tempo de protrombina, do tempo de tromboplastina parcial e a contagem de\nplaquetas são estudos valiosos na primeira hora, especialmente no doente com história de\ncoagulopatia ou em uso de medicamentos que alterem a coagulação ou quando não há\ninformações confiáveis quanto ao seu estado prévio de coagulação.","D":"Doentes com trauma cranioencefálico grave são menos propensos ao desenvolvimento de\nanormalidades da coagulação."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216218","number":"216218","sourceNumber":"216218","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação à avaliação do paciente idoso vítima de trauma, assinale a alternativa\nINCORRETA.","options":{"A":"A indicação de transfusão de sangue deve ser a mesma dos doentes jovens.","B":"O risco para o tratamento não operatório de lesões fechadas pode ser maior do que o risco de\numa operação precoce nos\n\npacientes idosos.","C":"O doente idoso hipertenso em uso crônico de diurético poderá ter volume vascular cronicamente\naumentado e déficit de potássio sérico.","D":"Doentes geriátricos podem ser mais sensíveis à sobrecarga de volume devido à maior incidência\nde doença cardíaca."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215214","number":"215214","sourceNumber":"215214","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Os ferimentos penetrantes das extremidades podem resultar em lesões vasculares de\ngrandes artérias, assim como traumas fechados com fraturas de extremidades ou luxações\narticulares próximas a artérias também podem lesar estes vasos. Assinale a alternativa\nINCORRETA.","options":{"A":"Um hematoma em rápida expansão sugere a existência de uma lesão vascular significativa.","B":"O tratamento de hemorragia arterial grave inclui a compressão direta do ferimento e a\nreanimação agressiva com soluções apropriadas.","C":"O uso criterioso do torniquete pneumático pode ser útil e salvar a vida.","D":"Se uma fratura desalinhada está associada a um ferimento aberto com hemorragia, deve-se\nevitar o realinhamento, utilizando-se apenas\na compressão direita do ferimento."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-216240","number":"216240","sourceNumber":"216240","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação aos ferimentos encefálicos penetrantes, assinale a alternativa\nINCORRETA.","options":{"A":"Em todo ferimento penetrante do cérebro ou quando a trajetória do projétil é próxima ou através\nde um seio venoso dural maior ou a base do\ncrânio, recomenda-se a realização da angiotomografia\nou angiografia convencional.","B":"Doentes vítimas de ferimento penetrante envolvendo as regiões orbitofascial ou pterional devem\nser submetidos à angiografia para a\nidentificação de aneurisma ou fístula arteriovenosa\nintracraniana traumática.","C":"A presença de grandes contusões, hematomas ou hemorragia intraventricular identificadas pela\ntomografia, estão associadas com aumento da mortalidade, especialmente quando estão\nenvolvidos ambos os hemisférios.","D":"A monitorização precoce da pressão intracraniana (PIC) não é recomendada em pacientes que\napresentam exames de imagem sugestivos de hipertensão intracraniana."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215218","number":"215218","sourceNumber":"215218","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à Máscara Laríngea (ML).","options":{"A":"A ML não fornece uma via aérea definitiva e o posicionamento adequado deste dispositivo é\ndifícil sem treinamento apropriado.","B":"Quando um doente chegar ao departamento de emergência com a ML, o médico atendente deve\nplanejar sua substituição por uma via aérea definitiva.","C":"A ML é considerada como uma via aérea definitiva e não há necessidade de substituição\nquando um doente chegar ao departamento de\nemergência em uso deste dispositivo.","D":"É indicada para pacientes no qual a tentativa de intubação foi malsucedida, ou naqueles em que\nse sabe que dificilmente a intubação será\nconseguida."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-187819","number":"187819","sourceNumber":"187819","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"MOP, motociclista, sofreu grave acidente ao colidir sua moto contra uma mureta em alta\nvelocidade. Usava capacete aberto e apresenta importante trauma de face. Ao exame, observa-se\nrespiração ruidosa, obstrução de via aérea por sangue e dentes avulsionados. O pré-hospitalar\ninforma saturação de oxigênio de 85% mesmo com oxigênio por máscara facial a 11 litros / minuto.\nAssinale a alternativa que apresenta uma informação CORRETA em relação ao manejo das vias\naéreas no trauma:","options":{"A":"A cricotireoidostomia por punção é manobra valiosa e salvadora nestes casos, com possibilidade\nde oxigenação adequada de pacientes críticos,\nsendo considerada uma forma de via aérea segura\ne definitiva.","B":"A intubação orotraqueal apresenta contra-indicação absoluta em pacientes com trauma de face\ne obstrução de via aérea, não consistindo em\numa opção terapêutica neste caso","C":"A intubação orotraqueal pode ser tentada por médico experiente, e em caso de insucesso,\npassa-se imediatamente a uma via aérea cirúrgica,\nsendo a cricotireoidostomia cirúrgica uma opção\nde via aérea definitiva.","D":"A máscara laríngea é a primeira opção de manejo de via aérea neste caso, uma vez que é\npossível realizar o seu posicionamento ás cegas, tem boa capacidade de oxigenação e protege a\nvia aérea de uma possível aspiração."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-180152","number":"180152","sourceNumber":"180152","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente vítima de contusão abdominal é levado à laparotomia de emergência.\nDurante a exploração cirúrgica, constata-se a\npresença de uma transecção completa do corpo do\npâncreas, à esquerda dos vasos mesentêricos. A melhor\n\nconduta, nesse caso, deve ser realizar:","options":{"A":"Cateterização do Wirsung com drenagem","B":"Pancreatectomia corpo-caudal","C":"Desbridamento pancreático","D":"Pancreatorrafia","E":"NDA"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181383","number":"181383","sourceNumber":"181383","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual a melhor conduta cirúrgica a ser tomada em Paciente vítima de ferimento por\narma branca, com lesão de 45% da circunferência do cólon transverso estável\nhemodinamicamente, após 2 horas do momento do trauma?","options":{"A":"Rafia primária da lesão.","B":"Colectomia segmentar a estoma proximal.","C":"Ressecção segmentar e anastomose primária.","D":"Rafia primária e colostomia proximal protetora.","E":"Confecção de fístula mucosa no local da lesão."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183110","number":"183110","sourceNumber":"183110","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Atualmente tem sido descrito o uso de soluções salinas hipertônicas, como NaCL 3%,\npara o tratamento do edema cerebral originário de várias situações clínicas agudas. O mecanismo\nde efeito da solução hipertônica seria:","options":{"A":"Remoção de água do tecido cerebral pela hiperosmolaridade induzida em pacientes com\nbarreira sangue-cérebro intactas.","B":"Indução de diurese osmótica como ocorre com o manitol.","C":"Equilíbrio osmótico entre os compartimentos intracelular e extracelular.","D":"Bloqueio do peptídeo natriurético."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-180121","number":"180121","sourceNumber":"180121","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das seguintes afirmações sobre trauma pediátrico no Brasil é verdadeira?","options":{"A":"Traumas relacionados aos veículos a motor somam menos de 10% de todas as lesões\npediátricas que resultam em óbito.","B":"Acidentes de transito é a principal causa de óbito em crianças e adolescentes de 1 a 14 anos","C":"capacetes de proteção para bicicleta não reduzem a gravidade da maioria dos traumatismos\ncrânioencefálicos\n\nrelacionados a bicicleta","D":"a maioria dos óbitos relacionados ao fogo ocorrem nas escolas","E":"o uso de equipamentos de contenção não reduziram os óbitos na faixa etária menor de 7 anos"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182725","number":"182725","sourceNumber":"182725","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Levando-se em consideração um paciente com Traumatismo Crânio Encefálico (TCE),\nassinale a alternativa CORRETA:","options":{"A":"Papiledema se presente, confirma o diagnóstico de hipertensão intracraniana, porém pode estar\nausente nos casos agudos.","B":"Recomenda-se manter a pressão de perfusão cerebral em crianças com TCE em torno de\n90mmHg.","C":"A monitorização da pressão intracraniana é recomendada quando lactentes e crianças\napresentam-se com escala de coma de Glasgow de 15.","D":"A hiperventilação (PCO2 < 30mmHg) é recomendada como medida de rotina nos casos de TCE\ngrave"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183577","number":"183577","sourceNumber":"183577","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de TCE apresentando abertura ocular ao chamado, emitindo sons\nincompreensíveis e obedecendo a comandos verbais como resposta motora. Qual é o escore de\nGlasgow do paciente?","options":{"A":"8 pontos.","B":"9 pontos.","C":"10 pontos.","D":"11 pontos."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182808","number":"182808","sourceNumber":"182808","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa que corresponde à lesão da figura.","options":{"A":"Hematoma Subdural.","B":"Hematoma Extradural.","C":"Hematoma Intraparenquimatoso.","D":"Lesão Axonal Difusa."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/182808.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182812","number":"182812","sourceNumber":"182812","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"É INCORRETO afirmar sobre o Hematoma Subdural Agudo que","options":{"A":"apresenta-se na tomografia computadorizada como uma imagem hiperdensa em crescente.","B":"o comprometimento cerebral subjacente costuma ser mais grave devido à presença de lesão\nparenquimatosa concomitante.","C":"a apresentação clínica clássica é o intervalo lúcido, no qual o paciente encontra-se acordado e,\ndepois de minutos ou horas, pode evoluir para o coma.","D":"ocorrem mais frequentemente por dilaceração de vasos superficiais pequenos ou vasos ponte\ndo córtex cerebral."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183075","number":"183075","sourceNumber":"183075","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São indicações para ventilação mecânica no tórax instável, EXCETO","options":{"A":"Frequência respiratória maior que 35 irpm.","B":"PaO2 < 60 mmHg com FiO2>0,5.","C":"Fratura de mais de 8 costelas.","D":"PaCo2 > 50 mmHg com FiO2 >0,5."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183599","number":"183599","sourceNumber":"183599","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente masculino de 49 anos, vítima de acidente automobilístico ocorrido há 45\nminutos, estava em uso de cinto de segurança,\napresenta-se consciente, dispneico; com ausência\nde MV e macicez em todo hemitórax direito, ausculta cardíaca sem alterações, quanto aos sinais\nvitais apresentava: FR = 38 irpm, FC = 120 bpm, PA = 110x60 mmHg. Qual é a principal hipótese\ndiagnóstica?","options":{"A":"Hemotórax à direita.","B":"Pneumotórax à direita.","C":"Tamponamento cardíaco.","D":"Ruptura brônquica à direita."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183080","number":"183080","sourceNumber":"183080","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São sinais radiográficos sugestivos de lesão aórtica, EXCETO","options":{"A":"desvio do brônquio fonte esquerdo para cima.","B":"obliteração do cajado aórtico.","C":"apagamento da janela aortopulmonar.","D":"hemotórax à esquerda."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183100","number":"183100","sourceNumber":"183100","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a Hipertensão Intracraniana é INCORRETO que","options":{"A":"a pressão intracraniana normal é entre 10 mmHg e 15 mmHg.","B":"sintomas de hipertensão intracraniana são cefaleia, vômitos e diminuição no nível de\nconsciência.","C":"sinais de hipertensão intracraniana incluem papiledema, paralisia dos nervos cranianos e a\ntríade de Cushing.","D":"a tríade de Cushing é composta por hipertensão, bradicardia e rebaixamento do nível da\nconsciência."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183107","number":"183107","sourceNumber":"183107","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A abordagem de emergência indicada para todos os pacientes com sinais clínicos de\nherniação inclui todos abaixo, EXCETO","options":{"A":"elevação da cabeceira à 30 graus.","B":"hidantalização.","C":"posição neutra da cabeça.","D":"manitol intravenoso (1 a 2g/kg)."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182770","number":"182770","sourceNumber":"182770","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Fazem parte dos componentes do controle de danos ou reanimação hemostática todos\nabaixo, EXCETO","options":{"A":"hipertônica.","B":"hemoderivados precoce.","C":"hipotermia permissiva.","D":"minimizar uso de cristaloides"},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183077","number":"183077","sourceNumber":"183077","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A esternotomia transversa proporciona acesso bilateral à cavidade pleural. Para\nprevenir a perda sanguínea relacionada a essa\nincisão, deve-se realizar a ligadura, em ambos os\nlados da artéria","options":{"A":"torácica lateral.","B":"mamária interna.","C":"pericardiofrênica.","D":"epigástrica superior."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182815","number":"182815","sourceNumber":"182815","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"É INCORRETO sobre a lesão traumática abaixo, que","options":{"A":"o intervalo lúcido entre o momento da lesão e a deteriorização neurológica é apresentação\nclássica.","B":"são relativamente raros, ocorrendo em 0,5% de todos os pacientes com trauma\ncrânio-encefálico.","C":"esses coágulos, em geral, ocorrem por dilaceração de vasos ponte do córtex cerebral.","D":"estão mais frequentemente localizados na região temporal ou temporoparietal."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/182815.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183625","number":"183625","sourceNumber":"183625","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A tríade de Beck é caracterizada por:","options":{"A":"hipotensão, abafamento de bulhas e turgência jugular.","B":"hipertensão, bradicardia e turgência jugular.","C":"hipertensão, abafamento de bulhas e depressão respiratória.","D":"hipertensão, bradicardia e depressão respiratória."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183094","number":"183094","sourceNumber":"183094","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 70 anos, masculino, tabagista 40 anos/maço, admitido no Pronto-socorro\ndo hospital com queixa de dor torácica em\nhemitórax direito, de início súbito, e dispneia ao repouso.\nAo exame físico, taquipneico, taquicárdico, cianose de extremidades e PA=120X80 mmHg. No\nexame do tórax, apresentava diminuição do murmúrio vesicular à direita e frêmito toracovocal\nreduzido ipsilateralmente, frequência respiratória de 32 irpm, SatO2 de 80%. Solicitado RX de tórax,\ndemonstrou discreto pneumotórax à direita (15%). Qual é a melhor conduta para o caso acima?","options":{"A":"Acompanhamento clínico.","B":"Punção pleural.","C":"Toracotomia.","D":"Drenagem pleural."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183627","number":"183627","sourceNumber":"183627","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das alternativas a seguir é uma indicação de toracotomia no traumatismo de\ntórax?","options":{"A":"Fratura de arco costal.","B":"Pneumotórax hipertensivo.","C":"Ferimento transfixante de mediastino.","D":"Hemotórax com drenagem superior a 1500 ml pelo dreno de tórax."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183632","number":"183632","sourceNumber":"183632","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Segundo as diretrizes brasileiras de Ventilação Mecânica, é INCORRETO a respeito do\ntrauma torácico que","options":{"A":"a ventilação não invasiva está contraindicada nos pacientes com lesão das vias aéreas\nsuperiores.","B":"pacientes com trauma torácico devem ser ventilados com volume corrente de 10ml/kg de peso\npredito, frequência respiratória entre 16 a 20 rpm, fração inspirada de oxigênio suficiente para\nmanter saturação periférica de oxigênio maior que 92% e PEEP entre 5 e 10 cmH2O.","C":"em pacientes com trauma torácico isolado, a aplicação precoce da ventilação não invasiva é\ncapaz de melhorar as trocas gasosas.","D":"deve-se intubar e ventilar prontamente pacientes com trauma torácico grave."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182810","number":"182810","sourceNumber":"182810","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A ilustração correponde à lesão traumática renal grau","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/182810.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183604","number":"183604","sourceNumber":"183604","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"É INCORRETO sobre a ruptura de aorta traumática que","options":{"A":"a incidência de ruptura é maior na aorta ascendente.","B":"são mais comuns em trauma fechado.","C":"menos de 20% dos pacientes com ruptura de aorta descendente chegam vivos ao hospital.","D":"mais de 30% dos que chegam a ter atendimento hospitalar têm possibilidade de morrer nas seis\nprimeiras horas."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182818","number":"182818","sourceNumber":"182818","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A laceração envolvendo vasos segmentares ou hilares produzindo importante\ndesvascularização (> 25% do baço) é considerada como de grau","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-182735","number":"182735","sourceNumber":"182735","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a síndrome compartimental abdominal é INCORRETO afirmar que,","options":{"A":"na síndrome compartimental, a pressão venosa central e a pressão capilar pulmonar diminuem.","B":"são formas de tratamento posição supina, ressuscitação com cristaloides criteriosa, sedação,\ndrenagem de conteúdos intraluminares.","C":"a pressão abdominal normal varia de subatmosférica a 5 mmH e flutua com a respiração, índice\nde massa corporal e atividade.","D":"a síndrome compartimental secundária pode ocorrer após o sangramento de uma lesão de\nextremidade e/ou quando a reposição volêmica maciça for necessária."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161225","number":"161225","sourceNumber":"161225","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação ao pneumotórax traumático simples, assinale a alternativa INCORRETA:","options":{"A":"Todo pneumotórax é melhor tratado com inserção de um dreno de tórax no quarto ou quinto\nespaço intercostal, anteriormente à linha axilar\nmédia. A observação e a aspiração do pneumotórax\nassintomático podem ser apropriadas, mas a escolha deve ser feita por um médico qualificado.","B":"Os doentes, que apresentam pneumotórax traumático ou que tenham risco de desenvolver um\npneumotórax hipertensivo no\n\ntransoperatório, não devem ser submetidos à anestesia geral ou à ventilação com pressão positiva\naté que tenham seu tórax drenado.","C":"Na presença de pneumotórax, o murmúrio vesicular está diminuído do lado afetado e a\npercussão demonstra macicez.","D":"Um pneumotórax simples pode transformar-se prontamente em um pneumotórax hipertensivo\ncom risco à vida, particularmente quando seu\ndiagnóstico não é feito desde o início e o doente é\nsubmetido à ventilação com pressão positiva."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161232","number":"161232","sourceNumber":"161232","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à toracotomia de reanimação no trauma\ntorácico.","options":{"A":"Os doentes com trauma fechado, que chegam sem pulso, mas com atividade elétrica\nmiocárdica, são candidatos à toracotomia de reanimação na sala de emergência.","B":"É essencial que se proceda a intubação orotraqueal e a ventilação mecânica em todo paciente\nsubmetido à toracotomia de reanimação.","C":"Os doentes que chegam com lesão torácica penetrante sem pulso, porém, com atividade elétrica\nmiocárdica, podem ser candidatos à toracotomia na sala de emergência.","D":"A toracotomia de reanimação no serviço de emergência raramente é eficiente em doentes que\nsofreram traumatismo fechado e apresentam parada cardíaca."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161242","number":"161242","sourceNumber":"161242","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação ao tamponamento cardíaco, aponte a alternativa INCORRETA.","options":{"A":"O pneumotórax hipertensivo, particularmente à esquerda, pode mimetizar o tamponamento\ncardíaco.","B":"Os métodos diagnósticos adicionais incluem o ecocardiograma, ultrassonografia direcionada\npara o trauma (FAST) e a janela pericárdica.","C":"O FAST apresenta uma acurácia de 90-95% para presença de líquido no saco pericárdico\nquando realizado por profissional experiente.","D":"O tamponamento cardíaco é identificado pela presença da clássica tríade diagnóstica de Beck:\nelevação da pressão venosa, aumento da pressão arterial e abafamento de bulhas cardíacas."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161253","number":"161253","sourceNumber":"161253","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das alternativas abaixo NÃO corresponde a um achado do exame físico em um\npaciente com hemotórax maciço?","options":{"A":"Desvio de traqueia.","B":"Macicez à percussão.","C":"Veias do pescoço sem distensão.","D":"Abafamento de bulhas cardíacas."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161267","number":"161267","sourceNumber":"161267","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quanto aos hematomas subdurais nos traumas, aponte a alternativa INCORRETA.","options":{"A":"São mais comuns que os hematomas epidurais, ocorrendo em aproximadamente 30% dos TCEs\ngraves.","B":"Ocorrem mais frequentemente por dilaceração de vasos superficiais pequenos ou vasos ponte\ndo córtex cerebral.","C":"O comprometimento cerebral subjacente ao hematoma subdural é mais leve do que nos\nhematomas epidurais.","D":"Frequentemente parecem assumir a forma do contorno do cérebro na tomografia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161143","number":"161143","sourceNumber":"161143","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente vítima de TCE é encontrada desacordada. Após 10 minutos, apresenta\nabertura ocular aos estímulos dolorosos,\ndecorticação como melhor resposta motora, emitindo sons\nincompreensíveis. Diante desse quadro, podemos AFIRMAR que seu Glasgow é:","options":{"A":"6.","B":"7.","C":"8.","D":"9."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161274","number":"161274","sourceNumber":"161274","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em um paciente vítima de traumatismo craniencefálico, que deu entrada no\n\nPronto-socorro apresentando abertura ocular somente ao estímulo doloroso, sons incompreensíveis\nna resposta verbal e flexão anormal\n(decorticação) como melhores respostas, qual é o Glasgow\ndeste paciente?","options":{"A":"6","B":"7","C":"8","D":"9"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161148","number":"161148","sourceNumber":"161148","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quilotórax ocorre quando a linfa do ducto torácico se acumula no espaço pleural.\nAssinale a alternativa INCORRETA em relação ao seu diagnóstico e tratamento.","options":{"A":"O diagnóstico pode ser feito com toracocentese ou drenagem do derrame quiloso. Análise do\nlíquido pleural com presença de quilomicrons confirma o diagnóstico.","B":"Dieta de triglicerídeo de cadeia média ou NPT são indicados inicialmente.","C":"Causas de quilotórax incluem traumas de tórax e pescoço fechados e penetrantes,\npós-cateterismo de veia subclávia, linfoma, mediastinite, simpatectomia.","D":"Ligadura do ducto torácico no ponto onde no tórax através do hiato diafragmático é obtida\natravés de toracotomia esquerda ou toracoscopia."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161303","number":"161303","sourceNumber":"161303","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quanto aos hematomas epidurais traumáticos, aponte a alternativa INCORRETA.","options":{"A":"São relativamente raros, ocorrendo em 0,5% de todos os doentes com trauma craniencefálico e\nem 9% dos doentes com lesão cerebral traumática e que estão em coma.","B":"Esses hematomas tipicamente adquirem a forma biconvexa ou lenticular à medida que\nempurram a dura aderente em direção oposta à da tábua interna do crânio.","C":"O intervalo lúcido é a apresentação clássica do hematoma epidural.","D":"Estão localizados mais frequentemente na região frontal e habitualmente resultam da ruptura da\nartéria meníngea média causada por uma fratura."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161166","number":"161166","sourceNumber":"161166","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A toracotomia de reanimação é um procedimento clássico de controle de danos. Depois\nde abrir o tórax, apenas cinco manobras\ndevem ser feitas. Qual das alternativas NÃO faz parte da\ntoracotomia de reanimação?","options":{"A":"Torcer o pulmão que tenha sangramento maciço.","B":"Seccionar o ligamento pulmonar inferior.","C":"Fazer massagem cardíaca interna.","D":"Isolamento da veia inominada."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161169","number":"161169","sourceNumber":"161169","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O FAST é uma ferramenta para avaliação rápida do traumatizado. Sobre as janelas de\nexame, assinale a alternativa INCORRETA.","options":{"A":"Iniciar pela janela pericárdica.","B":"A visualização do quadrante superior direito é feita com corte sagital na linha axilar média.","C":"A visualização suprapúbica é feita com um corte sagital, com melhor observação quando a\nbexiga ainda não estiver sondada.","D":"As estruturas a serem visualizadas no quadrante superior esquerdo são diafragma, baço e o rim."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-158739","number":"158739","sourceNumber":"158739","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente jovem, vítima de acidente automobilístico há menos de 1 hora, admitido em\nPS com PA de 80 x 60 mmHg, fc de 120 bpm e\ntaquipneia. É identificado um pneumotórax à direita,\nsendo feita a drenagem torácica em selo d?água, observando fuga aérea. Após infusão de 2000\nmL de cristaloide, o quadro clínico está inalterado e o paciente mantém exame físico de\npneumotórax à direita. Depois de não constatar erro no sistema de drenagem nem no exame físico\ne a radiografia no leito revelar pneumotórax maciço, qual a suspeita?","options":{"A":"Barotrauma.","B":"Tórax instável.","C":"Ruptura de esôfago.","D":"Ruptura de brônquio.","E":"Lesão diafragmática."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161370","number":"161370","sourceNumber":"161370","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Muitos fatores estão envolvidos na decisão de operar ou não um doente com\nhemotórax, os mais importantes são o estado\nfisiológico do doente e o volume de sangue eliminado\npelo dreno de tórax. Como conduta normativa, a exploração cirúrgica deve ser considerada sempre\nque a drenagem inicial for igual a:","options":{"A":"1.500 mL de sangue, ou 500 mL/h durante 2 a 4 horas.","B":"1.500 mL de sangue, ou 200 mL/h durante 2 a 4 horas.","C":"1.000 mL de sangue, ou 200 mL/h durante 2 a 4 horas.","D":"1.000 mL de sangue, ou 300 mL/h durante 2 a 6 horas."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161230","number":"161230","sourceNumber":"161230","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Fazem parte dos passos da toracotomia de reanimação, com EXCEÇÃO de","options":{"A":"Seccionar o ligamento pulmonar inferior.","B":"Fazer massagem cardíaca interna.","C":"Clampear a aorta torácica.","D":"Abertura do diafragma para exploração abdominal."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161378","number":"161378","sourceNumber":"161378","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Diante de um paciente politraumatizado, com dor torácica, dispneia, ausência de\nexpansibilidade torácica unilateral e um ferimento toracoaspirativo em parede torácica, indique a\nalternativa que MELHOR corresponde ao tratamento inicial, sequencialmente.","options":{"A":"Toracocentese em segundo espaço intercostal, curativo oclusivo, drenagem pleural fechada em\nsexto espaço intercostal anteriormente à linha axilar média.","B":"Curativo de três pontas, toracocentese em segundo espaço intercostal, toracotomia exploradora.","C":"Curativo de três pontas, toracocentese em segundo espaço intercostal, drenagem pleural\nfechada em sexto espaço intercostal anteriormente à linha axilar média.","D":"Curativo de três pontas, drenagem pleural fechada em sexto espaço intercostal anteriormente à\nlinha axilar média."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161402","number":"161402","sourceNumber":"161402","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito da avaliação do sistema sensorial nos pacientes com trauma\nvertebromedular, aponte a alternativa que\ncorresponde ao segmento do nervo espinhal inervada\npela face medial da perna.","options":{"A":"T10","B":"T12","C":"L4","D":"L5"},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161404","number":"161404","sourceNumber":"161404","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O traumatismo contuso da cabeça e do pescoço é um fator de risco para lesões da\nartéria carótida e vertebral. O reconhecimento\ne tratamento precoce dessas lesões podem reduzir o\nrisco de acidente vascular cerebral. As indicações para investigação são amplas, mas os critérios\nsugeridos para investigação incluem, EXCETO:","options":{"A":"As fraturas de C1 ? C3.","B":"As fraturas cervicais com subluxação.","C":"As fraturas envolvendo o forame transverso.","D":"A fratura de Chance."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161153","number":"161153","sourceNumber":"161153","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Nesta tarde durante uma emergência respiratória que ocorreu na enfermaria, você foi\nobrigado utilizar uma cânula nasofaríngea devido ao fato de não ter outra disponível no carrinho de\nemergência, pois tinha sido utilizada em outra emergência. A respeito disso, assinale a alternativa\nconsiderada INADEQUADA.","options":{"A":"A cânula nasofaríngea pode ser utilizada para facilitar a realização de ventilações torácicas com\no dispositivo bolsa-válvula-máscara.","B":"A cânula nasofaríngea pode ser utilizada em pacientes com obstrução das vias aéreas ou para\naqueles com risco de desenvolver obstrução das vias aéreas, em pacientes com impossibilidade de\nreceber uma cânula orofaríngea.","C":"Na presença ou suspeita de fratura de base de crânio ou coagulopatia grave, deve-se optar pela\ncânula nasofaríngea.","D":"Existem cânulas nasofaríngeas de diferentes tamanhos. Para a escolha do tamanho adequado,\nbasta medir a distância entre a extremidade\ndo nariz e o lobo da orelha. Esta distância indica\naproximadamente o comprimento da via aérea nasofaríngea."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-152637","number":"152637","sourceNumber":"152637","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 40 anos, sexo masculino, vítima de acidente automobilístico com duas\nfraturas costais bilateral. Apresenta dispneia\nintensa, PA: 90/ 50 mmHg e volumoso enfisema\nsubcutâneo nas regiões torácica, cervical, abdominal, bolsa escrotal e na face. Rx de tórax mostra\npneumomediastino com pulmões expandidos (ausência de pneumotórax). Qual a conduta?","options":{"A":"Toracotomia com drenagem fechada do mediastino.","B":"Toracotomia com drenagem fechada da cavidade\n\npleural, unilateral e no hemitórax que apresentar maior volume de enfisema subcutâneo.","C":"Tratamento conservador.","D":"Toracotomia exploradora e rafia do brônquio.","E":"NDR."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-152643","number":"152643","sourceNumber":"152643","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo feminino, 50 anos, vítima de acidente automobilístico. Apresenta tórax\ninstável decorrente de múltiplas fraturas de arcos costais bilateral. Ao ser admitida na UTI,\napresenta insuficiência respiratória. Rx de tórax mostra pulmões não expandidos. Portadora de\ndrenagem torácica bilateral. Qual a conduta imediata na admissão da UTI?","options":{"A":"Cirurgia imediata com fixação dos arcos costais.","B":"Oxigenioterapia sob máscara e analgesia rigorosa.","C":"Entubação orotraqueal mantendo em ventilação\nmecânica.","D":"Colocação de mais um dreno de tórax em cada lado, posicionando-os no 1/ 3 superior.","E":"NDR."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161387","number":"161387","sourceNumber":"161387","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em relação ao Traumatismo Cranioencefálico (TCE), considere estas assertivas. I. O\nTCE na infância é a principal causa de\nmorte e invalidez na faixa etária abaixo de 12 anos de idade,\nsendo, nesse grupo, responsável por até 75% das mortes no Brasil.; II. Aproximadamente 60% dos\npacientes que sobrevivem a TCE apresentam sequelas graves, com deficit motor e cognitivo.; III.\nOs traumas intencionais, caracterizados pela recorrência das lesões, podem passar\ndesapercebidos em até um terço das vezes. As assertivas CORRETAS estão contidas em:","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-161394","number":"161394","sourceNumber":"161394","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa CORRETA quanto à escala de coma de Glasgow (ECG), no\natendimento inicial de pacientes com Traumatismo Cranioencefálico (TCE):","options":{"A":"A escala de coma de Glasgow avalia a abertura ocular, a melhor resposta motora e a melhor\nresposta neurológica.","B":"A partir da pontuação da escala de coma de Glasgow, classifica-se o TCE quanto à gravidade,\nem leve (ECG 3 a 8), moderado (ECG 9 a 13) e\ngrave (ECG 14 e 15).","C":"A Glasgow Outcome Scale vai do grau 1 ao 5, indicando, respectivamente, boa recuperação,\nincapacidade moderada, incapacidade grave, estado vegetativo e óbito.","D":"As crianças devem ser admitidas na UTI pediátrica se apresentarem ECG > 12."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134832","number":"134832","sourceNumber":"134832","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Atualmente, a escala neurológica mais utilizada para avaliação neurológica é a Escala\nde Coma de Glasgow, pois ela se mostra\nadequada à avaliação de Traumatismo Craniano. Dessa\nforma, podemos considerar INADEQUADO","options":{"A":"Definir necessidade de manobras de reanimação cardiorrespiratória.","B":"Definir necessidade de manejo de vias aéreas.","C":"Indicar a incapacidade de proteção de via aérea por parte do paciente.","D":"Indicar gravidade do traumatismo craniano."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134821","number":"134821","sourceNumber":"134821","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente deu entrada na sala de emergência trazido por corpo de bombeiros, foi\nencontrado desacordado na beira de um morro, bastante alcoolizado e sujo. Não se sabe se\ncaiu de altura ou não. Exame físico demonstra Glasgow de 8, hálito etílico intenso, pupilas\nanisocóricas, dificuldade respiratória com FR de 40 i/min. Qual das alternativas abaixo parece MAIS\nadequada ?","options":{"A":"Inicialmente fazer exame de glicemia capilar e repor glicose para tentar evitar entubar.","B":"Indicada manejo de via aérea pelo estado de coma, independente de estar alcoolizado ou não.","C":"Somente indicar manejo de via aérea caso não melhore após tratamento.","D":"O fato de estar anisocórico indica manejo de via aérea pelo TCE."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134270","number":"134270","sourceNumber":"134270","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A perfusão tissular no paciente chocado é MELHOR avaliada através do seguinte\nparâmetro. Indique-o.","options":{"A":"Pressão venosa central.","B":"Diurese horária.","C":"Pressão arterial.","D":"Hematócrito."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134082","number":"134082","sourceNumber":"134082","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Entende-se hipovolemia por um volume de sangue menor do que o normal, e que pode\nocorrer","options":{"A":"por perda de sangue total, plasma, água e sal, e dissecação.","B":"somente por perda de sangue total.","C":"às vezes por perda de sangue, água e sal.","D":"duas acima estão certas."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134280","number":"134280","sourceNumber":"134280","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O Choque, por definição, é uma condição fisiopatológica reconhecida como um estado\ncaracterizado por","options":{"A":"Perfusão tecidual adequada.","B":"Perfusão tecidual inadequada.","C":"Labilidade hormonal.","D":"Excesso de aporte hídrico."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134105","number":"134105","sourceNumber":"134105","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com história de traumatismo torácico grave com suspeita de tamponamento\ncardíaco. Assinale a CORRETA.","options":{"A":"A tríade de Beck não faz parte dessa patologia.","B":"Hiperfonese aparece em 50% dos casos.","C":"Sua evolução é o choque séptico","D":"A hipotensão pode estar presente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134286","number":"134286","sourceNumber":"134286","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quais dos hormônios abaixo estão aumentados no pós-trauma?","options":{"A":"Insulina, ADH e ACTH.","B":"Cortisol, catecolaminas e insulina.","C":"Insulina, catecolaminas e aldosterona.","D":"ADH, cortisol e catecolaminas."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134290","number":"134290","sourceNumber":"134290","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Na terapia do choque hemorrágico, o MELHOR indicador clínico de reposição de\nvolume eficaz é","options":{"A":"O aumento da diurese.","B":"O aumento da oxigenação arterial.","C":"A diminuição da taquicardia.","D":"O aumento da pressão arterial."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134121","number":"134121","sourceNumber":"134121","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São causas de obstrução das vias aéreas no trauma, EXCETO uma das listadas\nabaixo. Indique-a.","options":{"A":"?Queda? da língua por rebaixamento do nível de consciência.","B":"Desidratação.","C":"Aspiração de sangue, conteúdo gástrico ou corpos estranhos.","D":"Hematomas cervicais."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134278","number":"134278","sourceNumber":"134278","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A função celular de um paciente com síndrome de choque severo está alterada em\ndecorrência de:","options":{"A":"Diminuição do sódio circulante.","B":"Hiperpotassemia.","C":"Alteração do mecanismo de transporte da membrana celular.","D":"Aumento do magnésio circulante."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134890","number":"134890","sourceNumber":"134890","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Jovem de 22 anos sofre pancada violenta na cabeça. Segundo testemunhas, o\npaciente ficou inconsciente por 10 minutos e\nfoi trazido ao Pronto Socorro por Paramédicos com\nimobilização da coluna cervical. Ao exame clínico, apresenta ventilação aparentemente\nnormal, frequência respiratória de 18/min, pressão arterial de 130 x 70 mmHg e pulso de 80/min.\n\nAbre os olhos aos estímulos dolorosos, mas não ao comando de voz. Encolhe-se com estímulo\ndoloroso. A resposta verbal é de sons\nincompreensíveis. Tem contusão na região temporal direita.\nPupila direita com fotorreação lenta e 6 mm de diâmetro. Pupila esquerda tem 4 mm de diâmetro e\nreação normal à luz. Não há otorragia. Em se tratando de um traumatismo craniano e considerando\na escala de coma de Glasgow, qual deve ser o próximo passo?","options":{"A":"Tomografia computadorizada de crânio.","B":"Intubação orotraqueal para controle da ventilação e oxigenação.","C":"Retirar o colar cervical.","D":"Bipar o Neurologista ou Neurocirurgião."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134812","number":"134812","sourceNumber":"134812","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação à causa de Abdome Agudo Hemorrágico, a MENOS provável é","options":{"A":"Laceração do fígado + baço no trauma.","B":"Gravidez ectópica rota.","C":"Úlcera perfurada + diverticulite aguda.","D":"Laceração do mesentério no trauma."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-131344","number":"131344","sourceNumber":"131344","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 40 anos, sexo masculino, vítima de acidente automobilístico, com duas\nfraturas costais bilateral. Apresenta dispneia\nintensa, PA: 90/ 50 mmHg e volumoso enfisema\nsubcutâneo nas regiões torácica, cervical, abdominal, bolsa escrotal e na face. Rx de tórax mostra\npneumomediastino com pulmões expandidos (ausência de pneumotórax). Qual a conduta?","options":{"A":"Toracotomia com drenagem fechada do mediastino.","B":"Toracotomia com drenagem fechada da cavidade pleural, unilateral e no hemitórax que\napresenta\n\nmaior volume de enfisema subcutâneo.","C":"Tratamento conservador.","D":"Toracotomia exploradora e ráfia do brônquio.","E":"NDR."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-131374","number":"131374","sourceNumber":"131374","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Ocorrendo ferimento vascular de extremidade na via pública. Qual a sua conduta?","options":{"A":"Não faz nada.","B":"Clampeamento com hemostática.","C":"Compressão digital.","D":"Chamar o bombeiro.","E":"Pedir sangue."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-131391","number":"131391","sourceNumber":"131391","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No diagnóstico do choque hemorrágico, qual o melhor parâmetro?","options":{"A":"Respiração ruidosa.","B":"Palidez e frieza da pele, e diminuição do nível de consciência.","C":"Desmaio.","D":"Arroxeamento das extremidades.","E":"Gasometria."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-131396","number":"131396","sourceNumber":"131396","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No atendimento inicial ao traumatizado, a medida mais importante é:","options":{"A":"Controle da hemorragia.","B":"Tipar e administrar sangue.","C":"Assegurar o acesso venoso.","D":"Assegurar a permeabilidade de vias aéreas (respiração).","E":"Chamar o cirurgião."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-131406","number":"131406","sourceNumber":"131406","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A escala de Glasgow, (resposta a estímulos verbais, sensitivos e motores), pode\navaliar:","options":{"A":"O coração.","B":"As pernas.","C":"A gravidade do traumatismo crânio-encefálico.","D":"O pulmão.","E":"A gravidade do trauma raqui-medular."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-109988","number":"109988","sourceNumber":"109988","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"NÃO deve ser passada a sonda nasogástrica às cegas, em casos de:","options":{"A":"Queimaduras extensas.","B":"Volvo de sigmoide.","C":"Gastrectomia parcial.","D":"Esofagite por soda cáustica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-362514","number":"362514","sourceNumber":"362514","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 28 anos de idade, profissional da construção civil, é\natendido no pronto socorro após queda de\nlaje há cerca de 3 horas, queixando dor abdominal. O\npaciente é hígido, sem comorbidades e nega uso crônico de medicações ou drogas. Ao exame\nfísico, o paciente apresenta-se em BEG, discretamente hipocorado, FR: 22irpm, FC: 90bpm e P.A.:\n100x70mmHg. Apresenta vias aéreas livres e ausculta torácica sem alterações. Apresenta extensa\nescoriação tóraco-abdominal à esquerda e dor à palpação abdominal. O FAST foi positivo para\nlíquido no hipocôndrio esquerdo. Foi realizada expansão volêmica com 500ml de ringer lactato, o\nque estabilizou seus sinais vitais. Hematócrito 30% e Hemoglobina 10g/dl. Foi submetido a\ntomografia computadorizada com contraste venoso e observada laceração esplênica de 5cm, sem\nextravasamento de contraste, com líquido livre periesplênico em moderada quantidade. Sobre o\ncaso descrito acima, assinale a alternativa CORRETA:","options":{"A":"A tomografia evidencia lesão esplênica grave com sangue intra-cavitário, estando indicada a\nesplenectomia de urgência.","B":"Uma vez que o choque hemorrágico aumenta consideravelmente a morbimortalidade no trauma\nabdominal, a melhor conduta para o caso seria a embolização arterial da lesão previamente a\nesplenectomia.","C":"Já que o paciente estabilizou após a ressuscitação volêmica e não foi transfundido, a conduta de\nmenor morbidade para o caso neste momento é a esplenectomia laparoscópica.","D":"A transferência para a Unidade de Terapia Intensiva ou Semi-intensiva, para monitorização\ncontínua, acompanhamento dos níveis de hemoglobina e\nhematócrito, repetição da tomografia\napós 48 horas e tentativa de tratamento não cirúrgico é viável para este paciente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-362509","number":"362509","sourceNumber":"362509","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 24 anos, é trazido ao pronto socorro por terceiros devido a\nferimento por arma branca no tórax. O paciente é admitido desacordado, bradipneico e pálido, com\nlesão traumática identificada em precórdio. Realizada monitorização de emergência, foi identificada\nFC: 50bpm e P.A: 60x30mmHg. O exame físico evidenciou, ainda, distensão de veias jugulares,\nmurmúrio vesicular fisiológico bilateralmente e abafamento de bulhas cardíacas. Sobre o caso,\nassinale a alternativa INCORRETA:","options":{"A":"Este tipo de ferimento atinge mais frequentemente o ventrículo direito.","B":"Uma vez avaliado o mecanismo do trauma e identificada a tríade de Beck, o próximo passo para\ndiagnóstico é a tomografia de tórax com contraste endovenoso.","C":"Apesar de haver sangramento de volume variável, o choque grave apresentado pelo paciente é\nclassificado como obstrutivo.","D":"Há indicação precisa de toracotomia de emergência, frequentemente realizada ainda, na sala do\natendimento inicial."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-362507","number":"362507","sourceNumber":"362507","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Você foi convidado para discutir o desfecho insatisfatório de um caso clínico de um\npaciente politraumatizado. O paciente, do sexo masculino, 60 anos, hipertenso e diabético, foi\nvítima de agressão física com trauma torácico e abdominal contuso e fratura exposta de fémur,\napresentando sinais clinicos de choque grave, sendo inicialmente submetido a ressuscitação com\nringer lactato e volumosa hemotransfusão. O tratamento definitivo das lesões compreendeu\ndrenagem fechada de tórax por hemopneumotórax, laparotomia exploradora com hepatorrafia\ndevido a extensa laceração hepática e desbridamento cirúrgico com estabilização do foco de\nfratura. O paciente foi transferido para a UTI para cuidados intensivos, porém evoluiu com\npneumonia, infecção no foco de fratura, sepse e óbito após 14 dias. A respeito das implicações\nimunológicas referentes ao caso acima, assinale a alternativa INCORRETA:","options":{"A":"Há disfunção endotelial relacionada ao trauma e perda sanguínea, com liberação de fatores\nmoleculares associados ao trauma (DAMPs) que resultam em ativação do complemento e do\nsistema imune celular, resultando em grande produção de citocinas, inflamação sistémica e lesão\ntecidual à distância.","B":"O ácido tranexâmico, frequentemente indicado em pacientes em estado de choque hemorrágico\npor trauma, parece ter efeito imunomodulador\npela inibição da fibrinólise e menor ativação do\ncomplemento.","C":"Durante a SIRS, caso se compensem as comorbidades existentes, o idoso traumatizado passa a\nter o mesmo prognóstico de pacientes jovens expostos a trauma e perda sanguínea.","D":"Antibioticoprofilaxia, evitar o uso de colóides sintéticos à base de amido na ressuscitação\nvolêmica e o uso restritivo de concentrado de\nhemácias provavelmente diminuiriam os efeitos da\nSIRS neste paciente."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-362465","number":"362465","sourceNumber":"362465","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Escolar de 9 anos, sexo masculino, é admitido no serviço de emergência após acidente\nautomobilístico torporoso e pouco reativo aos estímulos. Ao exame físico: dor em hemitórax direito,\nFC 150 bpm, PA 110 x 70 mmHg, enchimento capilar 3,5 segundos. Após garantir a permeabilidade\nda via aérea, aporte de oxigênio e observado diurese de 0,2 ml/kg/h, deve-se administrar:","options":{"A":"Solução salina hipertônica 3% - 10 ml/hg.","B":"Concentrado de hemácias 10 ml/kg.","C":"Solução salina isotônica 0,9% - 20 ml/kg.","D":"Albumina 5% - 2 ml/kg."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-362443","number":"362443","sourceNumber":"362443","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Escolar de 8 anos, sexo masculino, sofreu acidente de bicicleta. Ao ser atendido na via\npública, queixava de dor no ombro esquerdo e respondia as solicitações do médico do serviço de\nurgência móvel. Na admissão escolar apresenta quadro de choque, sendo a etiologia mais\nprovável:","options":{"A":"Ruptura de aorta descendente.","B":"Ruptura de pâncreas.","C":"Ruptura de fígado.","D":"Ruptura de baço."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-327249","number":"327249","sourceNumber":"327249","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 23 anos, é vítima de agressão física após assalto em\nregião periférica da cidade, é trazido ao\npronto atendimento em estado grave. Durante a avaliação\ninicial, o paciente se encontra com nível de consciência bastante rebaixado, apresentando lesões\ncontusas em face e crânio, com coluna cervical sem degraus ou crepitação à palpação. O paciente\napresenta FR: 30 irpm e seu tórax também apresenta lesões contusas em ambos os hemitórax,\nalém de orifício de ferimento por arma de fogo à direita (entrada em parede anterior e saída em\nparede posterior). Palpa-se enfisema subcutâneo nessa região e o murmúrio vesicular é bastante\ndiminuído nesse hemitórax. O paciente se encontra hipocorado ++/4, com FC: 92bpm e P.A.: 90 x\n60mmHg. Não se observa sangramentos externos. FAST negativo. Neste momento, o paciente\napresenta abertura ocular ao estímulo de pressão, não responde ao comando verbal e apresenta\nresposta motora com localização de estímulo, além de ausência de reflexo pupilar a estímulo, além\nde ausência de reflexo pupilar a estímulo luminoso à direita. Membros superiores sem\ndeformidades. Bacia estável. Coxa esquerda aumentada de volume com encurtamento e rotação\nexterna do membro. Sobre as condutas iniciais a serem tomadas neste paciente, assinale a\nalternativa INCORRETA:","options":{"A":"Há indicação de obtenção de via aérea definitiva neste paciente, porém uma vez que o trauma\nde face pode dificultar a intubação\norotraqueal, tal obstáculo pode ser minimizado através do uso\nda videolaringoscopia.","B":"Já que o paciente foi admitido em choque grau III ocasionado pelo trauma torácico e fratura de\nfêmur direito, provavelmente haverá indicação de transfusão de concentrado de hemácias e\nadministração de ácido tranexâmico a despeito da reposição volêmica com 1.000ml de Ringer\nLactato.","C":"Para o diagnóstico do possível hemopneumotórax deste paciente, a execução do E-FAST é\npreferencial à realização da radiografia de tórax.","D":"Visto que o paciente apresenta 8 pontos na Escala de coma de Glasgow e anisocoria, há\nindicação de tomografia de crânio logo após a estabilização hemodinâmica e ventilatória deste\n\npaciente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-327252","number":"327252","sourceNumber":"327252","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Policial 32 anos, vítima de ferimento por arma de fogo em tórax durante troca de tiros\ncom traficantes, é atendido por você em um Pronto Socorro com equipe multiprofissional treinada\npara o trauma e bons recursos diagnósticos. O paciente apresenta orifício de entrada a nível do 7º\nespaço intercostal direito, sem orifício de saída. Ao exame físico, apresenta-se em BEG,\ndiscretamente dispneico e taquicárdico, normotenso. A ausculta torácica revela diminuição do\nmurmúrio vesicular à direita. Apresenta, ainda, dor abdominal de leve intensidade à palpação\nprofunda, sem sinais de irritação peritoneal. A radiografia de tórax evidenciou moderado derrame\npleural associado a pneumotórax com comprometimento de 50% da expansão pulmonar. Sobre o\ncaso descrito, qual a conduta mais adequada?","options":{"A":"A conduta mais segura para o caso é a toracotomia associada a laparotomia para controle de\nsangramento de vísceras maciças, já que todo ferimento de alto impacto em região\n\ntóraco-abdominal é cirúrgico.","B":"Drenagem fechada de tórax à direita e realização de tomografia de abdome; em caso de\nevidência de lesão hepática sem demais\nlesões viscerais, pode-se tentar o tratamento conservador.","C":"Toracocentese à direita e FAST abdominal para avaliação da provável lesão hepática associada\ne em caso de resultado positivo para sangue\nna cavidade peritoneal, proceder laparotomia.","D":"Drenagem fechada de tórax à direita e realização de tomografia de abdome; em caso de\ndiagnóstico de qualquer lesão visceral, proceder laparoscopia terapêutica."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298192","number":"298192","sourceNumber":"298192","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Para o tratamento das hemorragias maciças que se seguem aos politraumatismos, a\nconduta hemoterápica imediata consiste em realizar transfusão de:","options":{"A":"Crioprecipitado, seguida de transfusão de concentrados de hemácias.","B":"Sangue total fresco.","C":"Solução de cristaloides ou coloides e transfusão de concentrados de hemácias.","D":"Concentrados de hemácias, plasma e concentrado de plaquetas, na proporção de uma bolsa de\ncada tipo de hemocomponente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298216","number":"298216","sourceNumber":"298216","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 18 anos, é trazido por familiares ao pronto atendimento\ndevido a queda de árvore há 1 hora. Queixa\ncontusão abdominal durante a queda e nega trauma\ncraniano e torácico. Suas vias aéreas são livres e a coluna cervical é indolor à palpação. O tórax\nnão apresenta lesões externas, mas é doloroso à palpação na transição tóraco-abdominal à\nesquerda, onde se observa extensa escoriação. Murmúrio vesicular fisiológico bilateralmente. O\npaciente se encontra alerta, FC: 100bpm, FR: 24irpm. P.A.: 120x80mmHg. A inspeção abdominal\nrevela áreas de contusão em flanco direito e FIE. A palpação evidencia dor difusa, sem sinais de\nirritação peritoneal. A mobilização da bacia era indolor. Não havia sinais de trauma craniano ou\ncomprometimento neurológico. Membros sem deformidades. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"As lesões descritas acima são suficientes para indicação de laparotomia exploradora imediata\nsem necessidade de investigação complementar.","B":"Já que o exame físico abdominal é inconclusivo e alterado devido a contusão torácica, a\nradiografia de abdome será útil na\ndeterminação de lesões de vísceras maciças intra-abdominais.","C":"A ultrassonografia é capaz de avaliar lesões pancreáticas traumáticas mesmo com amilase\nsérica normal.","D":"A tomografia, se disponível na unidade de atendimento, seria bem indicada para avaliação do\ntrauma abdominal deste paciente por possibilitar o diagnóstico de ar ou líquido livre na cavidade\nperitoneal, lesões de órgãos maciços e de órgãos retroperitoneais."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-286727","number":"286727","sourceNumber":"286727","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 22 anos, vítima de queda de motocicleta (relato de\nacidente em alta velocidade), é trazido ao\npronto socorro por terceiros, com importante escoriação\nem cabeça e tórax. Não usava capacete. É atendido na sala de trauma inconsciente e bastante\ndispneico (FR: 32irpm), taquicárdico, hipotenso, com turgência jugular bilateral e desvio de\ntraquéia\npara a esquerda. Ao exame do tórax, observamos discreto abaulamento em hemitórax direito, com\naparente hipertimpanismo e murmúrio vesicular abolido. Hemitórax esquerdo sem alterações.\n\nAssinale a alternativa INCORRETA:","options":{"A":"Há indicação de intubação orotraqueal preferencialmente guiada por videolaringoscopia, neste\ncaso.","B":"A drenagem fechada de tórax deverá ser realizada imediatamente, preferencialmente com\ndrenos calibrosos de 36 a 38F.","C":"A provável presença de choque obstrutivo indica punção com cateter calibroso no 5º. espaço\nintercostal, a nível da linha axilar média.","D":"O eFAST pode facilmente diagnosticar um pneumotórax neste caso."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252234","number":"252234","sourceNumber":"252234","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Chega um paciente masculino de 42 anos em seu consultório com quadro de há 3\nmeses ter sido vítima de traumatismo\ncranioencefálico. A irmã conta que ele estava dirigindo com\ncapacete e que em um cruzamento, um carro atravessou o sinal vermelho e o colidiu lateralmente.\nA irmã refere que ele foi levado pelo SAMU em coma, dando entrada no Hospital João Lúcio. A\nirmã entregou o relatório de alta que dizia: ?Paciente deu entrada no dia 28/03/2019 em Glasgow 6,\ncom pupilas mióticas, instável hemodinamicamente. Foi feito laparotomia exploradora devido lesão\nde baço, sendo feito esplenectomia. Avaliação neurocirúrgica: TC sem afecções neurocirúrgicas.\n\nSem conduta neurocirúrgica?. Ficou 30 dias na UTI, onde foi feita traqueostomia e gastrostomia.\nRecebe alta hoje, dia 05/05/17, com abertura\nocular espontânea, anisocoria esquerda maior que\ndireita, não fixa olhar e apresenta menos movimentos à direita. Ferida operatória abdominal sem\nsinais flogísticos?. Hoje, dia 28/06/2019, você avalia o paciente e ele está em cadeira de rodas,\ncontactuando verbalmente, mas com fala arrastada. Ele refere lentificação do pensamento, perda\nde memória para fatos recentes, diplopia quando olha para esquerda, dificuldade para deambular e\nsonolência excessiva. No exame físico você constata leve anisocoria esquerda maior que direita,\nfala escandida e dupla hemiparesia espástica com predomínio à direita. O paciente está fazendo\nuso de fenitoína 200 mg/dia. Qual o diagnóstico mais provável?","options":{"A":"Mielopatia cervical traumática.","B":"Hematoma epidural.","C":"Hemorragia meníngea traumática.","D":"Lesão axonal difusa."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252235","number":"252235","sourceNumber":"252235","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de ferimento por arma de fogo em hipocôndrio direito. Foi submetido a\nlaparotomia com identificação de lesão hepática grave. O cirurgião realizou uma manobra para\ndiminuir o sangramento, clampeando o hilo hepático. Quais estruturas foram clampeadas?","options":{"A":"Ducto cístico, colédoco e artéria hepática.","B":"Colédoco, vesícula e veia porta.","C":"Colédoco, veia porta e artéria hepática.","D":"Veia porta, ducto cístico e artéria hepática."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252243","number":"252243","sourceNumber":"252243","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Nos traumas abdominais fechados de alta energia, qual órgão sólido mais\ncomprometido?","options":{"A":"Baço","B":"Fígado","C":"Rim","D":"Adrenal"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-252244","number":"252244","sourceNumber":"252244","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A musculatura abdominal é uma importante barreira de defesa dos órgãos cavitários.\nTrauma de alto impacto pode causar hematoma\nna bainha do reto abdominal. Qual sinal podemos\nencontrar?","options":{"A":"Fox","B":"Fothergill","C":"Flasher","D":"Mcburney"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208314","number":"208314","sourceNumber":"208314","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considera-se Via Aérea Definitiva:","options":{"A":"Cricotireoidotomia","B":"Máscara Laríngea","C":"Ventilação Transtraqueal Percutânea","D":"Instalação da Cânula de Guedel"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208320","number":"208320","sourceNumber":"208320","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com Trauma Crânio Encefálico, apresenta abertura ocular a comandos\nverbais, responde com palavras inapropriadas e\nlocaliza dor; tem o escore na Escala de Coma de\nGlasgow:","options":{"A":"10","B":"9","C":"11","D":"12"},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208340","number":"208340","sourceNumber":"208340","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A Tríade de Beck é encontrada:","options":{"A":"Tamponamento Cardíaco","B":"Colangite","C":"Tumor de Pulmão (Pan Cost)","D":"Aneurisma Dissecante de Aorta Abdominal"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208368","number":"208368","sourceNumber":"208368","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Marcelo, 19 anos é admitido no Pronto-Socorro com relato de acidente motociclístico,\ncom instabilidade hemodinâmica. Apresenta do\npélvica e uretrorragia. Ao Raio X - fratura de bacia e\nna uretrocistografia foi evidenciado ruptura completa da uretra anterior. A melhor conduta urológica\na ser tomada é:","options":{"A":"Cistostomia por punção e reconstrução uretral posterior","B":"Cateterismo Vesical com sonda de Foley, antes de qualquer procedimento mais invasivo","C":"Cirurgia imediata com anastomose término-terminal dos cotos uretrais por via supra pública","D":"Cirurgia imediata com anastomose término-terminal dos cotos uretrais por via perineal"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208417","number":"208417","sourceNumber":"208417","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, é vítima de atropelamento em via pública e\ntrazido ao pronto atendimento por terceiros.\nA admissão, refere não conseguir respirar\nadequadamente além de apresentar considerável dor torácica. Ao exame físico, observa-se marca\nde pneu sobre o tórax, com respiração de padrão paradoxal. A palpação do hemitórax direito é\nbastante dolorosa, identificando-se áreas com crepitações. O murmúrio vesicular é diminuído à\ndireita. FC: 100 bpm, FR: 30 irpm, P.A.: 130 x 90 mmHg. Sem sangramentos externos. FAST\nnegativo. Glasgow 15 pts, pupilas isocóricas, sem déficits neurológicos periféricos. Bacia e\nmembros sem alterações ao exame físico. Assinale a alternativa CORRETA:","options":{"A":"A drenagem fechada do hemitórax direito reestabelecerá a dinâmica respiratória adequada deste\npaciente.","B":"Os dados fornecidos acima nos permitem afirmar que há indicação de toracotomia para a\ncorreção da lesão pulmonar presente.","C":"Analgesia potente, suplementação de O2 e possível necessidade de entubação orotraqueal\ndevem fazer parte do tratamento deste paciente.","D":"Uma vez que o padrão respiratório descrito acima é secundário a choque hemorrágico, a\nressuscitação volêmica com solução salina é\nsuficiente para compensar sua frequência respiratória."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-208365","number":"208365","sourceNumber":"208365","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"João, escolar de 07 anos, sexo masculino, é admitido no serviço de emergência após\nacidente automobilístico. Na admissão está torporoso e pouco reativo aos estímulos. Ao exame\nfísico: dor em hemotórax direito, FC 160 bpm, PA 110 X 70 mmHg, enchimento capilar 3,5\nsegundos e diurese 0,2 ml/kg/h. Após garantir a permeabilidade da via aérea e o aporte de\noxigênio, devo administrar:","options":{"A":"Solução isotônica 0,9% endovenosa 20 ml/kg.","B":"Sangue 10 ml/kg.","C":"Solução coloide 20 ml/kg.","D":"Albumina 5% - 2 ml/kg."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-176087","number":"176087","sourceNumber":"176087","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, 19 anos, vítima de atropelamento em via pública, é trazido\nao centro de trauma queixando muita dor\ntorácica e dificuldade para respirar. Ao exame físico,\napresenta vias aéreas livres e coluna cervical indolor, sem degraus à palpação. Está bastante\ndispneico (FR: 28 irpm) e exibe exuberante escoriação, com marca de pneu, em hemitórax direito,\npodendo ser observada respiração de padrão paradoxal. Múltiplas crepitações e bastante dor à\npalpação do hemitórax direito, com murmúrio vesicular diminuído à direita. Saturação de O2 = 88%\nem ar ambiente. Não se evidencia sangramentos externos. FAST negativo. Glasgow = 15 pts.,\npupilas isocóricas, sem deficit neurológicos. Bacia estável. Escoriações em membros inferiores,\nsem deformidades. Assinale a alternativa INCORRETA:","options":{"A":"Suporte de O2 e analgesia potente podem estabilizar o quadro ventilatório do paciente.","B":"Anestesia peridural pode evitar a necessidade de intubação orotraqueal deste paciente.","C":"Provavelmente observaremos retalho costal não articulado secundário a múltiplas fraturas de\ncostela, à radiografia de tórax.","D":"A observação de contusão pulmonar extensa concomitante à avaliação radiológica indica\ndrenagem fechada de tórax."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-151872","number":"151872","sourceNumber":"151872","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente do sexo masculino, aproximadamente 20 anos, é trazido ao pronto-socorro\npelo SAMU, vítima de acidente automobilístico\n(passageiro do banco da frente do veículo). Não\nusava cinto de segurança. Encontra-se imóvel na maca, com nível de consciência rebaixado e\nexuberante trauma de face e região frontal, com presença de sangramento abundante em cavidade\noral, escoriações e deformidade em região malar e mandibular, com crepitação à palpação nessas\nregiões. Saturação de O? 85%. Pupilas anisocóricas, com midríase à direita. Seu tórax é estável,\nmas apresenta equimose à esquerda, com crepitação à palpação e diminuição importante do\nmurmúrio vesicular. FC: 110 bpm, P.A. 100 X 90 mmHg. FAST negativo. Não abre os olhos, não\nemite sons e retira o membro ao estímulo doloroso. Bacia estável. Deformidade na coxa direita e\ndemais membros sem deformidades. Sobre a condução adequada deste caso, assinale a\nalternativa CORRETA:","options":{"A":"A segunda prioridade após o estabelecimento de via aérea definitiva é a avaliação tomográfica\nde trauma craniano grave deste paciente.","B":"A primeira prioridade deste paciente é a manutenção da via aérea, estando indicadas manobras\nde retificação das mesmas, aspiração da cavidade\noral e intubação orotraqueal.","C":"Devido ao trauma torácico fechado com suspeita de hemopneumotórax, há necessidade de\nradiografia de tórax para confirmação diagnóstica e posterior drenagem fechada em selo d'água.","D":"Os dados acima nos permitem afirmar que o paciente apresenta choque hipovolêmico grau III,\njustificado pelo sangramento da face, provável hemotórax e fratura de fêmur, estando indicada\nressucitação volêmica inicial com solução salina."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-151984","number":"151984","sourceNumber":"151984","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um aluno no Internato Rural de Medicina em Parintins é chamado pela enfermeira para\navaliar um paciente que foi vítima de ferimento penetrante por arma de fogo em hemitórax direito há\n1 dia, sendo atendido no pronto socorro e submetido a drenagem fechada de tórax em selo d'água.\nA enfermeira tem dúvidas porque refere que, apesar de haver oscilação do dreno, esta observou\nborbulhamento intenso de ar no frasco de drenagem. O débito líquido nas últimas 24h foi de 200 ml\nde secreção serossanguinolenta. O Interno ausculta o paciente e observa diminuição do murmúrio\nvesicular do hemitórax drenado. Não havia enfisema subcutâneo. Sobre o caso acima, assinale a\nalternativa CORRETA:","options":{"A":"Os dados expostos acima são suficientes para indicar a retirada do dreno torácico e alta do\npaciente.","B":"Sob a hipótese de pneumotórax residual, a conduta adequada é clampear o dreno e encaminhar\no paciente para radiografia de tórax.","C":"Pela possibilidade de fístula aérea de alto débito, deve ser avaliada a possibilidade de se\ninserir\num segundo dreno no mesmo hemitórax.","D":"Provavelmente o alto débito de fuga aérea se dá devido ao baixo gradiente de pressão do frasco\ndo dreno, estando indicada a elevação do\nfrasco acima do nível do leito do paciente."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-139134","number":"139134","sourceNumber":"139134","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Difícil de ser avaliado, o déficit de paciente cirúrgico que necessita transfusão\nsanguínea para a estabilização do volume\nsanguíneo; em cenário que um adulto sadio que\napresentou uma perda de 15 a 30 % do seu volume sanguíneo, associada a taquicardia e pressão\nde pulso diminuída, mas mantendo uma pressão arterial normal, é classificada como hemorragia do\ntipo:","options":{"A":"classe I.","B":"classe II.","C":"classe III.","D":"classe IV."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-103831","number":"103831","sourceNumber":"103831","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A Síndrome Compartimental Abdominal (SCA), pode ocorrer nas citações abaixo,\nEXCETO:","options":{"A":"cisto anexais volumoso.","B":"acúmulo súbito de ascite.","C":"distensão abdominal por gases.","D":"edema intestinal excessivo."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-103837","number":"103837","sourceNumber":"103837","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com hipotensão, distensão das veias do pescoço e pulso paradoxal ocorrida\napós trauma do tórax contra o volante em\nacidente automotivo. Achados são sugestivos de:","options":{"A":"tamponamento cardíaco","B":"pneumotórax","C":"hemotórax","D":"contusão miocárdica"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-107721","number":"107721","sourceNumber":"107721","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de ferimento abdominal por arma de fogo foi submetido à laparotomia\nexploradora que evidenciou lesão transfixante de estômago, explosão esplênica com hemorragia\nprofusa e lesão do diafragma esquerdo, sendo realizada a gastrorrafia, esplenectomia, frenorrafia e\ndrenagem fechada de tórax à esquerda. A paciente fez uso de cefalosporina de primeira geração\nprofilática, ressuscitação volêmica com ringer lactato e analgesia. No primeiro dia pós-operatório\napresentava-se pálido, discretamente dispneico, taquicárdico e normotenso, com urina bastante\nconcentrada e volume reduzido. Sobre possíveis condutas adicionais e eventos relacionados ao\npós-operatório, marque a alternativa INCORRETA:","options":{"A":"Devido à gravidade do caso, havia indicação precisa de reposição de glicose, sódio e potássio\nna hidratação do pós-operatório imediato.","B":"Podemos inferir que, devido ao jejum prolongado secundário ao procedimento cirúrgico e\nrecuperação pós-operatória, as catecolaminas\ncirculantes bloqueiam a ação periférica da insulina\nno intuito de manter os níveis glicêmicos normais.","C":"O paciente apresenta oligúria devido à ação da aldosterona nos túbulos renais distais e do\nhormônio antidiurético, em resposta à provável\nhipovolemia não plenamente tratada deste paciente.","D":"Podemos inferir que o débito cardíaco deste paciente está sendo mantido as custas de aumento\nda resistência vascular periférica e aumento da\nfrequência cardíaca mediada pela adrenalina e\nnoradrenalina."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-107733","number":"107733","sourceNumber":"107733","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"As alternativas abaixo expressam achados clínicos presentes tanto no pneumotórax\nhipertensivo quanto no tamponamento cardíaco, EXCETO:","options":{"A":"Aumento da pressão venosa central.","B":"Desvio traqueal.","C":"Hipoperfusão periférica.","D":"Choque obstrutivo."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-294468","number":"294468","sourceNumber":"294468","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU ao pronto-socorro do\nHospital Geral, vítima de queda de moto há 20 minutos. Paciente dá entrada com colar cervical e\nprancha rígida, referindo dor em ombro direito, em região escapular direita e em abdome. No\nexame inicial, A: via aérea pérvia, mantido colar cervical, SatO?: 97% com cateter de O? 15 L/min;\nB: murmúrios vesiculares bem distribuídos e sem ruídos adventícios, FR: 18 irpm; C: bulhas\nrítmicas e normofonéticas, FC: 88 bpm, PA: 122 x 72 mmHg, abdome com dor à palpação,\nprincipalmente, em hipocôndrio direito, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de escoriações em tórax.\nDiante desse caso clínico... Indique a conduta terapêutica mais adequada, caso o exame\ncomplementar não apresente sinais de sangramento ativo e o paciente mantenha o mesmo quadro\nclínico.","options":{"A":"Realizar laparotomia exploradora.","B":"Fazer transfusão de O? concentrados de hemácias e Transamin endovenoso.","C":"Manter em observação e seriar Hb/Ht e exame físico.","D":"Realizar arteriografia e embolização."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-354409","number":"354409","sourceNumber":"354409","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem, 20 anos de idade, é trazido pelo SAMU ao Pronto-Socorro, vítima de queda de\ncerca de cinco metros há uma hora. Paciente dá entrada com colar cervical e prancha rígida,\nreferindo dor em região pélvica. No exame inicial, A. via aérea pérvia, SatO?: 88% com cateter de\nO? 15L/min; B. murmúrios vesiculares bem distribuídos e sem ruídos adventícios, FR: 28ipm; C.\nbulhas rítmicas e normofonéticas, FC: 132bpm, PA: 82x52mmHg, abdome indolor, pelve com\nmovimentação da sínfise púbica à palpação e toque retal sem alterações; D. escala de coma de\nGlasgow=13, pupilas isocóricas e fotorreagentes; E. presença de equimose em períneo e sangue\nem meato uretral. Realizado FAST: sem líquido livre em cavidade abdominal. Radiografias série\ntrauma evidenciaram fratura no púbis bilateral e disjunção sacroilíaca direita. Após a reanimação\ninicial, o paciente manteve o mesmo padrão hemodinâmico. Identifique a conduta imediata a ser\nrealizada:","options":{"A":"Tomografia computadorizada de abdome com contraste.","B":"Laparotomia exploradora.","C":"Tamponamento cirúrgico extraperitoneal e fixação externa da pelve.","D":"Urografia excretora."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-354410","number":"354410","sourceNumber":"354410","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem, 20 anos de idade, é trazido pelo SAMU ao Pronto-Socorro, vítima de queda de\ncerca de cinco metros há uma hora. Paciente dá entrada com colar cervical e prancha rígida,\nreferindo dor em região pélvica. No exame inicial, A. via aérea pérvia, SatO?: 88% com cateter de\nO? 15L/min; B. murmúrios vesiculares bem distribuídos e sem ruídos adventícios, FR: 28ipm; C.\nbulhas rítmicas e normofonéticas, FC: 132bpm, PA: 82x52mmHg, abdome indolor, pelve com\nmovimentação da sínfise púbica à palpação e toque retal sem alterações; D. escala de coma de\nGlasgow=13, pupilas isocóricas e fotorreagentes; E. presença de equimose em períneo e sangue\nem meato uretral. Realizado FAST: sem líquido livre em cavidade abdominal. Radiografias série\ntrauma evidenciaram fratura no púbis bilateral e disjunção sacroilíaca direita. Indique o exame\ncomplementar que deve ser realizado para complementar a avaliação do paciente quanto a lesões\ndo aparlho urn'rio baixo:","options":{"A":"Tomografia computadorizada do abdome com contraste.","B":"Uretrocistografia retrógrada.","C":"Cistoscopia endoscópica.","D":"Videolaparoscopia diagnóstica."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-294466","number":"294466","sourceNumber":"294466","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU ao pronto-socorro do\nHospital Geral, vítima de queda de moto há 20 minutos. Paciente dá entrada com colar cervical e\nprancha rígida, referindo dor em ombro direito, em região escapular direita e em abdome. No\nexame inicial, A: via aérea pérvia, mantido colar cervical, SatO?: 97% com cateter de O? 15 L/min;\nB: murmúrios vesiculares bem distribuídos e sem ruídos adventícios, FR: 18 irpm; C: bulhas\nrítmicas e normofonéticas, FC: 88 bpm, PA: 122 x 72 mmHg, abdome com dor à palpação,\nprincipalmente, em hipocôndrio direito, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de escoriações em tórax.\nDiante desse caso clínico... indique a principal suspeita diagnóstica que justifique o quadro\nclínico\ndo paciente.","options":{"A":"Trauma esplênico.","B":"Trauma renal direito.","C":"Trauma hepático.","D":"Trauma de pâncreas."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-294467","number":"294467","sourceNumber":"294467","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU ao pronto-socorro do\nHospital Geral, vítima de queda de moto há 20 minutos. Paciente dá entrada com colar cervical e\nprancha rígida, referindo dor em ombro direito, em região escapular direita e em abdome. No\nexame inicial, A: via aérea pérvia, mantido colar cervical, SatO?: 97% com cateter de O? 15 L/min;\nB: murmúrios vesiculares bem distribuídos e sem ruídos adventícios, FR: 18 irpm; C: bulhas\nrítmicas e normofonéticas, FC: 88 bpm, PA: 122 x 72 mmHg, abdome com dor à palpação,\nprincipalmente, em hipocôndrio direito, pelve estável e toque retal sem alterações; D: escala de\ncoma de Glasgow = 15, pupilas isocóricas e fotorreagentes; E: presença de escoriações em tórax.\nDiante desse caso clínico... Identifique o exame complementar mais adequado que pode auxiliar na\nconfirmação do diagnóstico.","options":{"A":"Tomografia computadorizada de abdome com contraste.","B":"Avaliação com ultrassonografia focada para o trauma (FAST).","C":"Videolaparoscopia.","D":"Radiografia de abdome."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-284578","number":"284578","sourceNumber":"284578","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU, vítima de trauma\nmoto x anteparo em via expressa há 30\nminutos. Dá entrada no Pronto Socorro com colar cervical e\nprancha rígida, referindo dor em hemitórax direito e falta de ar. Ao exame, A: Via aérea pérvia,\nmantido colar cervical, SatO2: 84% com cateter de O2 15L/min; B: murmúrios vesiculares\ndiminuídos com crépitos em hemitórax direito, FR: 36ipm; C: Bulhas rítmicas e normofonéticas, FC:\n98bpm, PA: 122x76mmHg, abdome indolor á palpação, pelve estável e toque retal sem alterações;\nD: escala de coma de Glasgow= 13, pupilas isocóricas e fotorreagentes; E: escoriações e dor à\npalpação em hemitórax direito. Foi realizado radiografia de tórax na sala de emergência. Indique os\nprincipais achados na radiografia que justifiquem o quadro clínico desse paciente.","options":{"A":"Pneumotórax e fratura de costelas.","B":"Fratura de costelas e contusão pulmonar.","C":"Desvio de mediastino e pneumotórax.","D":"Alargamento cardíaco e do mediastino."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/284578.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-284579","number":"284579","sourceNumber":"284579","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo masculino, 20 anos de idade, é trazido pelo SAMU, vítima de trauma\nmoto x anteparo em via expressa há 30\nminutos. Dá entrada no Pronto Socorro com colar cervical e\nprancha rígida, referindo dor em hemitórax direito e falta de ar. Ao exame, A: Via aérea pérvia,\nmantido colar cervical, SatO2: 84% com cateter de O2 15L/min; B: murmúrios vesiculares\ndiminuídos com crépitos em hemitórax direito, FR: 36ipm; C: Bulhas rítmicas e normofonéticas, FC:\n98bpm, PA: 122x76mmHg, abdome indolor á palpação, pelve estável e toque retal sem alterações;\nD: escala de coma de Glasgow= 13, pupilas isocóricas e fotorreagentes; E: escoriações e dor à\npalpação em hemitórax direito. Foi realizado radiografia de tórax na sala de emergência. Indique a\nconduta terapêutica imediata mais adequada nesse caso.","options":{"A":"Toracostomia com drenagem em selo d'água.","B":"Intubação orotraqueal com ventilação mecânica assistida.","C":"Pericardiocentese de alívio.","D":"Reposição volêmica com solução cristaloide 2000mL."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/284579.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-249996","number":"249996","sourceNumber":"249996","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Jovem de 19 anos, vítima de acidente automobilístico de alto impacto é trazido em\nprancha rígida e colar cervical após 40 min\ntrauma. Há relato de ejeção do veículo e grande\ndeformidade do automóvel. Durante atendimento pré-hospitalar foi administrado 1000ml de ringer\nlactato aquecido e 1g de ácido tranexâmico. É admitido em sala de emergência com vias aéreas\npérvias, de colar cervical. Ao exame físico pulmonar: escoriação em hemitórax esquerdo, ausculta\nabolida a esquerda, hipertimpânico, com estase jugular. Bulhas normofonéticas. Pressão arterial:\n80x40 mmHg, Frequência cardíaca: 125 bpm, saturação de oxigênio periférico: 82%, frequência\nrespiratória: 38 irpm. Glasgow 13, pupilas isocóricas, sem déficits focais aparentes. Pelve fechada.\nExame físico abdominal normal. Assinale a alternativa sequencial correta, preconizada pelo\nAdvanced Trauma Life Support (ATLS) 10ª edição, por ordem de execução.","options":{"A":"Ofertar oxigênio, drenagem de tórax, lavado peritoneal diagnóstico.","B":"Punção de alívio em segundo espaço intercostal, na linha médio-clavicular, seguida de\ndrenagem de tórax.","C":"Punção de alívio em segundo espaço intercostal, na linha médio clavicular, seguida de\ncolocação de um dreno pig tail.","D":"Punção de alívio em quinto espaço intercostal esquerdo, descompressão manual, seguido de\ndrenagem torácica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-215603","number":"215603","sourceNumber":"215603","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Pacientes vítimas de traumatismos cranioencefálicos classificados como gravidade\nmoderada apresentam qual faixa de escore na escala de coma de Glasgow?","options":{"A":"13-15.","B":"9-12.","C":"9-13.","D":"3-8."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181186","number":"181186","sourceNumber":"181186","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Dos exames relacionados abaixo, qual não deve ser realizado de rotina no paciente\nafogado?","options":{"A":"Medida da pressão arterial.","B":"Eletroencefalograma.","C":"Controle do sensório.","D":"Gasometria."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181195","number":"181195","sourceNumber":"181195","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São medidas de prevenção de afogamento todas as abaixo, EXCETO:","options":{"A":"Sempre valorizar a sua capacidade de nadar, evitando o uso de coletes que possam dificultar o\nseu deslocamento durante a prática de esportes\nnáuticos.","B":"Sempre supervisionar crianças pequenas.","C":"Investir em equipamentos de proteção ? redes, grades, alarmes.","D":"Ensinar lições de natação a partir de um ano."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181147","number":"181147","sourceNumber":"181147","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em relação ao afogamento, assinale a alternativa correta:","options":{"A":"Em áreas com salva-vidas os afogamentos são mais graves pela confiança que as pessoas tem\nde avançar em áreas mais profundas.","B":"Pessoas sem treinamento devem tentar atendimento ao afogado dentro da água.","C":"Compressões torácicas devem ser realizadas apenas em terra.","D":"Imobilizações cervicais devem ser feitas de rotina em pacientes afogados."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181171","number":"181171","sourceNumber":"181171","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Na avaliação do paciente com suspeita de morte encefálica e potencial doador (vontade\njá manifestada pela família) devemos realizar,\nEXCETO:","options":{"A":"Exame físico e história da doença atual.","B":"Tomografia computadorizada de abdome.","C":"História pregressa e história social.","D":"Teste de apneia."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181177","number":"181177","sourceNumber":"181177","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual é a lesão específica no traumatismo craniano, onde o quadro clínico cursa\nclassicamente com uma breve perda de consciência seguida por um intervalo de lucidez?","options":{"A":"Hematoma Epidural.","B":"Hematoma Subdural.","C":"Hematoma Intrparenquimatoso.","D":"Hemorragia Subaracnóidea."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-181179","number":"181179","sourceNumber":"181179","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"São medidas que podem ser aplicadas para o tratamento da Hipertensão Intracraniana\nno Traumatismo Craniano, EXCETO:","options":{"A":"Elevação da cabeceira.","B":"Sedação Profunda.","C":"Solução Salina Hipertônica.","D":"Corticóides."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157583","number":"157583","sourceNumber":"157583","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o trauma vértebro-medular, indique a opção INCORRETA.","options":{"A":"As Fraturas de Chance são fraturas transversas no corpo vertebral, causadas por flexão sobre\num eixo anterior à coluna.","B":"A Fratura de Jefferson consiste na ruptura anterior e posterior do anel do atlas, por sobrecarga\naxial.","C":"Deve-se investigar lesões vasculares contusas em artérias carótidas e vertebrais quando houver\nfraturas de C1 a C3, fraturas cervicais\ncom subluxação e fraturas envolvendo o forame transverso.","D":"A Síndrome Anterior da Medula é caracterizada pela desproporção entre perda de força motora\nnas extremidades superiores mais acentuadas que\nnas extremidades inferiores."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157588","number":"157588","sourceNumber":"157588","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A Laparotomia no trauma é indicada nas seguintes situações, com EXCEÇÃO de uma\ndelas. Aponte-a.","options":{"A":"TC com contraste revelando lesão gastrointestinal.","B":"TC com contraste com Lesão do pedículo renal ou lesão parenquimatosa grave após trauma\nfechado.","C":"TC com contraste com Lesão extraperitonial de bexiga.","D":"Ruptura de diafragmática."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157595","number":"157595","sourceNumber":"157595","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito dos dermátomos espinhais avaliados no exame sensorial do trauma\nvértebro-medular, assinale a alternativa CORRETA:","options":{"A":"T4 corresponde à área de inervação do xifoide.","B":"C8 corresponde à área de inervação do dedo mínimo.","C":"T12 corresponde à área de inervação do umbigo.","D":"S1 corresponde à região perianal."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157676","number":"157676","sourceNumber":"157676","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"De acordo com o ATLS, aponte a alternativa que contém as lesões potencialmente\nfatais, que devem ser obrigatoriamente\nreconhecidas já na avaliação primária.","options":{"A":"Pneumotórax, pneumotórax aberto, hemotórax, ruptura esofágica e obstrução de via aérea.","B":"Obstrução de via aérea, pneumotórax hipertensivo, pneumotórax aberto, tórax instável,\nhemotórax maciço e tamponamento cardíaco.","C":"Contusão cardíaca, lesão traqueobrônquica, pneumotórax hipertensivo, pneumotórax aberto e\ntórax instável.","D":"Ruptura de aorta, contusão cardíaca, pneumotórax aberto, pneumotórax hipertensivo e\nobstrução de via aérea."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157701","number":"157701","sourceNumber":"157701","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o trauma pediátrico, aponte a alternativa CORRETA.","options":{"A":"As drogas de escolha para intubação orotraqueal em crianças politraumatizadas com\ninstabilidade hemodinâmica são: propofol, fentanil e succinilcolina.","B":"É indicado o uso de sulfato de atropina previamente à sedação e bloqueio neuromuscular na\nintubação orotraqueal em menores de 1 ano.","C":"A intubação nasotraqueal é o método preferido para a obtenção da via aérea em crianças.","D":"Os locais preferenciais para acesso venosos em crianças são: intraósseo, percutâneo e\ndissecção venosa."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157713","number":"157713","sourceNumber":"157713","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Choque é uma anormalidade do sistema circulatório, que resulta em perfusão orgânica\ne oxigenação tecidual inadequadas. Sobre o choque\ntraumático, assinale a alternativa\nINCORRETA.","options":{"A":"Choque hemorrágico é a causa mais comum de choque após trauma. Outras causas de choque\nnão-hemorrágicos são: cardiogênico, tamponamento cardíaco, pneumotórax hipertensivo,\nneurogênico e séptico.","B":"Choque hemorrágico classe I representa uma perda sanguínea de até 750 mL, e clinicamente o\npaciente encontra-se com frequência cardíaca entre 100 e 120 bpm, pressão arterial normal,\npressão de pulso diminuída.","C":"Choque hemorrágico classe III se caracteriza por perda sanguínea estimada entre 1.500 e 2.000\nmL, e é caracterizado clinicamente por pressão arterial diminuída, pressão de pulso diminuída,\nfrequência de pulso entre 120 e 140 bpm.","D":"Transfusão maciça em doentes em choque é definida como transfusão > 10 unidades de sangue\nem 24 horas. Terapia balanceada ou\nhemostática corresponde à administração precoce de sangue,\nplasma e plaquetas, além de cristaloides, e pode melhorar a sobrevida."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157625","number":"157625","sourceNumber":"157625","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o traumatismo craniano, assinale a alternativa INCORRETA.","options":{"A":"Recomenda-se cirurgia para todo paciente com hematoma epidural maior que 5 milímetros.","B":"Valores persistentes de PIC > 20 mmHg são considerados anormais e requerem medidas iniciais\npara o tratamento de hipertensão intracraniana, como manitol, hiperventilação e hipotermia.","C":"O hematoma epidural é mais comum que os ubdural, e com frequência são decorrentes da\nruptura da A. Meníngea média. Tem caracteristicamente a forma biconvexa.","D":"As contusões cerebrais são bastante comuns, e a maioria delas ocorre nos lobos frontal e\ntemporal. Em até 20% dos casos, pode ocorrer formação de hematomas intracerebrais com efeito\nde massa, por isso é necessário uma TC de controle em 24h após a TC inicial."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157724","number":"157724","sourceNumber":"157724","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o trauma torácico, assinale a alternativa INCORRETA.","options":{"A":"Pneumotórax simples é uma das lesões mais encontradas no trauma. Tanto o ferimento\npenetrante como contuso são causas de vazamento de ar do pulmão ao espaço pleural.","B":"Na contusão pulmonar histopatologicamente, podemos encontrar áreas de hemorragia alveolar e\nintersticial, até áreas de laceração de parênquima. Fraturas costais múltiplas e principalmente das\ntrês primeiras costelas, da escápula e do esterno alertam para presença de contusão pulmonar.","C":"Nos pacientes com ferimentos transfixantes de mediastino estáveis hemodinamicamente e sem\nevidência clínica ou radiológica de lesão em órgãos mediastinais, não é preciso solicitar exames\nauxiliares para excluir lesões de esôfago, traqueia, brônquios, vasos mediastinais e coração.","D":"A ruptura diafragmática por trauma fechado tem como fisiopatologia o aumento repentino da\npressão intra-abdominal. Os acidentes de trânsito e\nas quedas de altura são causas frequentes de\ntrauma fechado."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157703","number":"157703","sourceNumber":"157703","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"As lesões cranioencefálicas encontram-se entre os tipos de trauma mais frequentes.\nSobre o TCE, assinale a alternativa CORRETA.","options":{"A":"Síndrome de herniação do uncus é caracterizada por anisocoria, com dilatação pupilar e\nhemiplegia contralateral.","B":"Hematomas subdurais tem a forma biconvexa, e estão mais localizadas na região temporal ou\ntêmporo-parietal.","C":"Hematomas epidurais são relativamente raros e resultam da ruptura da artéria meníngea média.","D":"Os anticonvulsivantes devem ser usados rotineiramente em todos os TCE graves, e o agente\nhabitualmente utilizado é o\n\nfenobarbital."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157709","number":"157709","sourceNumber":"157709","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Aponte a alternativa INCORRETA.","options":{"A":"Hipertensão Intra-abdominal é definida por pressão intra-abdominal > 12 mmHg, aferida em três\nmedições padronizadas, em intervalos de 4 a 6 horas.","B":"Hipertensão Intra-abdominal é definida como pressão de perfusão abdominal < 60 mmHg,\naferida por no mínimo duas vezes, realizada com 1 a 6 horas de diferença.","C":"Síndrome Compartimental Abdominal é definida por pressão intra-abdominal > 20 mmHg,\naferida por 3 medidas, com intervalo de 1 a 6\nhoras, em conjunto com falência orgânica que não\nestava previamente.","D":"As manifestações clínicas da hipertensão abdominal e Síndrome Compartimental são elementos\ntardios na evolução. A sensibilidade do\nexame físico na detecção da hipertensão abdominal\nultrapassa 50%."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157702","number":"157702","sourceNumber":"157702","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o traumatismo de crânio, assinale a alternativa INCORRETA.","options":{"A":"Comparativamente aos adultos, diferenças anatômicas tornam a faixa etária pediátrica\nparticularmente suscetível ao trauma de crânio e a certos tipos de lesões associadas.","B":"As lesões cerebrais no trauma de crânio são classificadas em primárias e secundárias.","C":"A lesão cerebral primária é produzida no momento do impacto como consequência do\ntraumatismo direto sobre o cérebro ou por forças de aceleração ou desaceleração agindo na\nsubstância branca.","D":"A lesão cerebral primária, após instalada, pode ser alterada pela intervenção terapêutica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157721","number":"157721","sourceNumber":"157721","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Das manifestações clínicas a seguir, todas estão presentes no tamponamento cardíaco,\ncom EXCEÇÃO de:","options":{"A":"Turgência jugular.","B":"Taquicardia.","C":"Cianose.","D":"Dispneia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157677","number":"157677","sourceNumber":"157677","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"?Tradicionalmente, considera-se que a lesão cerebral traumática é leve quando o\nquadro evolui com ausência de sinais\nneurológicos focais e o paciente apresenta um nível de\nconsciência igual ou superior a na avaliação pela escala de coma de Glasgow.? Assinale a\nalternativa que preenche a lacuna ADEQUADAMENTE.","options":{"A":"10","B":"11","C":"12","D":"13"},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157707","number":"157707","sourceNumber":"157707","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual é a desvantagem do uso de coloide natural em relação aos sintéticos no paciente\ncom choque séptico?","options":{"A":"Maior efeito expansor.","B":"Menor risco de reação anafilática.","C":"Maior custo.","D":"Menor risco de alteração da coagulação."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157689","number":"157689","sourceNumber":"157689","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa CORRETA a respeito do atendimento pré-hospitalar de pacientes\napós o afogamento.","options":{"A":"Como a parada cardíaca decorre da asfixia, maximizar a oxigenação, junto com a perfusão\ndurante a reanimação cardiopulmonar, pode\nmelhorar o prognóstico desses pacientes.","B":"A reanimação deve ser iniciada na água, sem exceções.","C":"CPAP é a melhor forma de ventilar e oxigenar vítimas de afogamento.","D":"Como a parada cardíaca decorre da asfixia, maximizar a oxigenação pode melhorar o\nprognóstico desses pacientes."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-157699","number":"157699","sourceNumber":"157699","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com histórico prévio de hidrocefalia por sequela de trauma evolui com rápida\ndeterioração do quadro neurológico. Qual das alternativas a seguir corresponde à tríade achada na\nHipertensão Intracraniana?","options":{"A":"Hipertensão, Bradicardia e Dificuldade respiratória.","B":"Hipertensão, Taquicardia e Ritmo de Biot.","C":"Vômitos em jato, Cefaleia eTaquicardia.","D":"Glasgow abaixo de 8, Dificuldade respiratória e Edema de papila."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134780","number":"134780","sourceNumber":"134780","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A radiografia de rotina no trauma de face é:","options":{"A":"Waters.","B":"Caldwell.","C":"Towne.","D":"Perfil."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134789","number":"134789","sourceNumber":"134789","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com traumatismo de face apresentando fratura tipo Le Fort III. Qual é a melhor\nincidência radiológica para o diagnóstico e sua sinonímia?","options":{"A":"Incidência de Waters, fratura de Guerin.","B":"Incidência de Hirtz, fratura piramidal.","C":"Incidência de Waters, disjunção craniofacial.","D":"Incidência de Hirtz, fratura de Guerin."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111924","number":"111924","sourceNumber":"111924","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Quando lançamos mão do manejo de via aérea provisório, devemos considerar\ndiversos aspectos no procedimento, EXCETO por:","options":{"A":"cânula de guedel, pois exacerba vômitos caso o paciente esteja acordado.","B":"proteção de via aérea com máscara laríngea.","C":"posição olfativa, pois também melhora a ventilação.","D":"todas as alternativas anteriores."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111823","number":"111823","sourceNumber":"111823","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das manobras abaixo listadas apresenta contraindicação no manejo de via aérea\nrealizada na emergência de uma insuficiência respiratória?","options":{"A":"Traqueostomia.","B":"Cricotireoideostomia.","C":"Máscara laríngea.","D":"Máscara e cânula de guedel."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111895","number":"111895","sourceNumber":"111895","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Chega ao departamento de emergência um menino de 7 anos com Trauma Craniano.\nO paciente apresenta uma atitude combativa e\nnecessita ser sedado e intubado para realização de\nTomografia Computadorizada. Qual dos seguintes fármacos é o MENOS apropriado para esse\nmenino?","options":{"A":"Lidocaína.","B":"Quetamina.","C":"Propofol.","D":"Tiopental."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111882","number":"111882","sourceNumber":"111882","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considerando um paciente politraumatizado, com traumatismo craniano, devidamente\nresgatado e transportado com colar\ncervical, prancha e máscara com nebulização de oxigênio,\nGlasgow 7, a primeira medida a ser tomada é:","options":{"A":"tomografia de crânio.","B":"acionar o neurocirurgião de plantão.","C":"avaliação da via aérea e intubação orotraqueal para ventilação mecânica.","D":"todas as alternativas anteriores."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111889","number":"111889","sourceNumber":"111889","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação ao trauma abdominal fechado, qual é o órgão MAIS acometido?","options":{"A":"Baço.","B":"Fígado.","C":"Víscera oca.","D":"Laceração do mesentério no trauma."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111858","number":"111858","sourceNumber":"111858","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Entende-se hipovolemia por um volume de sangue menor do que o normal, e que pode\nocorrer:","options":{"A":"por perda de sangue total, plasma, água e sal, e dissecação.","B":"somente por perda de sangue total.","C":"às vezes, por perda de sangue, água e sal.","D":"por todas as alternativas anteriores."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-321292","number":"321292","sourceNumber":"321292","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma equipe de resgate do SAMU é acionada para atender uma vítima de acidente de\njet ski que após colisão frontal apresenta\ntrauma facial grave. O paciente apresenta-se com rosto\ndesfigurado, grande quantidade de sangue saindo pelos ferimentos da face. Ele emite sons de\ndifícil compreensão devido à dificuldade de respirar por aspiração constante de sangue. O paciente\né colocado na maca com proteção cervical. Apesar da grande deformidade da mandíbula, é\npossível observar afundamento do palato, sangue e fragmentos ósseos na cavidade oral e edema\nde glote. Há líquido claro e sangue que se exterioriza através do nariz. O paciente está pálido e\ncom extremidades cianóticas. Qual medida deve ser tomada imediatamente, para esse paciente?","options":{"A":"Traqueostomia.","B":"Cricotiroidostomia.","C":"Intubação nasotraqueal.","D":"Intubação orotraqueal com Bougie."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-350873","number":"350873","sourceNumber":"350873","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em um cenário de trauma, a equipe de PHTLS prepara e transporta as vítimas a um\ncentro de trauma onde uma equipe com treinamento em ATLS está aguardando. Nesse contexto,\nem qual das seguintes situações o atendimento da equipe hospitalar será essencial para impactar\nna mortalidade?","options":{"A":"Idosa vítima de trauma cranioencefálico e raquimedular.","B":"Mulher desorientada, pele pálida e fria, com deformidade pélvica.","C":"Criança de 11 anos com fratura exposta de tíbia, gritando, com dor.","D":"Homem com ferimento penetrante precordial sangrando, em parada cardíaca."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-350866","number":"350866","sourceNumber":"350866","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem vítima de trauma automobilístico com impacto frontal é trazido à emergência. O\npaciente apresenta dor em abdome inferior, hipotensão leve e taquicardia. Foi submetido à\nhidratação e passagem de sonda vesical de demora. A pressão, após hidratação, é 130 x 60mmHg\ne a urina apresenta-se vermelha. Realizou tomografia que evidenciou desalinhamento do anel\npélvico e vazamento extraperitonial de contraste através de falha na parede lateral da bexiga, sem\noutros achados. Com relação ao trauma vesical, qual a conduta mais apropriada para esse\npaciente?","options":{"A":"Laparotomia exploradora.","B":"Cistorrafia e aposição de dreno sentinela.","C":"Manutenção da sonda vesical e observação.","D":"Cistoscopia com cateterização ureteral bilateral."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-292790","number":"292790","sourceNumber":"292790","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 25 anos, vítima de politrauma grave com TCE e choque hipovolêmico\npor fratura pélvica, é submetido à cirurgia para\ncontrole de hemorragia. Durante a cirurgia, o\nanestesista opta por utilizar fluidos aquecidos para infundir no doente. Qual a principal vantagem\ndessa conduta?","options":{"A":"Preservar tecido cerebral por evitar hipotermia extrema.","B":"Diminuir o metabolismo e resposta inflamatória exagerada.","C":"Aquecer o paciente para evitar tremores e consequente perda de energia.","D":"Prevenir distúrbios de coagulação em consequência de ação fibrinolítica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-292800","number":"292800","sourceNumber":"292800","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Qual das seguintes características abaixo sugere uma via aérea difícil de\nventilar/entubar?","options":{"A":"Abertura da boca de 6 cm.","B":"Cirurgia de artrodese cervical.","C":"Distância tireomentoniana aumentada.","D":"Visualização da úvula, no teste de Mallampati."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-292802","number":"292802","sourceNumber":"292802","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 64 anos sofre queda do telhado enquanto realizava um conserto elétrico\nna sua casa. Uma ambulância foi acionada e o\npaciente levado para um centro de trauma. O\npaciente referia dor torácica à direita, na projeção de escoriações da pele. Ao exame, estava com\nestado geral comprometido, cianótico, fácies de dor, dispneico, sudoreico, hipotenso, com\nsensação de crepitação subcutânea torácica e ruídos abolidos em hemotórax direito. O que o\nemergentista deve fazer, nesse momento?","options":{"A":"Solicitar o desfibrilador e avaliar arritmia cardíaca.","B":"Solicitar tomografia de tórax, para mensurar contusão pulmonar.","C":"Infundir cristaloides e sangue total e oferecer oxigênio em máscara.","D":"Descomprimir o tórax com agulha, seguida de drenagem em selo d?água."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259695","number":"259695","sourceNumber":"259695","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, 63 anos, deu entrada na emergência com aneurisma de aorta abdominal roto,\nsendo submetido a aneurismectomia e by-pass aorto-bifemoral. Evoluiu no 2º dia de pós-operatório\ncom distensão abdominal, desconforto respiratório e oligúria nas últimas 24 horas. Ao exame,\napresenta-se taquicárdico, hipotenso, taquipnéico, ECG com ritmo sinusal e afebril. Exames\nlaboratoriais: Hb: 11,3 g/dl, leucócitos: 13.200/mm³ sem desvio, plaquetas: 220.000/mm³,\nmarcadores para IAM negativos. Qual a conduta diagnóstica inicial?","options":{"A":"Laparotomia exploradora.","B":"Tomografia de abdome com contraste.","C":"Raio X de tórax e abdome em ortostase e decúbito.","D":"Aferição da pressão intra-abdominal pela sonda vesical de demora."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259699","number":"259699","sourceNumber":"259699","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um jovem motociclista de 19 anos se envolve em uma colisão com um ônibus no\ncruzamento que fica cerca de 20 minutos do Hospital de Emergência Terciário de referência às\nvítimas de trauma. Ele usava corretamente o capacete e estava confuso, agitado, expressando\nmuita dor, com pele pálida, fria e úmida na cena. O que chama atenção é uma grave lesão de\namputação traumática da perna esquerda ao nível do joelho com muito sangue no asfalto.\n\nPopulares aplicaram um torniquete improvisado pouco tempo depois e chamaram o SAMU 192. De\nacordo com a nona edição do Prehospital Trauma Life Support (PHTLS), qual a primeira ação da\nequipe de Suporte Avançado de Vida do SAMU 192 na avaliação primária do atendimento inicial à\nessa vítima?","options":{"A":"Colocar curativo compressivo.","B":"Iniciar analgesia endovenosa com opioides.","C":"Confirmar se o torniquete foi aplicado corretamente.","D":"Verificar a permeabilidade da via aérea e controle cervical."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259700","number":"259700","sourceNumber":"259700","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um jovem de 17 anos deu entrada na UPA 24h levado por populares, após ser atingido\npor um projétil de arma de fogo na região do\nhipocôndrio esquerdo, acerca de 40 minutos. Os\nachados da avaliação primária mostram que ele está com fala confusa, ansioso, respiração rápida\n(FR = 27 irpm) e superficial, murmúrio vesicular presente bilateral, pele pálida, fria e úmida. O\npulso\nradial não é palpável e há sangramento mínimo pela lesão abdominal, sem evidência de outro\nferimento. Tem dor abdominal importante a palpação e o glasgow é 13 (3+4+6). O Hospital de\nreferência em Trauma fica há 18 minutos de distância e o SAMU 192 já foi acionado. Considerando\no mecanismo do trauma e os achados da avaliação, qual a conduta inicial mais adequada para ser\nrealizada na UPA para esse caso?","options":{"A":"Estabelecer uma reanimação de controle de danos, ofertar oxigênio suplementar, reposição\ntitulada de ringer lactato, dose inicial de ácido tranexâmico e aquecer o doente.","B":"Realizar intubação orotraqueal, aplicar colar cervical, reposição volêmica de 2 litros de soro\nfisiológico aquecido, considerar drogas vasoativas e curativo oclusivo do ferimento.","C":"Solicitar radiografia do tórax, abdome e pelve, uso do ultrassom à beira do leito, iniciar\ninfusão\nde noradrenalina, iniciar reposição volêmica\nvigorosa de cristaloides e realizar ventilação assistida.","D":"Verificar a resposta após infusão rápida de 1500 ml de cristaloide, ofertar oxigênio em alto\nfluxo,\nnão realizar o ácido tranexâmico pelo tempo da lesão, curativo compressivo da lesão e agilizar a\nremoção pelo SAMU 192."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259704","number":"259704","sourceNumber":"259704","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A unidade de suporte avançado do SAMU 192 chega na Sala de Emergência do\nHospital de Trauma com um doente ocupante\nde veículo de passeio que capotou após uma curva\nem uma estrada federal. Ele encontra-se alerta, com restrição de movimento da coluna, abrasões\nno tórax direito e região do flanco direito do abdome, leve taquipneia, sem crepitação e enfisema na\npalpação do tórax, murmúrio vesicular diminuído na base do tórax direito, saturação de 95% com\noxigênio suplementar, pele corada e seca, pulso radial palpável. Na palpação abdominal apresenta\nsensibilidade evidente e descompressão dolorosa difusa, sem alteração no exame da pelve,\nGlasgow 14 (4+4+6) com hálito alcóolico e ossos longos sem evidência de fraturas. Sinais vitais:\nFR 23 irpm, FC 96 bpm, PA 102 x 70 mmHg, temperatura 36,5ºC. Com base nesses achados da\navaliação inicial, qual a tomada de decisão na abordagem desse doente?","options":{"A":"Indicar cirurgia de emergência, neste caso uma laparotomia exploradora.","B":"Realizar ultrassonografia focada no trauma (FAST) e se positivo indicar laparotomia.","C":"Realizar tomografia abdominal com contraste para decidir entre tratamento conservador ou\ncirurgia.","D":"Exames radiológicos habituais da avaliação primária (radiografia do tórax, pelve e eFAST) e\nexame físico seriado."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/259704.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259673","number":"259673","sourceNumber":"259673","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma mulher, de 27 anos, vítima de colisão moto x poste é trazida para a emergência\npelo SAMU. De acordo com o médico do\npré-hospitalar, ele realizou a intubação pelo rebaixamento\nde consciência (Glasgow 7) na ambulância. Durante a avaliação inicial, identifica-se uma paciente\nobesa com volumoso enfisema subcutâneo envolvendo principalmente o hemitórax esquerdo, com\nmurmúrio vesicular abolido também à esquerda. Não há presença de turgência jugular e não é\npercebido desvio de traqueia no exame físico. A frequência cardíaca é 142 bpm, pressão arterial 82\nx 54 mmHg, pele pálida, fria e úmida. Com base nessas informações iniciais e as recomendações\natuais de tratamento do doente de trauma, qual a melhor conduta a ser realizada inicialmente?","options":{"A":"Drenagem torácica em selo d´água à esquerda e verificar a posição do tubo endotraqueal.","B":"Realizar o extend ? FAST e na presença do sinal do ?código de barras? realizar uma\ndescompressão torácica digital.","C":"Toracocentese com agulha no 2º espaço intercostal da linha clavicular média à esquerda e\nsolicitar radiografia de tórax anteroposterior.","D":"Descompressão torácica à esquerda com agulha no 5º espaço intercostal na linha axilar anterior\ne seguir com a drenagem torácica em selo\nd´água."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-259674","number":"259674","sourceNumber":"259674","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Durante uma laparotomia de emergência, em um doente com trauma abdominal, os\nachados cirúrgicos são: uma laceração de 60% do\ncorpo do pâncreas com secção do ducto e uma\nlesão esplênica com sangramento. Os parâmetros hemodinâmicos estão estáveis. Qual o melhor\ntratamento para corrigir essas lesões?","options":{"A":"Reparo pancreático primário e esplenorrafia.","B":"Reparo pancreático primário e esplenectomia.","C":"Pancreatectomia distal, esplenectomia e drenagem.","D":"Enterostomia pancreática em Y de Roux e esplenorrafia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-234010","number":"234010","sourceNumber":"234010","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um motociclista de 22 anos e? envolvido em uma colisa?o com um carro, sendo\natendido pela equipe do SAMU 192 que realizou\no atendimento inicial conforme o PHTLS\n(Prehospital Trauma Life Support) e aplicou te?cnicas de restric?a?o de movimento da coluna.\nLevado ate? a sala de emerge?ncia tem os seguintes dados na avaliac?a?o inicial: A: via ae?rea\npe?rvia, fala confuso, oxige?nio suplementar (12l/min) e colar cervical; B: FR = 28 irpm,\nsime?trica,\nmurmu?rio bilateral presente, SaTO2 = 94%, ause?ncia de crepitac?a?o o?ssea e de enfisema\nsubcuta?neo; C: Sangramento na perna direita controlado com curativo compressivo, pele quente,\npulsos radiais palpa?veis FC= 70 bpm, enchimento capilar < 2 seg. PA= 84 x 52 mmHg, pelve\nesta?vel; D: pupilas isoco?ricas e fotorreagentes, Glasgow = 14; sem movimento motor e\nsensibilidade dos membros inferiores E: diversas escoriac?o?es asfa?lticas, deformidade no\ntornozelo E (imobilizado), dorso com escoriac?o?es e a?reas de dor a? palpac?a?o. Realizado o\neFAST (negativo), Rx de to?rax e pelve sem anormalidades. Com base na histo?ria cli?nica\ndescrita, qual a prova?vel origem do choque circulato?rio?","options":{"A":"Choque medular.","B":"Choque neuroge?nico.","C":"Choque hipovole?mico.","D":"Choque hemorra?gico de fonte oculta."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-199716","number":"199716","sourceNumber":"199716","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Menina de 8 anos de idade, 25 kg, foi vítima de atropelamento há meia hora. Foi\natendida pela equipe do SAMU que iniciou\ninfusão de 500 ml de Ringer lactato por acesso venoso\nperiférico calibroso e administração de oxigênio suplementar. Foi transferida para unidade de\nemergência em centro de trauma nível I, com equipe específica para atendimento pediátrico. Ao\nchegar, estava alerta e referia dor abdominal, já finalizando a infusão. Exame físico: pulsos\nperiféricos finos; FC = 140 bpm; PA = 95 x 65 mmHg; FR = 40 irpm e saturação de oxigênio de 96%\nem ar ambiente; ACP = normal; abdome = distensão leve, doloroso difusamente, com Blumberg\npresente. Sem outros achados. Avaliação neurológica normal. Raio X de tórax normal. Tomografia\ncomputadorizada helicoidal de abdome revelou laceração capsular de 3 cm de profundidade no\nparênquima esplênico, com líquido livre na cavidade compatível com sangue particularmente em\nespaço esplenorrenal e ausência de pneumoperitônio. Com base na última versão do ATLS em\nportuguês (9ª edição), qual a próxima conduta a ser tomada?","options":{"A":"Prescrever a transfusão de 500 ml de sangue e posteriormente reavaliar a indicação de\nlaparotomia exploradora.","B":"Internar em UTI Pediátrica e iniciar hidratação de manutenção com 250 ml de Ringer lactato nas\npróximas 6 horas.","C":"Indicar laparotomia exploradora e prosseguir ressuscitação volêmica até controle definitivo do\nsangramento ativo.","D":"Administrar nova expansão volêmica com 500 ml de Ringer lactato e posteriormente reavaliar a\nindicação de laparotomia."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-199735","number":"199735","sourceNumber":"199735","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, condutor de moto, vítima de acidente de trânsito envolvendo um carro e sua\nmoto. Foi encontrado pelo SAMU no local do acidente deitado ao solo, apresentando ventilação\nrápida e superficial, saturação de O? = 92%; pele fria, úmida, pálida e enchimento capilar de 4\nsegundos; pulsos radiais filiformes e rápidos; diversas escoriações e lesões de queimadura\nasfáltica; confuso e com hálito alcoólico; deformidades e edema de coxa direita, antebraço e\ntornozelo esquerdo Considerando os princípios de atendimento do Prehospital Trauma Life Support\n\n- PHTLS, qual a conduta adequada para este paciente no local do acidente?","options":{"A":"Aplicar colar cervical, iniciar analgesia, imobilizar com talas, rolamento e colocação em prancha\nlonga, remoção para a ambulância.","B":"Aplicar o colar cervical, alinhar e imobilizar em prancha longa, remover para ambulância e\nrealizar acesso venoso para reposição volêmica a caminho do hospital.","C":"Realizar intubação de sequência rápida, aplicar o colar cervical, iniciar reposição volêmica\nvigorosa,\n\nimobilizar principais fraturas e remover para a ambulância.","D":"Aplicar manobras manuais de abertura da via aérea, aplicar colar cervical, 2 acessos venosos\ncalibrosos com reposição rápida de Ringer lactato, imobilização cuidadosa das fraturas e remoção\npara a ambulância."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-199679","number":"199679","sourceNumber":"199679","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"M.F.D.T., masculino, 33 anos, vaqueiro, deu entrada na emergência de um hospital\nsecundário no interior do estado vítima de\nacidente automobilístico: colisão frontal com um cavalo\nseguida de capotamento. Usava cinto de segurança. Não possui doenças concomitantes. Ao\nexame, encontra-se com sinais vitais estáveis, sem evidências de fraturas, mas com múltiplas\nescoriações em face e braços. Não lembra do acidente, nem de como foi trazido para o hospital. Ao\nexame, encontra-se acordado, orientado, cooperativo, atendendo a comandos. Os exames\nradiológicos de tórax, coluna cervical, bacia e crânio foram normais e os exames laboratoriais\ncolhidos também não evidenciaram alterações. Qual a conduta mais adequada?","options":{"A":"Transferir imediatamente para hospital terciário com UTI e neurocirurgião de plantão.","B":"Prescrever analgésicos e alta hospitalar, recomendando manter-se acordado por seis horas.","C":"Internar na enfermaria para observação com prescrição de analgésico, corticoide e manitol.","D":"Manter internado em observação aguardando vaga eletiva para tomografia computadorizada."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-172991","number":"172991","sourceNumber":"172991","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Na emergência de um Centro de Trauma, você recebe um paciente levado pelo SAMU\nvítima de colisão frontal moto x carro. Trata-se de um jovem de 17 anos, intubado, com colar\ncervical e imobilizado na prancha, sem lesões hemorrágicas aparentes, murmúrio vesicular\npresente bilateral, SatO? = 92%; pele pálida, fria e úmida, FC = 138 bpm; PA = 82 x 50 mmHg.\n\nDurante o atendimento inicial, é identificada uma instabilidade pélvica e solicitado um RX na sala\nde\nemergência (vide abaixo). Qual a conduta mais adequada para este paciente nessa situação?","options":{"A":"Indicar fixação externa imediata.","B":"Indicar laparotomia exploradora.","C":"Solicitar tomografia abdominal total com contraste venoso.","D":"Realizar uma ultrassonografia abdominal focada no trauma (FAST) na sala de reanimação."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/172991.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-173000","number":"173000","sourceNumber":"173000","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Motorista, 42 anos, sofreu colisão frontal em seu carro. No momento do acidente,\nviajava a 60 km/h e estava sem cinto de\nsegurança. Foi encaminhado à Emergência, pelo SAMU,\nqueixando-se de dor no peito. Na avaliação primária intra-hospitalar, apresentava via aérea livre,\nmurmúrio vesicular presente bilateralmente, ausculta cardíaca com sopro sistólico (+/4) e bulhas\ncardíacas normais. SatO2 = 96%, PA = 110 x 80 mmHg, pulso de 104 bpm, Glasgow = 15,\nhematoma superficial pré-esternal. Paciente não melhorou da dor após administração de nitratos e\napresentava ECG com taquicardia sinusal. Qual o diagnóstico mais provável?","options":{"A":"Tórax instável.","B":"Contusão miocárdica.","C":"Tamponamento cardíaco.","D":"Infarto agudo do miocárdio."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-173012","number":"173012","sourceNumber":"173012","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma equipe de suporte avançado do SAMU 192 chega na sala de emergência com um\nhomem de 44 anos, vítima de atropelamento\nem uma via de 60 km/h de velocidade. Na abordagem\ninicial, o paciente reclama de sede e parece confuso. Encontra-se imobilizado com colar cervical e\nem prancha longa, com FR = 32 irpm; murmúrio vesicular presente bilateral; SatO? = 93% com\noxigênio a 12 L/min.; FC = 142 bpm; PA = 72 x 50 mmHg e com múltiplas escoriações em tronco e\nextremidades. Na sala de emergência, é submetido a uma ultrassonografia abdominal focada no\ntrauma (FAST), conforme figura abaixo que mostra o espaço de Morrison. Com base nos achados\nclínicos e no FAST, qual a conduta mais adequada?","options":{"A":"Reanimação volêmica de 20 ml/kg e videolaparoscopia.","B":"Procedimentos de controle de danos e tratamento conservador.","C":"Atendimento inicial ao trauma e indicar laparotomia exploradora.","D":"Reposição volêmica de 2 litros de cristaloides e tomografia abdominal."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/173012.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-150789","number":"150789","sourceNumber":"150789","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Mulher de 25 anos, durante uma videolaparoscopia eletiva, apresenta lesão de aorta\nevoluindo com choque hipovolêmico classe 4. Foi ressuscitada hemodinamicamente com grande\nvolume de cristaloides e múltiplas transfusões de concentrados de hemácias e de plasma fresco.\nTeve o foco principal do sangramento resolvido. Passou a apresentar, em seguida, sangramento\npelos locais de punção venosa e pela incisão cirúrgica que não cedia com a compressão mecânica.\nAtualmente, o perfil de coagulação demonstra plaquetas normais, TAP e TPTa levemente\naumentados e fibrinogênio normal. HPP: a paciente tinha realizado amigdalectomia há 4 anos, sem\nsangramento, e o coagulograma pré-operatório era normal. Qual a causa mais provável da\ncoagulopatia, nesse caso?","options":{"A":"Coagulopatia dilucional.","B":"Doença de von Willebrand.","C":"Coagulopatia por hipotermia.","D":"Coagulação intravascular disseminada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-150801","number":"150801","sourceNumber":"150801","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 35 anos foi vítima de agressão à faca em uma briga de bar. Chega à\nunidade de emergência em choque e é encaminhado à sala de ressuscitação. Ao exame físico,\npercebe-se ferimento de 2 cm de comprimento ao nível do 6º espaço intercostal esquerdo, próximo\nao esterno. As pupilas estão reativas, não há pulsos e evidencia-se movimentos respiratórios\nespontâneos. Em seguida, um membro da equipe constata que o paciente está em parada\ncardíaca. Na monitorização, constata-se atividade eletrocardiográfica organizada. Qual a MELHOR\nconduta nesse caso?","options":{"A":"Iniciar massagem cardíaca externa.","B":"Realizar pericardiocentese de alívio.","C":"Realizar janela pericárdica de alívio.","D":"Realizar toracotomia de reanimação."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-150806","number":"150806","sourceNumber":"150806","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um colegial de 17 anos chega à unidade de emergência após acidente resultante de\nmergulho em piscina rasa, usando colar cervical e prancha de imobilização de toda a coluna. Foi\nretirado imediatamente da piscina referindo dor na coluna cervical e paralisia motora dos membros\nsuperiores e inferiores. Na avaliação inicial, apresentava dificuldade respiratória, hipoventilação,\nparalisia dos músculos intercostais, PA = 80/40 mmHg, pulso 72/min, consciente, orientado,\nextremidades bem perfundidas e aquecidas. Qual a MELHOR conduta nesse caso?","options":{"A":"Suporte ventilatório, reposição volêmica, vasopressor e TC de toda a coluna.","B":"Ventilação sob máscara, reposição volêmica com soro fisiológico e TC da coluna cervical.","C":"Intubação, reposição de cristaloide, corticosteroides venosos e radiografias de toda a coluna.","D":"Máscara de Venturi, reposição com Ringer lactato, noradrenalina e radiografias de toda a\ncoluna."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-150809","number":"150809","sourceNumber":"150809","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma mulher de 26 anos foi agredida por seu marido e esfaqueada no hemitórax\nesquerdo dois centímetros abaixo do mamilo e\nao nível da linha axilar anterior. Chega ao hospital,\nestável hemodinamicamente, com queixas de dor à inspiração, dor abdominal e discreta dificuldade\nrespiratória. A radiografia do tórax evidencia pneumotórax discreto e pneumoperitônio. Qual a\nmelhor conduta nesse caso?","options":{"A":"Toracotomia e frenorrafia.","B":"Toracocentese e lavado peritonial.","C":"Drenagem de tórax, laparotomia e frenorrafia.","D":"Drenagem de tórax e ultrassonografia abdominal."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-127007","number":"127007","sourceNumber":"127007","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente, sexo feminino, 23 anos, vítima de acidente automobilístico, quando pilotava\nsua moto sem uso de capacete e colidiu\nfrontalmente com um carro. Foi admitida em serviço de\nemergência conduzida por transeuntes. À avaliação inicial, apresentava respiração espontânea\ncom saturação de O2 de 90%; frequência respiratória de 24 irpm; frequência cardíaca de 112 bpm;\nPA de 90 x 60 mmHg; com resposta motora de extensão ao estímulo álgico; resposta verbal com\nsons incompreensíveis e abertura ocular ao comando verbal, além de apresentar fratura exposta\nem fêmur direito e de zigomáticos, bilateralmente. A pontuação na escala de coma de Glasgow e a\nmelhor conduta inicial para essa paciente correspondem ao item:","options":{"A":"Glasgow 7 ? Intubação orotraqueal.","B":"Glasgow 8 ? Ressuscitação volêmica.","C":"Glasgow 9 ? Colocação de colar cervical.","D":"Glasgow 10 ? Realização de TC de crânio."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-127015","number":"127015","sourceNumber":"127015","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"<p>Após o início de um grande incêndio em uma fábrica, os bombeiros conseguiram\nresgatar de seu interior, 1 hora depois, um\noperador de máquinas, 22 anos de idade, 70Kg. Na\navaliação inicial, a vítima apresentava leve taquipneia, com queimaduras de primeiro grau em 14%\nde sua superfície corpórea e de segundo e terceiro graus em 28% de sua superfície corpórea.\n\nEntre outros, foi ofertado oxigênio por máscara e obtidos dois acessos venosos calibrosos.\nSegundo os princípios do suporte avançado de vida\nno trauma, a ressuscitação volêmica com\nRinger Lactato para esse paciente, nas próximas 3 horas, deverá ser de: </p>","options":{"A":"245 a 490 ml/hora.","B":"280 a 560ml/hora.","C":"367,5 a 35ml/hora.","D":"420 a 840ml/hora."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-126963","number":"126963","sourceNumber":"126963","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 22 anos, vítima de lesão penetrante por punhal em hipocôndrio\nesquerdo, é admitido na emergência. Está\nestável clinicamente, porém à exploração cirúrgica do\norifício, houve penetração da cavidade abdominal. Realizou radiografia do tórax normal. Foi\nsubmetido à laparotomia exploradora com enterorrafia. No terceiro dia de pós-operatório evoluiu\ncom dispneia leve e vômitos ocasionais. Realizou nova radiografia do tórax que mostrou imagem\ncom níveis hidroaéreos no hemitórax esquerdo. Qual a conduta recomendada nesse momento?","options":{"A":"Observação.","B":"Toracoscopia.","C":"Laparotomia.","D":"Drenagem do tórax."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-141591","number":"141591","sourceNumber":"141591","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o traumatismo cranioencefálico (TCE), é correto afirmar:","options":{"A":"O TCE grave caracteriza-se por apresentar escala de coma de Glasglow de 15 a 12.","B":"O hematoma subdural agudo geralmente é causado por lesão da artéria meníngea média.","C":"Fraturas de crânio estão associadas a lesões intraparenquimatosas em 66% dos casos.","D":"Na concussão leve, a tomografia de crânio mostra-se com hiperdensidade heterogenia."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-141595","number":"141595","sourceNumber":"141595","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No traumatismo facial, a disjunção craniofacial corresponde a fratura do tipo:","options":{"A":"Le Fort IV.","B":"Le Fort III.","C":"Le Fort II.","D":"Le Fort I."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-322142","number":"322142","sourceNumber":"322142","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente, vítima de acidente automobilístico, chega ao hospital trazido pela equipe\nde atendimento pré-hospitalar já intubado,\nhemodinamicamente instável e anisocórico. Na\nadmissão, foi realizada tomografia computadorizada de crânio que mostrou imagem hiperdensa no\nencéfalo, próximo à calota craniana, em região parietal, de aspecto côncavo-convexo e com\nimportante desvio de linha média. Qual é o diagnóstico e o tratamento mais indicado para esse\npaciente?","options":{"A":"Hematoma epidural / Abordagem cirúrgica.","B":"Hematoma subdural / Abordagem cirúrgica.","C":"Hematoma intraparenquimatoso / Monitorização da pressão intracraniana.","D":"Lesão axonal difusa / Abordagem cirúrgica.","E":"AVC isquêmico / Manitol endovenoso."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-322151","number":"322151","sourceNumber":"322151","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 27 anos é levado ao pronto atendimento após queda de nível elevado.\nDepois de assegurar uma via aérea pérvia, a imobilização da coluna cervical e a checagem dos\nsinais vitais, a resposta ao exame neurológico é a seguinte: flexão normal, sons irreconhecíveis e\nabertura ocular (todos após estímulos dolorosos). Diante do exposto, assinale a alternativa\nCORRETA.","options":{"A":"A tomografia de crânio é importante para determinar a escala de coma de Glasgow desse\npaciente.","B":"O homem apresenta um Traumatismo Crânioencefálico (TCE) leve e pode ser liberado com\nsegurança.","C":"A avaliação do médico neurocirurgião é essencial para a definição entre TCE leve, moderado ou\ngrave.","D":"O homem apresenta 8 pontos na escala de coma de Glasgow.","E":"Uma tomografia de coluna cervical é importante para determinar a escala de coma de Glasgow\ndesse paciente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-365619","number":"365619","sourceNumber":"365619","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 30 anos de idade foi admitido no pronto-socorro após um acidente\nautomobilístico de alta velocidade. Ele\nestava usando cinto de segurança no momento do impacto.\nO paciente queixava-se de dor abdominal intensa e distensão. Ao exame físico, apresentou PA =\n90 mmHg x 60 mmHg, FC = 120 bpm, FR = 24 irpm, temperatura = 36,5 ºC, SatO2 = 92% em a.a, o\nabdome rígido à palpação, com sinais de equimose e hematomas difusos, e ausculta abdominal\ndiminuída. Exames complementares demonstraram hemograma com hematóerito diminuído e base\nexcess -10, radiografia de tórax sem fraturas costais e FAST livre de líquido intraperitoneal.\n\nConsiderando esse caso clínico, assinale a alternativa correspondente à conduta mais apropriada\npara esse paciente com suspeita de trauma\nabdominal.","options":{"A":"Observação clínica e repetição da ultrassonografia em seis horas.","B":"Tentativa de estabilização hemodinâmica com cristaloides até a chegada de sangue. Caso haja\nestabilidade, deve realizar tomografia computadorizada de abdome total sem contraste.","C":"Tentativa de estabilização hemodinâmica com cristaloides até a chegada de sangue. Caso haja\nestabilidade, deve realizar tomografia computadorizada de abdome total com contraste.","D":"Intervenção cirúrgica exploratória imediata."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337499","number":"337499","sourceNumber":"337499","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. Esse paciente pode\nser classificado como em estado de choque classe II.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337500","number":"337500","sourceNumber":"337500","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. O paciente em\nquestão tem indicação de receber transfusão sanguínea, já que se trata de um choque grau III.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337501","number":"337501","sourceNumber":"337501","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. A perda de sangue\nestimada para esse paciente é de 30-40% do seu total.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337502","number":"337502","sourceNumber":"337502","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. Caso haja sinais de\ndor abdominal e peritonite, com líquido intra-abdominal detectado no FAST, há indicação de\nlaparotomia exploradora imediata.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337503","number":"337503","sourceNumber":"337503","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. Pode-se afirmar\nque o paciente se encontra na tríade letal, quando são encontradas acidose, hipertermia e\ncoagulopatia associadas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337504","number":"337504","sourceNumber":"337504","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos sofreu um acidente automobilístico com trauma contuso\nabdominal importante. Foi admitido no serviço de\nemergência com frequência cardíaca de 122,\npressão arterial de 70 x 40 mmHg e frequência respiratória de 35ipm. Em relação ao manejo desse\npaciente e aos conhecimentos médicos correlacionados, julgue o item a seguir. Caso o paciente\napresente lesão esplênica com laceração envolvendo vasos hilares e desvascularização\nimportante, maior que 25% do baço, pode-se classificar essa lesão como grau III.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298834","number":"298834","sourceNumber":"298834","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Nesse caso\nclínico, a escala de coma de Glasgow do paciente é 9.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298835","number":"298835","sourceNumber":"298835","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Quanto ao nível\nde hemorragia, nesse caso, pode-se classificar o choque como classe IVa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298836","number":"298836","sourceNumber":"298836","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A maioria dos\npacientes em choque classe II precisará de transfusão de hemoderivados, enquanto praticamente\ntodos em choque classe III precisarão de protocolo de transfusão maciça.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298837","number":"298837","sourceNumber":"298837","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A radiografia de\ntórax se faz necessária para confirmação do diagnóstico de hemopneumotórax.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298838","number":"298838","sourceNumber":"298838","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A avaliação\ninicial do caso deve seguir o ABCDE do trauma, com as vias áreas pérvias (airway). Deve-se,\nentão, proceder À drenagem pleural fechada (breathing) e, em um segundo momento, avaliar a\nnecessidade de intubação orotraqueal de acordo com a escala de Glasgow.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298839","number":"298839","sourceNumber":"298839","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Nesse caso,\nestá indicado o uso de ácido tranexâmico. Ele é um medicamento antifibrinolítico e deve ser\naplicado de maneira precoce, nas primeiras três horas do trauma, em bolus.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298841","number":"298841","sourceNumber":"298841","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente foi levado pelo Serviço de Atendimento Móvel de Urgência (SAMU) à\nemergência de um hospital com história de atropelamento há alguns minutos. Ao exame físico, o\npaciente apresenta FC = 110 bpm, FR = 28 irpm, SatO2 = 90% e PA = 100 mmHg x 75 mmHg. Ao\nser questionado, apenas verbaliza algumas palavras sem sentido, e demonstra abertura ocular à\ndor e resposta motora de flexão anormal. A ausculta respiratória indica murmúrio vesicular ausente\nà direita e normais à esquerda. Exames cardiovascular e abdominal não há alterações. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Caso o dreno\nde tórax esteja drenado 100 mL serohemático por dia, mesmo sem vazamentos e com boa\nexpansibilidade pulmonar aos raios X, não é possível retirá-lo. É preciso que a drenagem torácica\nseja inferior a 50 mL/dia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298855","number":"298855","sourceNumber":"298855","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos de idade deu entrada na emergência do hospital com história\nde ferimentos por arma branca em hipocôndrio\ndireito e antebraço esquerdo, com delta T de 30\nminutos. No momento, o paciente apresenta-se inquieto, relata leve dor abdominal na área atingida.\nObserva-se lesão cortante profunda em antebraço direito, sem sangramento ativo. Ao exame físico,\nverificam-se FC = 92 bpm, FR = 19 irpm, SatO2 = 99% e abdome indolor à palpação e à\ndescompressão. A exploração digital do ferimento abdominal comprova que ultrapassa a\naponeurose abdominal. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue os itens a seguir. O teste de Allen confirma ou descarta lesão do nervo ulnar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298856","number":"298856","sourceNumber":"298856","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos de idade deu entrada na emergência do hospital com história\nde ferimentos por arma branca em hipocôndrio\ndireito e antebraço esquerdo, com delta T de 30\nminutos. No momento, o paciente apresenta-se inquieto, relata leve dor abdominal na área atingida.\nObserva-se lesão cortante profunda em antebraço direito, sem sangramento ativo. Ao exame físico,\nverificam-se FC = 92 bpm, FR = 19 irpm, SatO2 = 99% e abdome indolor à palpação e à\ndescompressão. A exploração digital do ferimento abdominal comprova que ultrapassa a\naponeurose abdominal. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue os itens a seguir. Apesar de ultrapassar a aponeurose abdominal, pode-se manter\ntratamento conservador para esse paciente, desde que sejam realizados exames clínico e\nlaboratoriais seriados.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-298857","number":"298857","sourceNumber":"298857","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 23 anos de idade deu entrada na emergência do hospital com história\nde ferimentos por arma branca em hipocôndrio\ndireito e antebraço esquerdo, com delta T de 30\nminutos. No momento, o paciente apresenta-se inquieto, relata leve dor abdominal na área atingida.\nObserva-se lesão cortante profunda em antebraço direito, sem sangramento ativo. Ao exame físico,\nverificam-se FC = 92 bpm, FR = 19 irpm, SatO2 = 99% e abdome indolor à palpação e à\ndescompressão. A exploração digital do ferimento abdominal comprova que ultrapassa a\naponeurose abdominal. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue os itens a seguir. Dada a localização do ferimento, esse paciente poderia ter como possível\nlesão vascular a artéria gastroduodenal, ramo da artéria mesentérica superior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-274340","number":"274340","sourceNumber":"274340","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Referente ao choque hemorrágico e seu tratamento, assinale a alternativa correta.","options":{"A":"Na maioria dos casos, é necessária intervenção cirúrgica imediata.","B":"Pacientes adultos com hipotensão, mesmo após reposição de 500mL de solução eletrolítica,\nprecisam de transfusão sanguínea.","C":"O tratamento do choque hemorrágico pode gerar síndrome compartimental abdominal.","D":"A reanimação no choque deve ser feita com infusão de coloides em bólus.","E":"A coagulopatia é comum nos pacientes que precisam de transfusão maciça, sendo necessária a\ninfusão de anticoagulantes."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-274345","number":"274345","sourceNumber":"274345","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente em escala de coma de Glasgow nível 12, com abertura ocular aos estímulos\nverbais e obedecendo a ordens em resposta\nmotora, deve apresentar qual das seguintes respostas\nverbais?","options":{"A":"Orientada e apropriada.","B":"Sons incompreensíveis.","C":"Ausente.","D":"Confusa.","E":"Palavras inapropriadas."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-274346","number":"274346","sourceNumber":"274346","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Em relação às lesões de órgãos abdominais que podem ocorrer em traumas, assinale a\nalternativa correta.","options":{"A":"As lesões gástricas ocorrem predominantemente em traumas fechados.","B":"Laceração maior que 50% da circunferência do duodeno é classificada como grau II.","C":"A hiperamilasemia deve levantar suspeita de lesão duodenal em trauma fechado.","D":"As lesões pancreáticas isoladas são comuns nos traumas fechados e os pacientes precisam ser\noperados devido à peritonite.","E":"O intestino delgado é o 4o (quarto) órgão mais atingido no trauma abdominal penetrante."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261220","number":"261220","sourceNumber":"261220","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Intubação orotraqueal é a\nprimeira conduta a ser tomada nesse momento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261221","number":"261221","sourceNumber":"261221","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A drenagem de tórax está\nformalmente indicada pelo provável hemotórax à direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261222","number":"261222","sourceNumber":"261222","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A TC de crânio deve\nevidenciar hematoma epidural.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261223","number":"261223","sourceNumber":"261223","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Lesão de artéria meningea\nmédia é esperada nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261224","number":"261224","sourceNumber":"261224","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A presença de líquido no\nespaço esplenorrenal indica laparotomia imediata, independentemente das lesões abdominais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261226","number":"261226","sourceNumber":"261226","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 18 anos de idade foi levado ao pronto-socorro após queda de moto em\nalta velocidade, com relato de que estava sem capacete no momento do acidente e que houve\nperda momentânea da consciência. Mas, após o fato, o paciente tornou a apresentar-se orientado\nno local do acidente. Na avaliação inicial, o paciente encontrava-se com colar cervical, agitado,\ncom\nhálito etilico, FR = 35 irpm, SatO2 = 83% com máscara de oxigênio, hemitórax direito com\nmurmúrios vesiculares ausentes e hipertimpânico, PA = 90 mmHg x 50 mmHg, FC = 115 bpm,\npupilas isocóricas e fotorreagentes, Glasgow 7, presença de hematoma extenso em flanco\nesquerdo e fratura de fêmur esquerdo com exposição óssea. FAST mostrou líquido livre no espaço\nesplenorrenal, e sonda vesical passada evidencia hematúria macroscópica. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Lesão renal é um\ndiagnóstico provável, e o acometimento do sistema coletor caracteriza a lesão como grau III.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-284317","number":"284317","sourceNumber":"284317","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. FAST (ultrassom focado para a avaliação do\ntrauma) abdominal mostrando ausência de líquido livre na cavidade abdominal e ausência de lesão\nhepática assegura que o pulmão é a origem das alterações do doente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-284318","number":"284318","sourceNumber":"284318","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 25 anos de idade foi levado ao pronto-socorro após ter sido vítima de\nferimento por arma branca no sexto espaço intercostal, linha axilar anterior. Encontra-se agitado,\ndispneico ++/4+, com pulso de 125 bpm e PA de 70 x 40 mmHg. Apresenta murmúrio vesicular\ndiminuído nos ? inferiores do hemitórax direito. Abdome plano, flácido e indolor à palpação. Com\nbase nesse caso hipotético, julgue o item a seguir. A drenagem torácica de 2.100 mL de sangue no\ndoente indica a toracotomia direita imediata através de uma incisão anterolateral direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261321","number":"261321","sourceNumber":"261321","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Todo profissional médico deve ter algum conhecimento a respeito de atendimento ao\npaciente politraumatizado e medicina de emergência. No que se refere a essa informação e aos\nconhecimentos médicos correlatos, julgue o item a seguir. Na sequência ABCDE de atendimento, a\nletra A refere-se a garantir a via aérea pérvia e a estabilização da coluna cervical; a letra B\n\nrefere-se a garantir a ventilação; e a letra C, a ressuscitação volêmica, o controle de hemorragia e\nos cuidados com hipotermia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-261322","number":"261322","sourceNumber":"261322","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Todo profissional médico deve ter algum conhecimento a respeito de atendimento ao\npaciente politraumatizado e medicina de emergência. No que se refere a essa informação e aos\nconhecimentos médicos correlatos, julgue o item a seguir. A \"hora de ouro\" refere-se ao momento\napós o evento traumático, no qual o atendimento correto e precoce aumenta, de maneira\nsignificativa, a sobrevida do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-255670","number":"255670","sourceNumber":"255670","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nDeve-se submeter a intubação orotraqueal, sendo um agente considerado seguro o etomidato.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-255673","number":"255673","sourceNumber":"255673","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Certo paciente de 38 anos de idade é levado para o hospital após sofrer dois acidentes\npor ferimento de arma de fogo, sendo um no tórax\ne outro no abdome. Chegou ao hospital em\nGlasgow 7. Ao exame físico, estava descorado, com frequência cardíaca de 135 bpm, ausculta\nabolida em hemitórax direito, local onde estava o ferimento por arma de fogo. A pressão arterial\ndele era de 70 mmHg x 50 mmHg e apresentava fáscies de dor. Além disso, apresentou fratura\nmaleolar esquerda com 3 mm de deslocamento da fratura fibular, associada à mesma. Com base\nnesse caso clínico e nos conhecimentos médicos relacionados ao ATLS, julgue o item a seguir.\n\nTomografia de tórax e de crânio devem ser realizadas imediatamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239264","number":"239264","sourceNumber":"239264","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A padronização do atendimento inicial ao trauma tem por\nobjetivo facilitar o treinamento de profissionais e priorizar a atenção às doenças com maior risco\nde\nmorte.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239265","number":"239265","sourceNumber":"239265","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A drenagem do tórax (pleural) é a primeira conduta a se\ntomar na chegada do paciente à sala de trauma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239266","number":"239266","sourceNumber":"239266","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. A tríade de Beck, característica de tamponamento\ncardíaco, é formada por hipofonese de bulhas cardíacas, turgência jugular e hipotensão arterial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239267","number":"239267","sourceNumber":"239267","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Nesse caso, como o paciente estava usando capacete,\npoderia se dispensar a imobilização da coluna cervical com colar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239268","number":"239268","sourceNumber":"239268","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Esse paciente pontua 12 pontos na escala de coma de\nGlasgow, considerado trauma cranioencefálico moderado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239269","number":"239269","sourceNumber":"239269","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 32 anos de idade é levado à sala de trauma pelo Corpo de Bombeiros\n25 minutos após ser vítima de acidente de moto\nversus anteparo. Testemunhas disseram que o\npaciente foi arremessado a uma distância de cerca de 10 metros, e que ele usava capacete. Na\ncena, estava eupneico e mantinha nível de consciência normal. Durante o transporte, começou a\nqueixar-se de \"falta de ar\". A avaliação inicial do plantonista da sala de trauma foi a seguinte: A\n-\nvias aéreas pérvias, com colar cervical; B - taquidispneico, FR = 54 irpm, murmúrios audíveis e\nsimétricos em ambos hemitóraxes, SpO2 = 93%; C - FC = 130 bpm, PA = 89 mmHg x 68 mmHg,\nbulhas cardíacas abafadas, escoriações no abdome e nos membros, sem sangramento ativo.\n\nToque retal sem alterações; D - Abertura ocular ao chamado, fala confusa, localizava dor. Pupilas\nisocóricas e fotorreagentes; E - Membro inferior esquerdo encurtado e em rotação lateral, com dor à\nmanipulação. Coluna sem dor à palpação. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Caso haja melhora das condições hemodinâmicas após\ntratamento do tamponamento cardíaco, deve-se realizar tomografia de abdome e pelve para esse\npaciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250118","number":"250118","sourceNumber":"250118","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. A administração\nde 3 L de cristaloides imediatamente é a principal prioridade na avaliação e na conduta inicial do\ndoente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250119","number":"250119","sourceNumber":"250119","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. A drenagem de\ntórax imediata na sala de emergência está bem justificada pelas condições descritas do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250120","number":"250120","sourceNumber":"250120","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. A aplicação de\numa máscara de oxigênio está indicada no momento da chegada do paciente na sala de\nemergência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250121","number":"250121","sourceNumber":"250121","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. Devido às\ncondições descritas, é possível descartar uma lesão cardíaca no doente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250122","number":"250122","sourceNumber":"250122","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. Caso o paciente\nse estabilize, a realização de uma videotoracoscopia após a drenagem torácica está bem indicada\npara a pesquisa de uma lesão diafragmática associada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250123","number":"250123","sourceNumber":"250123","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. A punção pleural\nno segundo espaço intercostal é um tempo obrigatório antes da drenagem em casos como esse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-250124","number":"250124","sourceNumber":"250124","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 27 anos de idade foi vítima de ferimento por arma branca no sexto\nespaço intercostal, na altura da linha axilar\nanterior esquerda. Chegou ao pronto-socorro dispneico,\nsudoreico, com Glasgow de 14, pulso de 130 bpm, pressão arterial de 80/60 mmHg, frequência\nrespiratória de 35 ipm e murmúrio vesicular diminuído no hemitórax esquerdo. Com base nesse\ncaso hipotético e nos conceitos médicos a ele associados, julgue o item a seguir. A toracotomia\nimediata está indicada se, na drenagem pleural, houver a saída de mais de 1.500 mL de sangue no\nmomento da drenagem.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239337","number":"239337","sourceNumber":"239337","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito do trauma na gestação, julgue o item a seguir. As prioridades do\natendimento inicial à gestante devem ser\nsemelhantes às prioridades da mulher não grávida. A\nadoção de medidas de reanimação materna, assim como a adequada monitorização maternofetal,\nconfiguram, também, o melhor tratamento inicial para o feto","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-239363","number":"239363","sourceNumber":"239363","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 28 anos de idade chega à emergência do pronto-socorro levado por\nambulância após acidente automobilístico a caminho do trabalho em metrópole brasileira, com\natendimento pré-hospitalar pela equipe da SAMU, iniciado oito minutos após o chamado. Na\nchegada à emergência, encontra-se em maca rígida, com colar cervical, com ficha de atendimento\npré-hospitalar indicando pressão arterial = 96 mmHg x 64 mmHg, frequência cardíaca = 102 bpm,\nfrequência respiratória = 20 ipm, saturação de oxigênio = 94%, regular estado geral, mucosas\númidas e hipocoradas, escala de coma de Glasgow 12, pupilas isocóricas e fotorreagentes,\nausculta pulmonar e cardíaca sem particularidades, abdome globoso, sem sinais de peritonismo,\ntempo de enchimento capilar de dois segundos, impressão de nítida fratura de membro inferior\nesquerdo e membro superior direito. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O risco de insuficiência respiratória aguda para esse paciente\nestará aumentado nos dias subsequentes ao acidente, sobretudo em razão dos efeitos orgânicos\nsecundários do politrauma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196601","number":"196601","sourceNumber":"196601","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. Durante o atendimento inicial da vítima em ambiente extra-hospitalar, a\nprimeira ação é atentar-se à hemodinâmina do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214364","number":"214364","sourceNumber":"214364","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Em relação a\nesse caso, a primeira medida a ser adotada são os raios X de cervical, tórax e pelve, preconizados\npelo Advanced Trauma Life Support (ATLS).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196604","number":"196604","sourceNumber":"196604","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. O tratamento da lesão neurológica deve ser feito com manitol e observação\nclínica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214421","number":"214421","sourceNumber":"214421","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Em casos de\ntrauma abdominal fechado, com lesão de vísceras sólidas ( fígado e baço), existem protocolos\natuais que preconizam o tratamento conservador delas, conforme a respectiva classificação de\ngravidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196608","number":"196608","sourceNumber":"196608","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. Após a tomografia, é necessária a realização de avaliação focalizada com\nultrassonografia para trauma (FAST).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214430","number":"214430","sourceNumber":"214430","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Na situação\nmencionada, provavelmente a instabilidade hemodinâmica do paciente ocorreu em razão da lesão\nde víscera sólida, que, nesse caso, pode ser tratada conservadoramente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196616","number":"196616","sourceNumber":"196616","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. Lesões de grau IV hepáticas geralmente são superiores a 75% do lobo\nhepático, sendo, portanto, necessária a abordagem cirúrgica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214443","number":"214443","sourceNumber":"214443","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Esse paciente\nencontra-se em choque classe III.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196618","number":"196618","sourceNumber":"196618","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. A lesão esplênica deve ser cirurgicamente abordada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214449","number":"214449","sourceNumber":"214449","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Na avaliação\nprimária do paciente descrito, o primeiro local a ser avaliado deve ser o abdome, pois, como há\ninstabilidade hemodinâmica, as prioridades se invertem, e a via aérea deixa de ser o primeiro local\na ser avaliado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196622","number":"196622","sourceNumber":"196622","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 35 anos de idade estava pilotando uma motocicleta, quando colidiu com um\ncaminhão, demonstrando politraumatismo. A frequência cardíaca e a pressão arterial dele eram,\nrespectivamente, de 150 bpm e de 80 mmHg x 60 mmHg. As auscultas cardíaca e respiratória\nestavam normais e apresentava abdome em tábua. Diante disso, realizou-se a retirada do paciente\nde acordo com as normas do suporte avançado de vida no trauma (ATLS), e foram realizadas\ntomografias de crânio, tórax e abdome total. Na tomografia de crânio, foi revelado hematoma\nsubdural com desvio da linha média superior a 10 mm. No abdome, apresenta lesão hepática grau\nIV e lesão esplênica grau V. Na tomografia de tórax, não foram encontrados achados sugestivos de\ntrauma. A respeito desse caso clínico e considerando-se os conhecimentos médicos correlatos,\njulgue o item a seguir. Provavelmente o paciente apresentava sinais de irritação peritoneal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214454","number":"214454","sourceNumber":"214454","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 29 anos de idade, vítima de acidente automobilístico (capotamento\napós colisão com obstáculo parado, em alta\nvelocidade, sem cinto de segurança), deu entrada no\npronto-socorro com os seguintes sinais vitais: pressão arterial de 90 mmHg x 70 mmHg; frequência\ncardíaca de 125 bpm; frequência respiratória de 32 mrpm; saturação de O? de 98% em ar\nambiente. Na avaliação inicial, o paciente apresentou via aérea permeável e atingiu 14 pontos na\nescala de coma de Glasgow, perdendo pontos na escala porque se encontrava confuso. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. No caso\napresentado, uma das causas que pode ser considerada para a instabilidade hemodinâmica do\npaciente é a ruptura de aorta, condição de altíssima morbimortalidade que ocorre quando há\ndesaceleração súbita e intensa, e o arco aórtico tende a continuar a se\n\nmovimentar em relação à aorta descendente, provocando uma força de cisalhamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196609","number":"196609","sourceNumber":"196609","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 40 anos de idade foi vítima de lesão por arma de fogo, acometendo a região\ntorácica esquerda. A pressão arterial inicial e a frequência cardíaca dele eram, respectivamente, de\n120 mmHg x 80 mmHg e de 120 bpm. O paciente foi então submetido a uma drenagem torácica por\napresentar hemotórax à esquerda. Durante a primeira hora, ocorreu drenagem sanguinolenta de\n200 mL. Após 24 horas, a drenagem total foi de 400 mL. A respeito desse caso clínico é\nconsiderando-se os conhecimentos médicos correlatos, julgue o item a seguir. O paciente deve ser\nsubmetido a cirurgia torácica de emergência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-196610","number":"196610","sourceNumber":"196610","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 40 anos de idade foi vítima de lesão por arma de fogo, acometendo a região\ntorácica esquerda. A pressão arterial inicial e a frequência cardíaca dele eram, respectivamente, de\n120 mmHg x 80 mmHg e de 120 bpm. O paciente foi então submetido a uma drenagem torácica por\napresentar hemotórax à esquerda. Durante a primeira hora, ocorreu drenagem sanguinolenta de\n200 mL. Após 24 horas, a drenagem total foi de 400 mL. A respeito desse caso clínico é\nconsiderando-se os conhecimentos médicos correlatos, julgue o item a seguir. A principal causa de\nhemotórax é a ruptura das artérias costais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214472","number":"214472","sourceNumber":"214472","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Determinada paciente de 56 anos de idade estava na própria casa, que se encontra em\nreforma, quando uma das paredes que estava sendo desmanchada pelos pedreiros cedeu e a\natingiu, prensando a perna direita dela contra o chão, tornando a mobilização do membro\nimpossível por causa do peso do material. A paciente foi prontamente socorrida pelos pedreiros,\nque chamaram a ambulância, porém não retiraram a parede de cima da perna dela com medo de\nmachucá-la mais. Essa paciente deu entrada no pronto-socorro levada pelo SAMU, cerca de três\nhoras após o incidente, pois encontrava-se em uma cidade sem hospital e em um local de difícil\nacesso para a equipe de resgate. À chegada, apresentava rotação externa de tornozelo e pé\ndireitos, sem lesões de continuidade na pele, porém com edema importante de partes moles abaixo\ndo joelho, hiperemia local e muita dor ao exame do local. Com relação a esse caso clínico, julgue o\nitem a seguir. Essa paciente apresenta um dos sinais precoces da síndrome compartimental.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214478","number":"214478","sourceNumber":"214478","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Determinada paciente de 56 anos de idade estava na própria casa, que se encontra em\nreforma, quando uma das paredes que estava sendo desmanchada pelos pedreiros cedeu e a\natingiu, prensando a perna direita dela contra o chão, tornando a mobilização do membro\nimpossível por causa do peso do material. A paciente foi prontamente socorrida pelos pedreiros,\nque chamaram a ambulância, porém não retiraram a parede de cima da perna dela com medo de\nmachucá-la mais. Essa paciente deu entrada no pronto-socorro levada pelo SAMU, cerca de três\nhoras após o incidente, pois encontrava-se em uma cidade sem hospital e em um local de difícil\nacesso para a equipe de resgate. À chegada, apresentava rotação externa de tornozelo e pé\ndireitos, sem lesões de continuidade na pele, porém com edema importante de partes moles abaixo\ndo joelho, hiperemia local e muita dor ao exame do local. Com relação a esse caso clínico, julgue o\nitem a seguir. A paciente mencionada não apresenta sinais de contratura isquêmica de Volkmann.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-214485","number":"214485","sourceNumber":"214485","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Determinada paciente de 56 anos de idade estava na própria casa, que se encontra em\nreforma, quando uma das paredes que estava sendo desmanchada pelos pedreiros cedeu e a\natingiu, prensando a perna direita dela contra o chão, tornando a mobilização do membro\nimpossível por causa do peso do material. A paciente foi prontamente socorrida pelos pedreiros,\nque chamaram a ambulância, porém não retiraram a parede de cima da perna dela com medo de\nmachucá-la mais. Essa paciente deu entrada no pronto-socorro levada pelo SAMU, cerca de três\nhoras após o incidente, pois encontrava-se em uma cidade sem hospital e em um local de difícil\nacesso para a equipe de resgate. À chegada, apresentava rotação externa de tornozelo e pé\ndireitos, sem lesões de continuidade na pele, porém com edema importante de partes moles abaixo\ndo joelho, hiperemia local e muita dor ao exame do local. Com relação a esse caso clínico, julgue o\nitem a seguir. A síndrome compartimental deve ser uma hipótese diagnóstica nesse caso, pois há\nsinais de fratura de tíbia, e o mecanismo de lesão deu-se por importante esmagamento muscular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-211935","number":"211935","sourceNumber":"211935","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 41 anos de idade, envolvido em colisão de carro em árvore, não\nutilizava cinto de segurança e foi ejetado\npara fora do veículo através do parabrisa. Deu entrada no\npronto-socorro do hospital levado pela equipe do Samu, em imobilização padrão, ventilando bem,\nsaturando 96% em AA, comatoso, Glasgow = 6, PA = 90 mmHg x 50 mmHg, FC = 135 bpm, FR =\n21 irpm, apresentando deformidade em coxa direita e braço direito. A ausculta pulmonar mostrou\nmurmúrios vesiculares uniformemente distribuídos bilateralmente. O exame do abdome foi\nprejudicado em função da condição neurológica do paciente. Com relação a esse caso clínico e aos\nconhecimentos médicos correlatos, acerca do trauma, assinale a alternativa correta.","options":{"A":"Os traumatismos são as causas menos comuns de morte em indivíduos entre 1 ano e 44 anos\nde idade.","B":"Nem todo paciente com trauma fechado tem lesão de coluna cervical; se, na avaliação primária\nna cena do acidente, a lesão for descartada\ncomo hipótese diagnóstica, o colar cervical não precisa\nser instalado no paciente.","C":"Esse paciente é um candidato para realização de tomografia computadorizada de abdome total\nde urgência, sem contraste, antes de se efetuar intervenção cirúrgica.","D":"A avaliação primária desse paciente deve seguir o protocolo ABCDE do Advanced Trauma Life\nSupport (ATLS), no qual a avaliação da via aérea é a primeira medida a ser tomada.","E":"Pneumotórax hipertensivo é uma das possibilidades diagnósticas para a causa do choque\ndescrito no paciente."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-179197","number":"179197","sourceNumber":"179197","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A via aérea dificil é sempre um desafio para a prática médica, portanto algumas\ntécnicas de resgate devem ser lembradas\nnessa situação de incapacitação para que seja realizada\numa intubação bem-sucedida. Considerando essa informação, assinale a alternativa que apresenta\num dispositivo que pode ser utilizado para canulização cega das vias aéreas.","options":{"A":"máscara laríngea","B":"máscara de Venturi","C":"máscara não reinalante","D":"cânula traqueal","E":"tubo traqueal"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-179195","number":"179195","sourceNumber":"179195","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente de 22 anos de idade foi levada em protocolo de trauma pelo serviço de\natendimento móvel de urgência ao pronto-socorro após ter sido atropelada em uma via pública. À\navaliação inicial, a paciente apresentava vias aéreas pérvias, mantendo frequência respiratória de\n18 irpm, com SpO? de 93%, PA de 90 x 65 mmHg, FC de 122 bpm e abertura ocular somente ao\nestímulo doloroso, com flexão anormal e sem resposta verbal. Havia uma laceração de\naproximadamente 5 cm no couro cabeludo e contusão em região temporal direita. Com base nessa\nsituação hipotética, assinale a alternativa que apresenta correta e respectivamente a pontuação\nsegundo a Escala de Coma de Glasgow (ECG) e a conduta imediata para a paciente.","options":{"A":"ECG 8 e iniciar suplementação de O2 com máscara de Venturi a 35%","B":"ECG 7 e realizar tomografia computadorizada de crânio sem contraste","C":"ECG 4 e encaminhar para craniectomia descompressiva","D":"ECG 6 e realizar intubação endotraqueal","E":"ECG 9 e realizar limpeza e sutura da lesão em couro cabeludo"},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-152082","number":"152082","sourceNumber":"152082","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considere hipoteticamente a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista, apresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir. Em\nacidentes como esse, é comum haver vítimas em massa, e deverá ser priorizado o atendimento a\nvítimas em risco iminente de morte e aos doentes com traumas multissistêmicos graves.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-152072","number":"152072","sourceNumber":"152072","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considere hipoteticamente a ocorrência de um acidente do tipo explosão após um raio\natingir certo tanque de combustível em uma usina onde vários funcionários estavam trabalhando.\nUma vítima foi levada ao pronto-socorro pelos bombeiros com imobilização cervical e em prancha\nrígida, e, segundo o socorrista, apresentava grande lesão penetrante em hemitórax direito, PA de\n90 mmHg x 60 mmHg, abertura ocular somente quando solicitado, pronunciando palavras\ndesconexas, e com flexão anormal a estímulos dolorosos. Evoluiu com FAST negativo e\nestabilidade hemodinâmica. A respeito do caso clínico apresentado, julgue o item a seguir. O\npaciente apresentado sofreu trauma cranioencefálico moderado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134952","number":"134952","sourceNumber":"134952","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Julgue o item a seguir, acerca de traumatismos toracoabdominais e geniturinários. A\nmanobra de Pringle é utilizada nos procedimentos de intervenção cirúrgica em traumatismos do\nfígado e pode ser mantida por até uma hora. Nas lesões das veias hepáticas e da veia cava\nintra-hepática, não há diminuição do sangramento durante a aplicação dessa manobra.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134968","number":"134968","sourceNumber":"134968","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Julgue o item a seguir, acerca de traumatismos toracoabdominais e geniturinários: os\ntraumatismos toracoabdominais contusos estão eventualmente associados com lesão do baço e do\nfígado. As lesões do baço, em sua maioria, necessitam de tratamento cirúrgico, ao passo que a\nmaior parte das lesões hepáticas são tratadas conservadoramente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-135066","number":"135066","sourceNumber":"135066","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Julgue o item subsequente, acerca de queda ocorrida com paciente idoso. Há uma\nassociação bem estabelecida entre o uso de psicoativos e quedas, sendo os antidepressivos, os\nansiolíticos, os neurolépticos e os hipnóticos os medicamentos mais envolvidos nesses episódios.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-134955","number":"134955","sourceNumber":"134955","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O trauma acidental ou intencional ocorrido em época de gestação é uma das principais\ncausas de morte de mulheres em idade\nreprodutiva. Com relação a esse assunto, julgue o item que\nse segue: Em mulheres no terceiro trimestre de gestação e com quadro de choque hipovolêmico, o\nsangue é desviado preferencialmente para o feto. Em decorrência disso, o cérebro e o coração\nmaterno tornam-se órgãos periféricos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-105532","number":"105532","sourceNumber":"105532","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Os cinco sinais considerados vitais para o paciente devem ser obtidos em exame\nclínico inicial em atendimento de emergência,\nporque dão informações valiosas para elaboração de\nhipóteses diagnósticas e impedem que sinais de morbidades mais frequentes passem\ndespercebidos. Considerando essas informações, assinale a alternativa que apresenta um deles.","options":{"A":"peso seco.","B":"saturação de oxigênio por oximetria de pulso.","C":"pH sanguíneo por gasometria arterial.","D":"diurese horária.","E":"pressão venosa central."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-105545","number":"105545","sourceNumber":"105545","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Durante o estabelecimento de uma via aérea definitiva por intubação endotraqueal no\npaciente politraumatizado, é fundamental que se confirme que o tubo traqueal esteja\nadequadamente localizado, evitando-se a intubação seletiva de algum brônquio pulmonar.\n\nConsiderando essas informações, assinale a alternativa que apresenta o melhor método para a\nconfirmação da correta localização do tubo traqueal na traqueia.","options":{"A":"ausência de ruídos respiratórios no epigastro.","B":"detector de dióxido de carbono (capnografia).","C":"gasometria arterial.","D":"radiografia de tórax.","E":"oximetria de pulso."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-105552","number":"105552","sourceNumber":"105552","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca do trauma torácico fechado, assinale a alternativa correta.","options":{"A":"Caracteristicamente, a contusão pulmonar sem fratura de costelas ocorre em pacientes idosos.","B":"A presença estimada de até 1.000 mL de sangue no espaço pleural é uma contraindicação para\na drenagem torácica fechada.","C":"A ruptura do diafragma é mais comumente diagnosticada do lado esquerdo.","D":"O sinal de alargamento do mediastino é patognomônico de ruptura da aorta.","E":"A traqueia é o local mais acometido após o trauma torácico fechado."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352362","number":"352362","sourceNumber":"352362","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 22 anos de idade, previamente saudável, foi trazido pelo SAMU\nseguindo um protocolo de trauma. Ele estava\nenvolvido em um acidente automobilístico, colidindo\ncom um objeto fixo, e não estava usando o cinto de segurança. Apresenta o sinal do \"\"olho de boi\"\".\nDurante a avaliação na sala de emergência, a ultrassonografia (e-FAST) revelou a imagem abaixo\n(corte para o esterno esquerdo - eixo longo). No exame físico, apresenta uma pontuação de 11 na\nEscala de Coma de Glasgow, pressão arterial de 82x58 mm Hg, frequência cardíaca de 144 bpm e\nfrequência respiratória de 32 irpm. Acerca do suporte avançado de vida no trauma (Advanced\nTrauma Life Support), o quadro apresentado e seus conceitos correlatos, julgue o item a seguir.\n\nAbafamento de bulhas cardíacas, turgência jugular e hipotensão não é esperado para o quadro em\ntela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352361","number":"352361","sourceNumber":"352361","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 22 anos de idade, previamente saudável, foi trazido pelo SAMU\nseguindo um protocolo de trauma. Ele estava\nenvolvido em um acidente automobilístico, colidindo\ncom um objeto fixo, e não estava usando o cinto de segurança. Apresenta o sinal do \"\"olho de boi\"\".\nDurante a avaliação na sala de emergência, a ultrassonografia (e-FAST) revelou a imagem abaixo\n(corte para o esterno esquerdo - eixo longo). No exame físico, apresenta uma pontuação de 11 na\nEscala de Coma de Glasgow, pressão arterial de 82x58 mm Hg, frequência cardíaca de 144 bpm e\nfrequência respiratória de 32 irpm. Acerca do suporte avançado de vida no trauma (Advanced\nTrauma Life Support), o quadro apresentado e seus conceitos correlatos, julgue o item a seguir. O\n\"sinal do olho de boi\" indica proptose aguda por provável hemorragia retrobulbar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352360","number":"352360","sourceNumber":"352360","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 22 anos de idade, previamente saudável, foi trazido pelo SAMU\nseguindo um protocolo de trauma. Ele estava\nenvolvido em um acidente automobilístico, colidindo\ncom um objeto fixo, e não estava usando o cinto de segurança. Apresenta o sinal do \"\"olho de boi\"\".\nDurante a avaliação na sala de emergência, a ultrassonografia (e-FAST) revelou a imagem abaixo\n(corte para o esterno esquerdo - eixo longo). No exame físico, apresenta uma pontuação de 11 na\nEscala de Coma de Glasgow, pressão arterial de 82x58 mm Hg, frequência cardíaca de 144 bpm e\nfrequência respiratória de 32 irpm. Acerca do suporte avançado de vida no trauma (Advanced\nTrauma Life Support), o quadro apresentado e seus conceitos correlatos, julgue o item a seguir. As\nsetas na imagem indicam a alteração que pode indicar o status clínico hemodinâmico do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366250","number":"366250","sourceNumber":"366250","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. Paciente vítima de traumatismo cranioencefálico (TCE) leve que\nao exame físico tem abertura ocular ao chamado por voz, que se encontra confuso e que localiza\ndor tem Escala de Coma de Glasgow (GCS) de 11.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366250.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366249","number":"366249","sourceNumber":"366249","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. São indicações de tomografia de crânio pelo alto risco de\nintervenção cirúrgica pacientes com TCE leve que apresentem: CGS <15 até 2 horas após o\ntrauma, vômitos(>2 episódios), idade superior à 65 anos e uso de anticoagulantes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366249.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366259","number":"366259","sourceNumber":"366259","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. As Figuras I e II apresentam um hematoma subdural e um\nhematoma epidural, respectivamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366259.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366248","number":"366248","sourceNumber":"366248","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. Em pacientes com hematoma subdurais é preciso estar atento ao\nintervalo lúcido que se dá entre o momento do trauma e a deterioração neurológica, apresentação\nclássica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366248.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366246","number":"366246","sourceNumber":"366246","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. O tratamento do TC pode incluir hidratação intravenosa, correção\nde coagulopatias, hiperventilação transitória bem como solução salina hipertônica ou manitol.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366246.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-366245","number":"366245","sourceNumber":"366245","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Acerca de suporte avançando de vida em trauma e considerando as imagens A e B\nacima, julgue o item subsecutivo. Embora a normocapnia seja preferida, a hipercapnia permissiva\natravés da hiperventilação lava reduz a PaCO2 o que causa vasodilatação cerebral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/366245.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-334869","number":"334869","sourceNumber":"334869","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 35 anos de idade, vítima de acidente automobilístico em que era o\nmotorista, foi ejetado do veículo, foi levado pelos bombeiros inconsciente, hipotenso com PA = 90\nmmHg x 60 mmHg, FC = 128 bpm e taquicárdico. Em relação ao atendimento inicial ao trauma,\npreconizado pelo Advanced Trauma Life Suport (ATLS), assinale a alternativa correta.","options":{"A":"As radiografias indicadas são de abdome, de tórax, de coluna cervical e de crânio.","B":"O volume inicial de líquidos a ser infundido é de 2.000 mL de soro aquecido.","C":"O paciente tem indicação de via aérea definitiva.","D":"Como o paciente está inconsciente, a principal hipótese é de traumatismo cranioencefálico.","E":"O uso do ácido tranexâmico é indicado após 24 horas, em sangramentos volumosos."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-343428","number":"343428","sourceNumber":"343428","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A técnica que permite a extração de um líquido anormal, acumulado no espaço pleural,\npor meio de uma agulha ou um cateter,\nintroduzido percutaneamente pela parede torácica até o\nespaço pleural, que pode ser utilizada para fins terapêuticos, quando a retirada do líquido da\ncavidade pleural diminui o quadro de insuficiência respiratória restritiva e com fins diagnósticos,\npara obter o líquido para análises bioquímica, citológica e microbiológica é a:","options":{"A":"Tapotagem.","B":"Toracostomia.","C":"Toracocentese.","D":"Toracopoiese."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-343441","number":"343441","sourceNumber":"343441","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos, é encaminhado ao hospital por ter sofrido coice\nde cavalo. Apresenta cefaleia leve e Glasgow 14. A TC de crânio sem contraste constatou\nTraumatismo Crânio Encefálico (TCE). Após algumas horas no leito, evoluiu com aumento da\nintensidade da cefaleia, rebaixamento do nível de consciência, náuseas e crise convulsiva e queda\nna escala de coma de Glasgow para 11. A alteração que revela o pior prognóstico do paciente é:","options":{"A":"Aumento da intensidade da cefaleia.","B":"Queda na pontuação da escala de coma de Glasgow.","C":"Crise convulsiva.","D":"Náusea."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-307090","number":"307090","sourceNumber":"307090","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um motociclista de 19 anos de idade foi levado à emergência após ser resgatado pelo\nServiço de Atendimento Móvel de Urgência, vítima de acidente automobilístico moto versus carro,\ncolisão frontal e cinemática grave. Na chegada, o paciente encontrava-se imobilizado em maca\nrígida, com imobilização de coluna cervical. A via aérea não estava pérvia, e o paciente tinha\ndificuldade de falar por causa da grande quantidade de sangue e fratura de face e maxila.\n\nConstataram- se murmúrio vesicular (MV) abolido à direita por meio de ausculta pulmonar,\nenfisema subcutâneo em hemitórax à direita, FR =\n25 irpm, FC = 128 bpm, PA = 140 x 110 mmHg,\nSatO2 = 91%, máscara com reservatório a 10 litros/minuto. Considerando esse caso clínico, a\navaliação inicial será interrompida, pois Alternativas:","options":{"A":"drenagem de tórax deve ser a conduta imediata.","B":"via aérea cirúrgica deve ser a conduta nesse momento.","C":"raios X de tórax, para confirmar diagnóstico de pneumotórax, estão indicados na avaliação\nprimária.","D":"toracotomia de urgência à direita está determinado.","E":"reposição de Ringer lactato e hemocomponentes está indicada nesse momento."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-307092","number":"307092","sourceNumber":"307092","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente vítima de politrauma grave por atropelamento por carro deu entrada na\nemergência conversando, referindo dor torácica à esquerda e dor em membro inferior esquerdo. Ao\nexame físico, foram verificados via aérea pérvia, ausculta pulmonar abolida à esquerda, normal à\ndireita, FR = 25 irpm, FC = 135 bpm, PA = 80 x 40 mmHg, Sat = 90% com O2, máscara a 10 litros\npor minuto, Glasgow 15, pupilas isocóricas e fotorreagentes. Na exposição, tem uma fratura\nexposta femoral à esquerda. Quanto ao manejo inicial desse caso clínico, a prioridade é","options":{"A":"fixação da fratura exposta.","B":"volume e transfusão sanguínea como conduta inicial.","C":"intubação orotraqueal por causa do quadro de insuficiência ventilatória grave.","D":"drenagem de tórax bilateral.","E":"toracocentese de alívio à esquerda para resolver o pneumotórax hipertensivo, seguido de\ndrenagem torácica à esquerda."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301264","number":"301264","sourceNumber":"301264","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 17 anos de idade chegou ao pronto-socorro com ferimento por arma de\nfogo no abdome, ocorrido há 30 minutos, na região de hipocôndrio direito. Na admissão,\nencontrava-se agitado, solicitando ajuda, e seus dados hemodinâmicos eram: PA = 60 mmHg X 40\nmmHg, pulso de 134 bpm e frequência respiratória de 32 ipm. Com base no caso clínico\napresentado, julgue os itens de 21 a 25. A reposição volêmica com soro fisiológico 0,9%, 3.000 mL\naberto, deve ser iniciada imediatamente, com o objetivo de elevar a pressão arterial, seguida de\navaliação da resposta hemodinâmica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301265","number":"301265","sourceNumber":"301265","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 17 anos de idade chegou ao pronto-socorro com ferimento por arma de\nfogo no abdome, ocorrido há 30 minutos, na região de hipocôndrio direito. Na admissão,\nencontrava-se agitado, solicitando ajuda, e seus dados hemodinâmicos eram: PA = 60 mmHg X 40\nmmHg, pulso de 134 bpm e frequência respiratória de 32 ipm. Com base no caso clínico\napresentado, julgue os itens de 21 a 25. A intubação orotraqueal é a primeira medida que deve ser\nrealizada para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301266","number":"301266","sourceNumber":"301266","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 17 anos de idade chegou ao pronto-socorro com ferimento por arma de\nfogo no abdome, ocorrido há 30 minutos, na região de hipocôndrio direito. Na admissão,\nencontrava-se agitado, solicitando ajuda, e seus dados hemodinâmicos eram: PA = 60 mmHg X 40\nmmHg, pulso de 134 bpm e frequência respiratória de 32 ipm. Com base no caso clínico\napresentado, julgue os itens de 21 a 25. O protocolo de transfusão maciça deve ser ativado\nimediatamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301267","number":"301267","sourceNumber":"301267","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 17 anos de idade chegou ao pronto-socorro com ferimento por arma de\nfogo no abdome, ocorrido há 30 minutos, na região de hipocôndrio direito. Na admissão,\nencontrava-se agitado, solicitando ajuda, e seus dados hemodinâmicos eram: PA = 60 mmHg X 40\nmmHg, pulso de 134 bpm e frequência respiratória de 32 ipm. Com base no caso clínico\napresentado, julgue os itens de 21 a 25. Nesses casos, a utilização de ácido tranexâmico traz\nvantagens para redução da mortalidade por hemorragia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301268","number":"301268","sourceNumber":"301268","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 17 anos de idade chegou ao pronto-socorro com ferimento por arma de\nfogo no abdome, ocorrido há 30 minutos, na região de hipocôndrio direito. Na admissão,\nencontrava-se agitado, solicitando ajuda, e seus dados hemodinâmicos eram: PA = 60 mmHg X 40\nmmHg, pulso de 134 bpm e frequência respiratória de 32 ipm. Com base no caso clínico\napresentado, julgue os itens de 21 a 25. A utilização do FAST (Focused Assessment with\nSonography for Trauma) abdominal é essencial para definição da conduta nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301274","number":"301274","sourceNumber":"301274","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 63 anos de idade, vítima de atropelamento há cerca de 40 minutos,\nchegou à sala de emergência queixando-se de\ndor em hemotórax direito e abdome. Ao exame,\nencontrava-se com Glasgow 15, pulso de 92 bpm, PA = 140 mmHg X 90 mmHg e presença de\nescoriação em região toracoabdominal à direita. Apresentava murmúrio vesicular presente\nbilateralmente e abdome plano, flácido, pouco doloroso em hipocôndrio direito. Realizou tomografia\ncomputadorizada de abdome, que mostrou moderada quantidade de líquido na cavidade, com uma\nlesão hepática grau III em segmentos V e VI, com presença de blush, sem outras lesões avaliadas.\nA respeito desse caso clínico, julgue os itens de 31 a 35. A laparotomia exploradora é a melhor\nmaneira de tratar esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301275","number":"301275","sourceNumber":"301275","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 63 anos de idade, vítima de atropelamento há cerca de 40 minutos,\nchegou à sala de emergência queixando-se de\ndor em hemotórax direito e abdome. Ao exame,\nencontrava-se com Glasgow 15, pulso de 92 bpm, PA = 140 mmHg X 90 mmHg e presença de\nescoriação em região toracoabdominal à direita. Apresentava murmúrio vesicular presente\nbilateralmente e abdome plano, flácido, pouco doloroso em hipocôndrio direito. Realizou tomografia\ncomputadorizada de abdome, que mostrou moderada quantidade de líquido na cavidade, com uma\nlesão hepática grau III em segmentos V e VI, com presença de blush, sem outras lesões avaliadas.\nA respeito desse caso clínico, julgue os itens de 31 a 35. O líquido livre na cavidade pode ser\njustificado apenas em razão da presença da lesão hepática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301276","number":"301276","sourceNumber":"301276","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 63 anos de idade, vítima de atropelamento há cerca de 40 minutos,\nchegou à sala de emergência queixando-se de\ndor em hemotórax direito e abdome. Ao exame,\nencontrava-se com Glasgow 15, pulso de 92 bpm, PA = 140 mmHg X 90 mmHg e presença de\nescoriação em região toracoabdominal à direita. Apresentava murmúrio vesicular presente\nbilateralmente e abdome plano, flácido, pouco doloroso em hipocôndrio direito. Realizou tomografia\ncomputadorizada de abdome, que mostrou moderada quantidade de líquido na cavidade, com uma\nlesão hepática grau III em segmentos V e VI, com presença de blush, sem outras lesões avaliadas.\nA respeito desse caso clínico, julgue os itens de 31 a 35. A arteriografia com angioembolização é\numa maneira muito efetiva para tratar esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301277","number":"301277","sourceNumber":"301277","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 63 anos de idade, vítima de atropelamento há cerca de 40 minutos,\nchegou à sala de emergência queixando-se de\ndor em hemotórax direito e abdome. Ao exame,\nencontrava-se com Glasgow 15, pulso de 92 bpm, PA = 140 mmHg X 90 mmHg e presença de\nescoriação em região toracoabdominal à direita. Apresentava murmúrio vesicular presente\nbilateralmente e abdome plano, flácido, pouco doloroso em hipocôndrio direito. Realizou tomografia\ncomputadorizada de abdome, que mostrou moderada quantidade de líquido na cavidade, com uma\nlesão hepática grau III em segmentos V e VI, com presença de blush, sem outras lesões avaliadas.\nA respeito desse caso clínico, julgue os itens de 31 a 35. A cirurgia de controle de danos promove\nbenefícios em pacientes com lesões hepáticas como essa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-301278","number":"301278","sourceNumber":"301278","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 63 anos de idade, vítima de atropelamento há cerca de 40 minutos,\nchegou à sala de emergência queixando-se de\ndor em hemotórax direito e abdome. Ao exame,\nencontrava-se com Glasgow 15, pulso de 92 bpm, PA = 140 mmHg X 90 mmHg e presença de\nescoriação em região toracoabdominal à direita. Apresentava murmúrio vesicular presente\nbilateralmente e abdome plano, flácido, pouco doloroso em hipocôndrio direito. Realizou tomografia\ncomputadorizada de abdome, que mostrou moderada quantidade de líquido na cavidade, com uma\nlesão hepática grau III em segmentos V e VI, com presença de blush, sem outras lesões avaliadas.\nA respeito desse caso clínico, julgue os itens de 31 a 35. O controle de hemoglobina e hematócrito\né uma maneira efetiva de avaliar o ressangramento de uma lesão hepática como a descrita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-268890","number":"268890","sourceNumber":"268890","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente sofre um ferimento por arma de fogo em tórax anterior direito, com\nferimento de saída no tórax posterior esquerdo. Chega à emergência intubado pela equipe do\natendimento pré-hospitalar, com murmúrio vesicular direito ausente e esquerdo presente.\n\nVerificam-se PA = 90 mmHg x 60 mmHg, FC =130 bpm, FR = 22 irpm e SatO2 = 85%. Com base\nnesse caso e nos conhecimentos médicos\nrelacionados ao trauma torácico, assinale a alternativa\ncorreta.","options":{"A":"É necessária a realização de raios X de tórax no leito, para determinar os procedimentos\nadequados.","B":"É essencial realizar uma angiotomografia o mais breve possível, se a drenagem torácica\napresentar débito de 1.800 mL logo após a passagem do dreno.","C":"É indicado toracotomia em um serviço de emergência, em situação de parada cardíaca, após\ntrauma penetrante do tórax.","D":"Necessita-se de uma endoscopia digestiva alta imediatamente, se houver saída de conteúdo\ngástrico no dreno torácico.","E":"O tratamento inicial deve ser uma toracocentese diagnóstica."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-291475","number":"291475","sourceNumber":"291475","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 40 anos, sexo masculino, cerca de 70 kg, lavado ao serviço de Urgência e\nEmergência por equipe dos Bombeiros, com relato de ter sofrido queda da laje de sua casa (cerca\nde 3 metros de altura) há 30 minutos. Familiar que o acompanhava relata que o paciente não\npossui comorbidades e não faz uso de medicações. Á admissão, o paciente apresentava\nfrequência cardíaca = 90 bpm, pressão arterial = 120 x 80 mmHg, saturação de oxigênio = 100%\ncom oxigênio suplementar sob máscara. Conversava e respondia ás perguntas do médico sem\ndificuldades e com frases ordenadas, mobiliza os 4 membros espontaneamente e havia abertura\nocular espontânea. O paciente relata que se lembra da queda e que \"bateu a cabeça no chão\".\n\nRealizou avaliação primária e secundária adequadas. Havia discreta equimose retroauricular e\nferida corto-contusa de 3 cm, superficial, em\nregião parietal direita. Exame físico do tórax e abdome\nsem alterações. Na avaliação secundária foi realizada tomografia computadorizada (TC) de crânio,\npescoço, tórax e abdome. TC crânio sem contraste: discreto hematoma extradural à direita.TC\npescoço, incluindo coluna cervical, com contraste venoso: sem alterações. TC de tórax e abdome\ncom contraste venoso: sem alterações. Cerca de 2 horas após o exame de tomografia, o paciente\napresentava-se com abertura ocular apenas ao estímulo doloroso e fala com palavras\ninapropriadas. Apresentou dois episódios de vômitos, FC = 62 bpm; PA = 180 x 110 mmHg. Pupila\ndireita em midríase e hemiparesia esquerda. Foi realizado novamente a avaliação primária, sem\noutras alterações além das descritas. Com os dados apresentados, assinale a alternativa que\ncontenha o diagnóstico, raciocínio e conduta corretos.","options":{"A":"O paciente apresentava, à admissão, trauma cranioencefálico moderado. Após as tomografias,\nevoluiu com choque hipovolêmico. Devem ser\nrepetidos os exames de tomografia para estabelecer\nlocal da hemorragia.","B":"O paciente apresentava, pelo resultado das tomografias, trauma cranioencefálico moderado.\n\nApós as tomografias, evoluiu com choque neurogênico. Deve ser realizado FAST (ultrassonografia\nabdominal focada para trauma) imediatamente\npara decidir sobre a necessidade de laparotomia\nexploradora.","C":"O paciente apresentava, á admissão, trauma cranioencefálico leve. Após as tomografias, evoluiu\ncom hipertensão intracraniana e herniação dos úncus. Deve ser realizada avaliação neurocirúrgica\nimediata para descompressão intracraniana.","D":"O paciente apresentava, à admissão, trauma cranioencefálico leve. Após tomografias, evoluiu\ncom choque de origem indeterminada. Deve ser realizada nova tomografia do crânio para avaliar\npossível alteração do hematoma visualizado inicialmente."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-273334","number":"273334","sourceNumber":"273334","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No trauma com queda à cavaleiro seguido de uretrorragia importante e equimose de\nperíneo, a conduta inicial que deve ser feita é:","options":{"A":"Sondagem uretral de demora com sonda de Foley.","B":"Cistostomia suprapúbica.","C":"Uretroscopia e vesicoscopia.","D":"Sondagem uretral de alívio com sonda de nelaton."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-266451","number":"266451","sourceNumber":"266451","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação aos achados de exames de imagem em paciente pediátrico, julgue o item\na seguir. Situação hipotética: Um escolar,\nvítima de um acidente de trânsito, deu entrada na\nemergência de um hospital, apresentando dor abdominal e hematuria macroscópica. Ele\nencontrava-se hemodinamicamente estável no exame clínico. Na abordagem diagnóstica, o médico\nassistente solicitou uma tomografia computadorizada com contraste das vias urinárias, a qual\nmostrou lacerações na cortical e hematomas perirrenais à direita. Assertiva: Nessa situação, a\nclassificação do trauma renal é de grau II e o tratamento deve ser conservador.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-263382","number":"263382","sourceNumber":"263382","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma jovem com 18 anos de idade que sofreu uma queda de bicicleta há 2 horas é\nlevada ao pronto-socorro. Seus familiares\nrelatam que ela não estava usando capacete e bateu a\ncabeça na calçada, quando perdeu momentaneamente a consciência por cerca de 1 minuto. Ao ser\natendida, apresenta-se consciente e orientada no tempo e no espaço, com abertura ocular\nespontânea e respondendo aos comandos verbais, com pupilas isocóricas e ausência de déficit\nneurológico. Ela se queixa de cefaleia discreta e não progressiva, além de tontura temporária, e\napresenta ainda ferimento cortocontuso de cerca de 3 cm no couro cabeludo, negando episódios\nde vômitos ou outros sintomas. Nessa situação, a conduta adequada a ser adotada, após a sutura\ndo ferimento, é","options":{"A":"manter a paciente em observação e realizar exame neurológico seriado por 24 horas.","B":"dar alta hospitalar, orientando a paciente e seus acompanhantes em relação aos sintomas de\nalarme.","C":"solicitar tomografia de crânio e, se o resultado for normal, dar alta hospitalar à paciente com\norientações.","D":"solicitar tomografia de crânio e indicar internação hospitalar da paciente para observação\nclínica\npor 24 horas."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-263386","number":"263386","sourceNumber":"263386","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma paciente com 34 anos de idade, vítima de acidente automobilístico, apresentando\ntrauma abdominal contuso sem evidência de\nlesões em outros segmentos corpóreos, foi levada ao\npronto-socorro do Centro de Referência de Trauma de nível terciário para atendimento. No\natendimento em cena pela equipe de suporte avançado do Serviço de Atendimento Móvel de\nUrgência (SAMU), foram infundidos 500 mL de ringer lactato. No exame físico da paciente,\n\nobteve-se os seguintes resultados: FC = 110 bpm, enchimento capilar = 6 segundos, PA = 100 x 70\nmmHg, Glasgow = 15. Houve normalização dos sinais vitais após a infusão de mais de 500 mL de\nsolução cristaloide no atendimento inicial. Os exames laboratoriais mostraram os seguintes\nresultados: Hb = 10,5 g/dL (valor de referência: 12 a 14 g/dL), Ht = 31 % (valor de referência: 35 a\n45 %), lactato = 2,8 mmol/L (valor de referência: < 2,0 mmol/L), INR = 1,0 (valor de referência:\n0,8 a\n1,2), fibrinogênio = 200 mg/dL (valor de referência: 185,0 a 400,0 mg/dL), plaquetas = 120 000/mm³\n(valor de referência: 100 000 a 420 000/mm³). A tomografia computadorizada do abdome com\ncontraste endovenoso é mostrada na imagem a seguir. Não foram evidenciadas outras lesões no\nabdome. Com base na história clínica, nos dados do exame físico e na imagem da tomografia, a\nconduta médica adequada é indicar","options":{"A":"laparotomia exploradora de urgência para tratamento da lesão hepática.","B":"controle clínico-laboratorial seriado e tratamento não operatório.","C":"angiografia e embolização para tratamento da lesão hepática.","D":"laparoscopia de urgência para hemostasia da lesão hepática."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/263386.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-263390","number":"263390","sourceNumber":"263390","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente com 23 anos de idade, do sexo masculino, vítima de acidente\nautomobilístico, foi trazido ao setor de\nTrauma pela equipe de suporte avançado do Serviço de\nAtendimento Móvel de Urgência (SAMU). Apresenta vias aéreas pérvias, ausculta pulmonar normal,\nPA = 100 x 60 mmHg, FC = 100 bpm, FR = 24 irpm, Glasgow = 14. Durante a inspeção, nota-se\nesquimose perineal. O paciente está com sonda vesical de duas vias com débito de 40 mL de\nsangue vivo. Queixa-se de dor intensa em hipogástrio, onde se nota abaulamento extremamente\ndoloroso à palpação que vai do púbis até cerca de 5 cm abaixo da cicatriz umbilical. Nesse caso, o\ndiagnóstico e a conduta médica inicial para esse paciente são","options":{"A":"trauma renal e tomografia computadorizada de abdome com contraste endovenoso.","B":"trauma de bexiga e colocação de sonda vesical em três vias para irrigação contínua.","C":"trauma de uretra e retirada da sonda vesical com cistostomia percutânea.","D":"obstrução da sonda vesical e desobstrução com irrigação sob pressão."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-263395","number":"263395","sourceNumber":"263395","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente com 25 anos de idade foi vítima de ferimento penetrante por arma de fogo\nem hemitórax esquerdo. O exame físico mostrou\nsinais vitais normais. No exame do hemitórax\nesquerdo, foi evidenciado orifício de entrada na linha axilar anterior a 1,5 cm acima da linha\nmamilar e orifício de saída em região posterior logo acima do ângulo da escápula do mesmo lado. A\nausculta pulmonar evidenciou abolição do murmúrio vesicular e maciez à percussão. A radiografia\nde tórax, realizada com o paciente em pé, é exibida a seguir. O diagnóstico e a conduta inicial\nindicada para esse paciente são","options":{"A":"hemopneumotórax e drenagem em selo d'água no quinto espaço intercostal.","B":"hemotórax e drenagem em selo d'água no quinto espaço intercostal.","C":"hemopneumotórax e toracocentese no quinto espaço intercostal.","D":"hérnia diafragmática e laparotomia exploradora."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/263395.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-291541","number":"291541","sourceNumber":"291541","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem com 38 anos de idade, aguardando em ponto de ônibus, foi atropelado por\nmotorista de veículo desgovernado e prensado contra a parede. Atendido em pronto-socorro de\nhospital terciário, referia muita dor na pelve, apresentava escoriações e contusões no hipogástrio e\nmembros inferiores, sem sinais de trauma torácico ou craniano. Apresentava instabilidade do anel\npélvico à palpação, pressão arterial = 80 x 40 mmHg, frequência cardíaca = 124 batimentos por\nminuto, 24 incursões respiratórias por minuto, tempo de enchimento capilar maior que 2 segundos e\nsaturação de oxigênio = 97%. Com base nos dados apresentados, qual deve ser o manejo inicial da\nvítima em relação ao quadro de choque?","options":{"A":"Radiografia de pelve anteroposterior na sala de emergência.","B":"Cinta ou lençol para estabilização pélvica e indicação precoce de infusão de hemocomponentes.","C":"Tratamento operatório para controle de danos em hemorragia retroperitoneal volumosa.","D":"Soluções cristaloides por acessos venosos periféricos e avaliação de ortopedista."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-244458","number":"244458","sourceNumber":"244458","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 37 anos de idade é atendido após trauma automobilístico, levado de\nambulância com referência de cinemática importante, com óbito na cena. Chega estável ao\natendimento, entretanto, após cerca de 45 minutos, passa a apresentar taquicardia e hipotensão,\nevoluindo para PCR em AESP. Depois do início das manobras de reanimação e de reavaliação do\nquadro, nota-se assimetria torácica. Com base nesse caso clínico e nos conhecimentos correlatos,\nquanto à possibilidade diagnóstica mais provável e ao procedimento a ser realizado, assinale a\nalternativa correta.","options":{"A":"Hemopneumotórax; drenagem torácica.","B":"Hemotórax; drenagem de tórax e autotransfusão.","C":"Contusão pulmonar; reposição volêmica.","D":"Pneumotorax; toracocentese de alívio.","E":"Hemopericardio; pericadiocentese."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-227368","number":"227368","sourceNumber":"227368","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de vinte e cinco anos de idade, vítima de acidente automobilístico com\ncapotamento ocorrido havia 8 horas, foi levado\nao pronto-socorro, onde deu entrada consciente,\norientado, imobilizado em prancha rígida, com colar cervical. O paciente apresentava sinais vitais\nnormais, quadro de dor em região cervical, abdominal e lacerações em membros superiores e\ninferiores. Com relação a esse caso clínico e aos múltiplos aspectos a ele relacionados, julgue o\nitem a seguir. Os exames radiológicos indicados para pacientes vítimas de politrauma são raios X\nde coluna cervical, tórax e pelve.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230582","number":"230582","sourceNumber":"230582","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O órgão sólido responsável pela MAIORIA dos choques hemorrágicos no trauma\nabdominal fechado é:","options":{"A":"Duodeno.","B":"Aorta.","C":"Fígado.","D":"Baço."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230583","number":"230583","sourceNumber":"230583","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"No tratamento do choque hemorrágico, durante o atendimento dos pacientes\npolitraumatizados, o MELHOR parâmetro para avaliar resposta à sua terapêutica inicial é:","options":{"A":"aumento da saturação de oxigênio.","B":"redução da frequência cardíaca.","C":"débito urinário satisfatório.","D":"hipertensão arterial."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230589","number":"230589","sourceNumber":"230589","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A droga anti-fibrinolítica que tem comprovação de redução na mortalidade dos doentes\npolitraumatizados em choques hemorrágicos é:","options":{"A":"Fitomenadiona.","B":"Succinilcolina.","C":"Ácido tranexâmico.","D":"Rivaroxabana."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230590","number":"230590","sourceNumber":"230590","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A intubação nasotraqueal é uma alternativa na garantia de uma via aérea definitiva. É\nCONTRAINDICADO em pacientes que apresentam:","options":{"A":"fratura cervical.","B":"apneia.","C":"hemotórax.","D":"trauma encefálico."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230596","number":"230596","sourceNumber":"230596","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente vítima de ferimento penetrante em tórax por arma branca, após 48h do\natendimento inicial e da drenagem de tórax, permanece com grande escape de débito aéreo pelo\ndreno. Mantém-se estável hemodinamicamente. A PRINCIPAL hipótese diagnóstica é:","options":{"A":"fístula brônquica.","B":"pneumotórax hipertensivo.","C":"lesão de grandes vasos.","D":"tamponamento cardíaco."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-230597","number":"230597","sourceNumber":"230597","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 53 anos, chega em sala de trauma trazido pelos bombeiros após\nespancamento em via pública. É transportado com colar cervical e prancha rígida. Apresenta\nrespiração ruidosa, frequência respiratória de 26 irpm, pressão arterial de 80 x 30 mmHg,\nfrequência cardíaca de 130 bpm. A conduta IMEDIATA é:","options":{"A":"administração de 1g de ácido tranexâmico.","B":"transfundir 1 unidade de sangue O negativo.","C":"drenagem de tórax.","D":"desobstrução de vias aéreas e oferta de oxigênio."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-202967","number":"202967","sourceNumber":"202967","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 28 anos de idade, vítima de acidente de motocicleta, deu entrada no\npronto-socorro com quadro de dor abdominal, pressão arterial de 90 mmHg x 40 mmHg e\nfrequência cardíaca de 120 bpm. Ao exame físico, estava consciente e orientado e apresentava dor\nà palpação no abdome. Acerca desse caso clínico, qual é a conduta mais indicada, nesse\nmomento, em relação ao trauma abdominal?","options":{"A":"Laparotomia exploradora.","B":"Tomografia de abdome.","C":"Lavado peritoneal diagnóstico.","D":"Videolaparoscopia diagnóstica.","E":"Cistografia retrógrada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212078","number":"212078","sourceNumber":"212078","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o item a seguir. Uma\ndas causas mais comuns para morte tardia desses\npacientes é a embolia pulmonar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212051","number":"212051","sourceNumber":"212051","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o próximo item. O\nposicionamento mais adequado para o exame inicial da vítima é o decúbito dorsal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212056","number":"212056","sourceNumber":"212056","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o próximo item. Na\nsequência de avaliação primária ABCDE, a letra \"C\" representa o controle das vias aéreas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-212067","number":"212067","sourceNumber":"212067","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito de pacientes acometidos por traumas graves, julgue o item a seguir. A\npresença de bile, bactérias ou fibras alimentares em um Lavado Peritoneal Diagnóstico (LPD) é\nindicativo de laparotomia exploradora de urgência.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-175087","number":"175087","sourceNumber":"175087","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Durante manobras de reanimação de uma vítima de Infarto, ocorreu dificuldade de\nentubação traqueal. Assim, você solicitou ao\nChefe da Emergência a aquisição de material\nalternativo a Tubo Oro traqueal, o Chefe da Emergência, por sua vez, pediu a você que o ajudasse\na fundamentar o uso do material para o setor de compras. Nessa fundamentação, foram utilizadas\njustificativas técnicas a respeito do Tubo Esofágico Traqueal (Combitube) que estão listadas\nabaixo, porém, uma delas está INCORRETA, indique-a:","options":{"A":"Consiste num dispositivo composto de 2 tubos em paralelo, a intubação ocorre às cegas.","B":"O tubo número 1, com cuff distal, e um tubo número 2, com cuff distal.","C":"Na maioria dos casos (mais de 90% dos casos), intuba-se o esôfago. Após a inserção do tubo,\ninsufla-se primeiro o cuff com 85ml de ar e, após, o cuff distal com 12ml de ar.","D":"Conecta-se o dispositivo bolsa-válvula-máscara ao tubo número 1 e realiza-se a ventilação dos\npulmões. Caso haja a expansão do tórax, o tubo foi inserido no esôfago e, portanto, deve-se\nmanter a ventilação por este tubo."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183893","number":"183893","sourceNumber":"183893","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. A escala de coma\nde Glasgow (ECG) baseia-se na melhor resposta\nocular, motora e sensitiva do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183849","number":"183849","sourceNumber":"183849","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. Grandes\nhemorragias devem ser tratadas, inicialmente,\ncom controle dos focos de sangramento e reposição\nvolêmica com sangue total.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-183858","number":"183858","sourceNumber":"183858","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Com relação aos pacientes politraumatizados, julgue o item a seguir. Contusões\nmiocárdicas de traumas torácicos contusos\nfrontais podem ocasionar parada cardiorrespiradória\n(PCR) por fibrilação ventricular, quadro que exige imediata ressuscitação cardiopulmonar (RCP)\nseguida de cardioversão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-175133","number":"175133","sourceNumber":"175133","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A respeito do tórax instável no atendimento inicial do politraumatizado, é INCORRETO\nafirmar:","options":{"A":"É uma lesão da parede torácica que gera movimento paradoxal de um de seus segmentos.","B":"O tratamento imediato deve ser a drenagem pleural em selo d?água.","C":"O tratamento definitivo possui como foco principal a estabilização esquelética.","D":"São indicações para ventilação mecânica no tórax instável: frequência respiratória maior que\n35/min; Pressão parcial de oxigênio arterial < 60 mmHg com Fração inspirada de Oxigênio > 50%."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-154487","number":"154487","sourceNumber":"154487","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Adulto jovem do sexo masculino, vítima de colisão automobilística contra anteparo há\ncerca de 1h. Equipe de socorristas revela\nque o mesmo usava cinto de segurança. Exame físico à\nadmissão hospitalar: consciente, orientado, dispneico, murmúrio vesicular abolido à direita,\nsubmacicez à percussão de todo o hemitórax direito, ausência de turgência jugular; frequência\ncardíaca = 118 bpm; pressão arterial = 112 x 74 mmHg; frequência respiratória = 38 irpm. Qual é a\nlesão torácica MAIS provável no caso descrito?","options":{"A":"Tamponamento cardíaco.","B":"Pneumotórax hipertensivo à direita.","C":"Ruptura brônquica à esquerda.","D":"Ruptura diafragmática à direita.","E":"Hemotórax à direita."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-154506","number":"154506","sourceNumber":"154506","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Dentre as opções abaixo, assinale a única medida que não pode ser utilizada como\nestratégia para redução de pressão intracraniana em contexto de neurotrauma:","options":{"A":"Elevação de cabeceira em 30º.","B":"Uso de solução salina hipertônica.","C":"Sedação profunda com barbitúricos.","D":"Hipotermia induzida.","E":"Hipercapnia permissiva."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-159597","number":"159597","sourceNumber":"159597","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Julgue o item a seguir, relativo a condições associadas a pacientes politraumatizados.\nO choque neurogênico que pode ocorrer no\npaciente politraumatizado decorre de traumatismo\nraquimedular e caracteriza-se por queda do retorno venoso, determinado pela vasodilatação\nperiférica, o que gera taquicardia e hipotensão, que não respondem à reposição volêmica em\nvirtude da vasoplegia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-159499","number":"159499","sourceNumber":"159499","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Pessoa vítima de ferimento por arma branca no hemitórax esquerdo foi trazida pelo\nSAMU com intensa dificuldade respiratória,\nqueixando-se de intensa dor torácica, que se\nintensificava com a respiração. Após exame físico, constatou-se ferimento causado por objeto\nperfurocortante ao nível do sexto espaço intercostal do hemitórax esquerdo, na linha hemiclavicular,\nalém de turgência jugular, abolimento do murmúrio vesicular e diminuição do timpanismo no\nhemitórax esquerdo. Com base no caso clínico apresentado, julgue o item a seguir. O paciente do\ncaso clínico em apreço encontra-se com provável hemopneumotórax à esquerda e deve ser\nsubmetido imediatamente à drenagem torácica fechada na sala trauma, com administração de\nterapêutica de antibiótico, que deve ser mantida por pelo menos cinco dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-158063","number":"158063","sourceNumber":"158063","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Chega à emergência do pronto-socorro um paciente de 18 anos de idade, vítima de\nacidente automobilístico. Ele era condutor de moto e chocou-se contra um poste, em alta\nvelocidade, cinemática grave. O paciente encontra-se acordado em ventilação espontânea, com\nausculta pulmonar simétrica bilateral; FR = 25 irpm; FC = 140 bpm; PA = 80 mmHg x 60 mmHg;\ncom abdome distendido, com dor e descompressão brusca. O quadril é estável. Apresenta uma\nfratura no tornozelo direito, mas sem comprometimento de tecidos moles nesse local, e o restante\ndo exame físico é normal. O eco-fast (ultrassom), realizado na sala de emergência, confirma o\nachado de líquido a cavidade peritoneal. Considerando esse caso clínico, após a estabilização da\nvia aérea, a próxima conduta é:","options":{"A":"Realizar laparotomia de urgência, em razão do choque hemodinâmico.","B":"Realizar raios X de crânio, tórax, abdome e pelve.","C":"Fixar a fratura do tornozelo.","D":"Transferir o paciente para a unidade de terapia intensiva para estabilização hemodinâmica por\nmeio de politransfusão.","E":"Realizar tomografia de abdome para identificação da origem do sangramento."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-158061","number":"158061","sourceNumber":"158061","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente de 18 anos de idade, do sexo masculino, é vítima de acidente automobilístico,\ncinemática importante, colisão frontal em alta\nvelocidade. Ele chega à emergência com via aérea\npérvia, em ventilação espontânea, sem sinais de choque circulatório, Glasgow 13, com dor torácica\nimportante em hemitórax direito, com fraturas costais visíveis à direita, em que a ausculta\n\nencontra-se abolida. Após a realização de drenagem de tórax, o paciente permanece com escape\nimportante pelo dreno de tórax, sem expansão pulmonar nos raios X de controle. Nesse caso\nclínico, a próxima conduta é realizar:","options":{"A":"Tomografia computadorizada de abdome.","B":"RNM de tórax.","C":"Raios X de tórax em decúbito lateral esquerdo.","D":"Fibrobroncoscopia.","E":"Raios X de estômago, esôfago e duodeno contrastados."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-168448","number":"168448","sourceNumber":"168448","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem com 24 anos de idade, vítima de ferimento por arma de fogo há 2 horas,\nrecebeu atendimento na Unidade de Pronto-Socorro. À admissão, estava consciente, descorado\n\n+/4, tendo a avaliação dos sinais vitais apresentado os seguintes resultados: pressão arterial = 130\nx 90 mmHg (simétrica nos membros\nsuperiores); frequência cardíaca = 102 bpm; frequência\nrespiratória = 28 irpm; saturação de O2 = 96%. No exame físico do paciente, a semiologia pulmonar\nmostrou-se normal e não foram encontradas alterações em pulsos periféricos, nem presença de\nsopros à ausculta cardíaca; observou-se orifício de entrada do projétil de arma de fogo na linha de\nintersecção do segundo espaço intercostal esquerdo com a linha hemiclavicular, mas não orifício de\nsaída do referido projétil. Segue, abaixo, uma imagem da radiografia do tórax solicitada. (Conforme\nimagem no caderno de questões) Com base nos dados clínicos e radiológicos, quais são o\ndiagnóstico e a conduta médica adequados?","options":{"A":"Hérnia diafragmática; toracofrenolaparotomia.","B":"Hemotórax; drenagem torácica com selo d'água sob aspiração.","C":"Tamponamento cardíaco; pericardiocentese seguida de esternotomia.","D":"Lesão aórtica; estudos complementares como tomografia e aortografia"},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/168448.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-168498","number":"168498","sourceNumber":"168498","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Durante plantão na central de regulação de urgência, o técnico auxiliar de regulação\nmédica transfere para o médico regulador uma\nchamada telefônica durante a qual ele deve orientar\nos cuidados iniciais para uma vítima de acidente de trabalho com serra elétrica. O paciente, um\noperário do sexo masculino, com 20 anos de idade, sofreu amputação do polegar direito e\nencontra-se consciente e orientado, apresentando sangramento local, que cessa à compressão\nmanual do coto de amputação. Havendo a intenção de reimplante do membro amputado, além de\ncobrir o ferimento no coto com pano limpo, que orientações deverão ser dadas pelo médico\n\nregulador, por telefone, até a chegada da ambulância ao local do chamado e posterior condução do\npaciente à unidade hospitalar especializada?","options":{"A":"Efetuar garrote no punho; lavar o dedo amputado em água corrente e colocá-lo em recipiente\ncom gelo cobrindo-o completamente.","B":"Efetuar compressão local; lavar o dedo amputado em água corrente e colocá-lo em recipiente\ncom gelo, cobrindo-o completamente.","C":"Efetuar garrote no punho; cobrir o dedo amputado com pano limpo e colocá-lo em um saco\nplástico e, depois, em um recipiente com gelo.","D":"Efetuar compressão local; cobrir o dedo amputado com pano limpo e colocá-lo em um saco\nplástico e, depois, em um recipiente com gelo."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-168500","number":"168500","sourceNumber":"168500","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Uma mulher com 18 anos de idade dá entrada na Unidade de Emergência com\nferimento cervical por arma branca. A paciente\nencontra-se consciente e orientada, porém muito\nassustada. À admissão, os sinais vitais da paciente são: saturação de O² = 96%; pressão arterial =\n110 x 75 mmHg; frequência respiratória = 22 irpm; frequência cardíaca = 112 bpm. O exame do\npescoço evidencia um ferimento lacerocontuso de 1,5 cm não sangrante, sem escape de ar ou\nsaliva, localizado em zona II à direita. Nesse caso, a conduta adequada a ser adotada na Unidade\nde Emergência é","options":{"A":"realizar endoscopia digestiva alta, laringoscopia, tomografia e arteriografia cervical.","B":"realizar cervicotomia exploradora de forma mandatória devido à alta probabilidade de lesões\nassociadas.","C":"explorar o ferimento sob anestesia local e, se a lesão ultrapassar o platisma, indicar\ncervicotomia\nexploradora.","D":"suturar a lesão, se o quadro clínico se mantiver estável, pois a extensão da lesão não demanda\nabordagem cirúrgica."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-168489","number":"168489","sourceNumber":"168489","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um menino com 12 anos de idade é levado ao Pronto-Socorro de um hospital de\nreferência por uma unidade de suporte avançado, após acidente de carro com colisão frontal. O\npaciente recebeu 2 litros de Ringer Lactato e foi mantido sob máscara de oxigênio a 10 L/min.\n\nQueixava-se de dor abdominal difusa de forte intensidade e referia que estava usando cinto de\nsegurança de dois pontos quando se\nacidentou. Ao exame físico, apresentou: pressão arterial = 80\nx 60 mmHg; frequência cardíaca = 122 bpm; frequência respiratória = 26 irpm; Glasgow = 13;\ntemperatura esofágica = 34,0 °C. Os exames laboratoriais realizados na ocasião mostraram: Hb =\n9,0 g/dL (valor de referência: 12 a 14 g/dL); Ht = 27% (valor de referência: 36 a 42%);\nfibrinogênio =\n65 mg/dL (valor de referência: 150 a 400 mg/dL); INR = 1,7 (valor de referência: < 1,3); gasometria\narterial com pH = 7,26 (valor de referência: 7,35 a 7,45), pO2 = 222 mmHg (valor de referência: >\n80 mmHg), pCO2 = 29 mmHg (valor de referência: 35 a 45 mmHg), HCO3 = 18 (valor de referência:\n22 a 26); BE = -6 (valor de referência: +2 a -2); saturação de O2 = 100% (valor de referência: > ou\nigual 94%); lactato = 3,8 (valor de referência < 2). O resultado da tomografia de abdome do\npaciente mostrou lacerações esplênica e hepática grau IV, e grande distensão de alças de intestino\ndelgado. Mesmo com transfusão maciça, o paciente evoluiu com episódios frequentes de\nhipotensão arterial. Nesse caso, as condutas indicadas são","options":{"A":"embolização arteriográfica das lesões do baço e do fígado.","B":"tratamento conservador, não operatório, do baço e do fígado.","C":"laparotomia exploradora com esplenectomia e rafia da lesão hepática.","D":"laparotomia exploradora com esplenectomia, packing hepático e peritoniostomia."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-128997","number":"128997","sourceNumber":"128997","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Ao se realizar o toque retal durante a avaliação primária de um homem\npolitraumatizado, foi encontrado sangue em\ndedo de luva. Acerca desse achado clínico, assinale a\nalternativa correta.","options":{"A":"Está geralmente associado com lesão da próstata.","B":"É compatível com trauma intestinal.","C":"É contraindicação para o cateterismo vesical.","D":"É patognomônico de fratura pélvica.","E":"Indica a realização de retossigmoidoscopia imediata."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-129000","number":"129000","sourceNumber":"129000","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A avaliação das vias aéreas e da ventilação representa etapa prioritária no atendimento\nao paciente politraumatizado. A respeito dessa\navaliação, assinale a alternativa correta.","options":{"A":"A intoxicação exógena é a principal causa de agitação e torpor nesses pacientes.","B":"O oxímetro de pulso fornece informações seguras a respeito da ventilação do paciente.","C":"A manobra de elevação do mento deve ser associada com a hiperextensão do pescoço antes da\nintubação traqueal.","D":"A cânula orofaríngea não deve ser utilizada em pacientes conscientes, pois pode levar ao\nreflexo do vômito e à sua aspiração.","E":"A intubação orotraqueal é contraindicada no paciente em apneia."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111328","number":"111328","sourceNumber":"111328","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Assinale a alternativa que apresenta achados que correspondem a um escore 9 na\nEscala de Coma de Glasgow:","options":{"A":"Abertura ocular ? à dor; melhor resposta verbal ?\npalavras inapropriadas; e melhor resposta motora ?\nretirada à dor.","B":"Abertura ocular ? à dor; melhor resposta verbal ?\npalavras inapropriadas; e melhor resposta motora ?\nextensão hipertônica à dor.","C":"Abertura ocular ? espontânea; melhor resposta verbal ? confuso; e melhor resposta motora\n\n? retirada à dor.","D":"Abertura ocular ? ao comando verbal; melhor\n\nresposta verbal ? sons incompreensíveis; e melhor resposta motora ? flexão hipertônica à dor.","E":"Abertura ocular ? nenhuma; melhor resposta verbal ? confuso; e melhor resposta motora\n\n? localiza a dor."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111343","number":"111343","sourceNumber":"111343","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o trauma torácico assinale a alternativa INCORRETA:","options":{"A":"As fraturas de costelas são as lesões mais comuns do trauma de tórax.","B":"Lesões intratorácicas graves podem ocorrer em crianças na ausência de fraturas costais, pela\nelasticidade da caixa torácica.","C":"O diagnóstico de Pneumotórax hipertensivo deve ser feito com raio X que mostra\nhipertransparência do hemitórax afetado com desvio no mediastino.","D":"Quando existe a necessidade de ventilação\n\nmecânica é indicada a drenagem torácica se houver diagnóstico de pneumotórax, mesmo que de\npequena monta.","E":"O principal critério para indicação de toracotomias são a instabilidade hemodinâmica e a\nnecessidade de reposição sanguínea."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-104776","number":"104776","sourceNumber":"104776","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considerando as medidas auxiliares à avaliação primária e à reanimação no paciente\npolitraumatizado, assinale a alternativa correta.","options":{"A":"A monitorização eletrocardiográfica está indicada apenas nos pacientes com arritmias ou uso\ncrônico de medicação cardiológica.","B":"A pressão arterial traduz o estado real de perfusão tecidual.","C":"A saturação de hemoglobina pelo oxigênio obtida por oximetria de pulso deve, assim que\npossível, ser comparada com a gasometria arterial.","D":"A sondagem gástrica está indicada para monitorar o sangramento gastrointestinal alto\nrelacionado com úlceras de estresse.","E":"A presença de sangue no meato uretral no homem, ao contrário do que ocorre na mulher, não\naumenta a suspeita de lesão uretral associada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111294","number":"111294","sourceNumber":"111294","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"É correto afirmar que:","options":{"A":"O pneumotórax aberto permite a realização do RX para se firmar o diagnóstico e estabelecer a\nconduta adequada.","B":"O pneumotórax hipertensivo deve ser drenado, imediatamente após a realização de Rx na sala\nde emergência.","C":"O tamponamento cardíaco deve ser tratado imediatamente com toracotomia, na sala de\nemergência.","D":"O hemotórax maciço deve ser tratado com a drenagem de tórax correspondente.","E":"A contusão pulmonar é tratada oferecendo oxigênio, analgesia e, muitas vezes, ventilação\nmecânica."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111302","number":"111302","sourceNumber":"111302","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem, 23 anos, vítima de acidente de motocicleta, chega ao pronto-socorro de um\nhospital com todos os recursos para o atendimento, com colar cervical e prancha longa. Está com\nintubação orotraqueal sob ventilação mecânica. Pulmões com murmúrio vesicular abolido à direita e\ntimpanismo à percussão. PA = 130/70 mmHg; FC = 90 bpm. Boa perfusão periférica. Apresenta\nsinais clínicos de fratura de bacia. Recebe avaliação e tratamento iniciais adequados e efetivos e\nentão o médico assistente indica tomografia de crânio, tórax e abdome. Qual dos procedimentos\nabaixo deverá ser realizado na sala de emergência após o paciente retornar da tomografia?","options":{"A":"Passar sondas nasogástrica e vesical.","B":"Drenar o tórax à direita.","C":"Realizar radiografia simples de bacia.","D":"Realizar compressão da bacia com lençol.","E":"Reavaliar a avaliação primária."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111319","number":"111319","sourceNumber":"111319","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem, 32 anos, vítima de queda de 12 metros, chega ao pronto socorro e na\navaliação inicial apresenta: PA=100/60 mmHg,\nFC=96 bpm, FR=38 ipm, Glasgow=7. É realizada\nsedação, intubação orotraqueal, ventilação mecânica e há dificuldade em manter-se uma boa\nsaturação de oxigênio. Pulmões com murmúrio vesicular bastante diminuído à esquerda com\nausculta nítida de ruídos hidroaéreos no tórax. Abdome está plano e flácido. A radiografia de tórax\nmostra hérnia diafragmática volumosa à esquerda. O serviço hospitalar não dispõe de equipamento\npara videocirurgia. É indicado tratamento operatório e quanto à via de acesso cirúrgica inicial:","options":{"A":"Deve ser por toracotomia esquerda.","B":"Deve ser por laparotomia.","C":"Pode ser por laparotomia ou por toracotomia esquerda.","D":"Deve ser por toracofrenolaparotomia esquerda.","E":"Pode ser por bitoracotomia."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-111340","number":"111340","sourceNumber":"111340","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente com 72 anos, internado na Unidade deTerapia Intensiva, em tratamento de\nbroncopneumonia, sob ventilação mecânica. Há 30 minutos foi submetido à passagem de cateter\nvenoso central em veia subclávia direita. Evoluindo com hipotensão, turgência jugular e com\nsaturação de oxigênio de 70%. Qual será provavelmente a melhor conduta?","options":{"A":"Iniciar noradrenalina.","B":"Colher gasometria arterial para otimizar os parâmetros ventilatórios.","C":"Realizar imediatamente radiografia do tórax.","D":"Puncionar o hemitórax direito no segundo espaço intercostal.","E":"Trocar a cânula de intubação."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-359199","number":"359199","sourceNumber":"359199","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um motociclista de 26 anos sofreu um acidente automobilístico, chocando-se com um\nposte elétrico. Ele estava sem capacete e apresentava lesões maxilofaciais com fraturas e\nsangramento ativo. Foi levado ao Pronto-socorro e, na admissão, apresentava PA = 160x84mmHg,\nFC = 92bpm e FR = 29irpm. Ele está agitado, não cooperativo, com dificuldade respiratória e\ndeformidade anatômica importante. A MELHOR conduta para garantir via aérea pérvia desse\npaciente é realizar a:","options":{"A":"Traqueostomia aberta.","B":"Intubação nasotraqueal.","C":"Traqueostomia percutânea.","D":"Cricotireoidostomia cirúrgica."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352195","number":"352195","sourceNumber":"352195","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente masculino, jovem e previamente hígido, vítima de acidente automobilístico,\nsem uso de cinto de segurança, ejetado do\nveículo, deu entrada gravíssimo à unidade de\nemergência, trazido pelo SAMU já intubado, apresentando enfisema subcutâneo em tórax, desvio\ntraqueal para a esquerda, turgência jugular e murmúrio vesicular abolido em hemitórax direito,\nfrequência cardíaca de 148bpm, pressão arterial de 88/52mmHg. Assinale a alternativa correta:","options":{"A":"Após confirmação radiológica, deve-se proceder a toracostomia com drenagem pleural fechada.","B":"O paciente encontra-se com choque classe IV e a prioridade deve ser a hemotransfusão.","C":"O eFAST (FAST estendido, sendo FAST \"\"Focused assessment with sonografy for trauma\"\") não\ntem valor em cenários como este, já que somente analisa janelas abdominais e pericárdio.","D":"A toracostomia com agulha é a medida prioritária e deve ser realizada no 5º espaço intercostal à\ndireita."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-368193","number":"368193","sourceNumber":"368193","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um jovem com 20 anos de idade é levado ao pronto-socorro com um ferimento\ntoracoabdominal por arma branca, em\nhemitórax esquerdo, acima do rebordo da última costela na\nlinha hemiclavicular. Está alerta, bem orientado e hemodinamicamente estável. A radiografia de\ntórax revela pneumotórax de 30%. Após a avaliação inicial desse paciente, o(s) passo(s)\nsubsequentes(s) consiste(m) em","options":{"A":"drenagem do tórax, laparotomia ou laparoscopia.","B":"exploração do local do ferimento e drenagem do tórax.","C":"observação clínica rigorosa.","D":"exploração local do ferimento e controle radiológico do tórax."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352200","number":"352200","sourceNumber":"352200","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A máscara laríngea é um dispositivo supraglótico idealizado para manter a via aérea\npatente em pacientes submetidos a\nprocedimentos anestésicos convencionais e usada no acesso\nda via aérea difícil. Considerando os cenários de via aérea e o dispositivo em questão, podemos\nafirmar:","options":{"A":"A máscara laríngea pode substituir o tubo traqueal servindo de via aérea avançada nas\nsituações de urgência (\"\"ventilo, mas não intubo\"\") ou nas emergências (\"\"não ventilo e não\nintubo\"\").","B":"O tamanho da máscara laríngea a ser utilizada em um paciente não é um fator crítico da sua\neficiência, já que todos os tamanhos são ajustáveis para cada tipo de paciente.","C":"A máscara laríngea protege a via aérea de broncoaspiração em casos de regurgitação, podendo\nser mantida com segurança em pacientes com\nestômago cheio.","D":"Não há na literatura corrente qualquer relato de complicações com o uso da máscara laríngea."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-352201","number":"352201","sourceNumber":"352201","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente de 24 anos é levando ao Pronto Socorro após ser baleado durante uma\nbriga de rua. No caminho para hospital, o\npaciente apresentou rebaixamento no nível de\nconsciência e necessitou de intubação. Ele também recebeu 2000 ml de soro fisiológico 0,9%. Na\nchegada ao hospital, a pressão arterial era de 86/40 mmHg e o pulso era de 130 bpm. A traqueia\nestá centrada na linha média e os sons respiratórios são iguais bilateralmente. Os sons cardíacos\nsão normais. Dois ferimentos por arma de fogo estão presentes: um no sexto espaço intercostal\nesquerdo, logo lateral à linha hemiclavicular, e outro no sétimo espaço intercostal esquerdo,\nposteriormente. A avaliação ultrassonografia para trauma (FAST) não revela derrame pericárdico e\né duvidosa para líquido livre intraperitoneal. A transfusão de sangue não cruzado está pendente.\n\nQual a melhor conduta a ser adotada para esse paciente?","options":{"A":"Tomografia computadorizada do abdomen e tórax.","B":"Toracostomia com drenagem pleural fechada.","C":"Laparatomia exploradora.","D":"Toracotomia exploradora."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-359197","number":"359197","sourceNumber":"359197","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Criança de 7 anos chega ao Pronto Socorro vítima de queda de laje há 30 minutos.\nSegundo a acompanhante, imediatamente após o\ntrauma, o paciente apresentou perda de\nconsciência e um episódio de vômito. À admissão, encontrava-se com 15 pontos na Escala de\nComa de Glasgow, com pupilas isocóricas fotorreagentes, sem déficits. Realizado Raio X simples\nde crânio: constatou-se fratura em região temporal direita. Enquanto aguardava Tomografia de\nCrânio, evoluiu com rebaixamento do nível de consciência (11 pontos na Escala de Coma de\nGlasgow), hemiparesia esquerda e anisocoria D>E. Assinale a alternativa que apresenta a hipótese\nMAIS provável.","options":{"A":"Hematoma Subdural agudo com herniação uncal.","B":"Lesão Axonal Difusa.","C":"Contusão Temporal Esquerda.","D":"Hematoma Extradural com herniação uncal."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-351592","number":"351592","sourceNumber":"351592","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 60 anos de idade foi encontrado à beira da estrada em dia frio e\nchuvoso, próximo a um carro capotado. Ao chegar\nao Serviço de Emergência, apresentava\nescoriações em face e abdome, pulsos carotídeos fracos e filiformes, temperatura igual a 34°C, FC\n\n= 40bpm, Pressão Arterial inaudível e 3 pontos na escala de coma Glasgow, não se conseguindo\nacesso venoso periférico. Nesse caso, é CORRETO\nafirmar que a conduta imediata é:","options":{"A":"Adrenalina intracardíaca.","B":"Acesso venoso central.","C":"Massagem cardíaca externa.","D":"Administração de sangue e Ringer com lactato morno."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-373562","number":"373562","sourceNumber":"373562","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente masculino, é transferido ao centro de trauma após queda de altura durante\natividade laboral (aproximadamente 10 metros)\nhá 1 hora. Foi atendido pela equipe de resgate\npré-hospitalar e devido aos sinais de choque, foram administrados durante o transporte 1000ml de\n\nringer lactato aquecido, 1g de ácido tranexâmico, 4mg de morfina e 1g de dipirona. Sai da cena do\nacidente com quadro neurológico avaliado em escala de coma de Glasgow de 11 pontos. É\ntransferido em prancha rígida, com colar cervical, máscara de oxigênio 15l/min, dois acessos\nperiféricos calibrosos, com manta térmica. É admitido com os seguintes sinais vitais: Pressão\narterial 60 x 40 mmHg; Frequência cardíaca 145 bpm; Frequência respiratória 33 ipm; Temperatura\naxilar 33,9 °C; Saturação periférica com máscara 15l/min 85 %. É atendido conforme o protocolo\namericano de trauma, com os seguintes achados: A ? Via aérea pérvia, com colar cervical. B ?\n\nMurmúrio abolido à direita, maciço à percussão, expansibilidade reduzida neste lado. Sem\nalterações à esquerda. C ? Hipotenso,\ntaquicárdico, pulsos filiformes, extremidades frias, sudoreico,\ngemente. D ? Abre o olho ao estímulo doloroso, tem resposta verbal com sons incompreensíveis,\nsem formar palavras, movimentos de retirada com flexão normal na resposta motora. Pupilas\nisocóricas, fotorreagentes. E ? Crepitação no exame pélvico. Diante do trauma multissistêmico, e\npela impossibilidade de realizar tomografias no momento, realizou os exames radiológicos abaixo,\nno leito. O FAST (Extended Focused Assessment with Sonography in Trauma), não evidenciou\nlíquido intraperitoneal. Para este caso, assinale as condutas e justificativas preconizadas.","options":{"A":"Garantir uma via aérea definitiva com intubação orotraqueal pelo rebaixamento de consciência,\ndrenagem torácica em sistema fechado, acionar protocolo de transfusão maciça e imobilização da\npelve.","B":"Garantir uma via aérea definitiva com intubação orotraqueal pelo rebaixamento de consciência,\ntoracocentese diagnóstica, acionar protocolo de transfusão maciça e imobilização da pelve.","C":"Garantir uma via aérea definitiva com intubação orotraqueal pela instabilidade hemodinâmica,\ndrenagem torácica em sistema fechado, expansão com cristaloide e imobilização da pelve.","D":"Garantir uma via aérea definitiva com intubação orotraqueal pelo rebaixamento de consciência,\n\ndrenagem torácica em sistema fechado, expansão com cristaloides e laparotomia exploradora."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/373562.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337613","number":"337613","sourceNumber":"337613","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 25 anos é trazido para sala de emergência pelo SAMU com história de\ntrauma moto em via de alta velocidade. Na\ncena foi entubado e deu entrada no serviço sedado com\ncetamina em com PA: 80x50mmHg e FC: 122bpm. Ausculta abolida em hemitórax direito, com\nmacicez à percussão. Em relação ao caso descrito, assinale a alternativa CORRETA:","options":{"A":"A principal suspeita é de pneumotórax hipertensivo e deve-se realizar a drenagem torácica com\ngelco em 5ºEIE.","B":"A hipotensão deve ser atribuída à sedação, uma vez que o paciente já se encontra intubado.","C":"Inicialmente estabilizar coluna cervical, fazer o ABCDE do ATLS, e seguir fazer TC de abdome\npara suspeita de lesão hepática com\ndeslocamento para diafragma.","D":"Fazer drenagem torácica D, pois se trata de hemotórax e se débito > 1500mL, indicar\ntoracotomia de urgência."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337614","number":"337614","sourceNumber":"337614","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Após avaliação de um paciente com trauma abdominal admitido no pronto socorro,\nanalise as afirmativas a seguir: I- Deve-se\npassar um cateter vesical antes da realização do FAST\npara avaliar líquido no fundo de saco na pelve. II- Hematúria macroscópica indica lesão de bexiga,\nureteres, ou do rim. III- Ausência de hematúria exclui lesão injúria ao trato genitourinário. IV-\nPaciente com equimose perineal ou hematoma escrotal deve ser mandatório realizar uretrografia\nretrograda. Está(ão) CORRETA(S) as afirmativas:","options":{"A":"I apenas.","B":"II e IV apenas.","C":"III e IV apenas.","D":"I e III apenas."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-337615","number":"337615","sourceNumber":"337615","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Na avaliação do traumatismo craniano, é CORRETO afirmar que:","options":{"A":"A dilatação pupilar associado com hemiparesia contralateral é o sinal clássico da herniação do\nuncus.","B":"A intubação deve ser realizada quando a escala de coma de Glasgow for menor que 11.","C":"A fratura de crânio linear aumenta risco de hematoma aproximadamente 10 vezes.","D":"O hematoma subdural, tipicamente mostra lesão biconvexa na tomografia e é mais comum que\no hematoma epidural."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-336257","number":"336257","sourceNumber":"336257","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Vítima de ferimento por arma de fogo durante assalto chega ao Pronto Socorro por\nmeios próprios. Lúcido e orientado, eupneico,\nPA:100x60mmHg, FC:130bpm. Presença de orifício\nde entrada em flanco direito. Não identificado orifício de saída. Assinale a conduta mais indicada:","options":{"A":"Laparotomia exploradora","B":"Sutura da ferida, curativo, antibioticoprofilaxia e reavaliação a cada 6h","C":"Rotina radiográfica para abdome agudo","D":"Paciente sem risco neste momento"},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-334726","number":"334726","sourceNumber":"334726","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Paciente politraumatizado após acidente motociclístico deu entrada gravíssimo à\nunidade de emergência, já intubado e\napresentando enfisema subcutâneo em tórax, desvio\ntraqueal para a esquerda, turgência jugular e murmurio vesicular abolido em hemitórax direito.\nFrequência cardíaca de 158 bpm, pressão arterial de 88/56 mmHg, saturação periférica de oxigênio\nde 89%, mesmo com alto fluxo de oxigênio. Observe as alternativas relacionadas ao quadro clínico\ndo paciente e assinale a correta:","options":{"A":"A radiografia de tórax é imprescindível para determinar o tratamento adequado.","B":"O tratamento definitivo adquado para este paciente deve ser a punção com agulha no 5º espaço\nintercostal à esquerda.","C":"O paciente apresenta choque grau IV e o tratamento a ser instituído de imediato consiste em\nhemotransfusão maciça.","D":"A ventilação com pressão positiva é um fator de piora clínica deste paciente na presença de\nlesão da pleura visceral."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-334728","number":"334728","sourceNumber":"334728","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"O SAMU acaba de trazer um paciente vítima de atropelamento por caminhão. Paciente\ntem 21 anos e apresenta quadro de\nhipotensão, bradiarritmia e desregulação da temperatura.\n\nDiante desse quadro foi considerada a hipótese de choque neurogênico. A propósito do diagnóstico\nestabelecido, assinale a opção correta:","options":{"A":"É uma consequência devastadora da lesão da medula espinhal, principalmente associada a\nlesão da coluna torácica baixa e lombar alta.","B":"É clinicamente similar ao choque hipovolêmico.","C":"Ocorre devido a perda súbita do tônus simpático, com função parassimpática preservada.","D":"O choque neurogênico, caracteriza-se por perda de todos os controles neurais abaixo da lesão."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-335083","number":"335083","sourceNumber":"335083","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Exige intervenção operatória imediata o seguinte cenário:","options":{"A":"Ferimento por arma branca na zona II da região cervical que violou o platisma.","B":"Lesão esplênica em grau III em menina de sete anos de idade, hemodinamicamente estável.","C":"Hematoma retroperitoneal na zona II, não expansivo.","D":"Fratura distal do fêmur, com um frêmito sobrejacente palpável."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-346860","number":"346860","sourceNumber":"346860","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um paciente hipotenso sofreu múltiplos ferimentos por arma branca no abdome. Na\nsala de operação evidencia laceração transversa de toda a extensão do estômago e lesão\nesplênica de menor gravidade. Considerando esse caso, a MELHOR maneira de tratar as\nperfurações gástricas, do paciente, é com:","options":{"A":"O fechamento primário de ambas as feridas.","B":"A ressecção gástrica com fechamento primário.","C":"A ressecção por meio da reconstrução Y de Roux.","D":"A gastrojejunostomia posterior com reparo primário da lesão anterior."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-345721","number":"345721","sourceNumber":"345721","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"É um agente antifibrinolítico que age através de mecanismo competitivo, inibindo a\nativação do plasminogênio a plasmina e promove, assim, maior estabilidade do coagulo, sendo\nbastante utilizado no tratamento dos choques hemorrágicos.","options":{"A":"Warfarin.","B":"Vitamina K.","C":"Ácido tranexâmico.","D":"Fator II."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-345723","number":"345723","sourceNumber":"345723","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o Tratamento Não Operatório (TNO) do trauma contuso hepático, assinale a\nincorreta.","options":{"A":"A maioria das lesões hepáticas são classificadas como grau I a III.","B":"São condições essenciais para realizar o TNO: protocolo bem fundamentado, equipe médica\npresencial para reavaliações, bloco cirúrgico disponível 24h.","C":"Todo paciente deve ser internado em leito de terapia intensiva, independente do grau de lesão e\ndas condições hemodinâmicas.","D":"São critérios para o tratamento não operatório: estabilidade hemodinâmica, ausência de sinais\nde irritação peritoneal e realização de\ntomografia computadorizada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-336285","number":"336285","sourceNumber":"336285","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Menino, 2 anos de idade, é trazido à sala de Emergência com relato de queda de uma\naltura de 2 metros. Ao exame da admissão: vias aéreas pérvias, movimentos respiratórios\nsuperficiais, FR: 12 irpm , SatO2: 94% em ar ambiente, RCR 2T, BNF sem sopros, FC: 70 bpm, PA\n130 x 95 mmHg, Tempo de enchimento capilar 2 seg. Qual o principal diagnóstico sindrômico?","options":{"A":"Trauma Raquimedular","B":"Insuficiência Respiratória Aguda","C":"Hipertensão Intracraniana","D":"Choque cardiocirculatório"},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-345727","number":"345727","sourceNumber":"345727","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Se uma via aérea difícil em urgência necessita que o médico progrida para outra\nestratégia, deve se iniciar os preparativos para uma via aérea cirúrgica. A primeira opção\npreconizada em adultos (sem contraindicações) é:","options":{"A":"Esvaziamento cervical.","B":"Traqueostomia.","C":"Traqueostomia.","D":"Cricotireoidostomia."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-321187","number":"321187","sourceNumber":"321187","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Nos dias atuais, em muitas ocasiões, é utilizado o tromboelastrograma para análise de\ncoagulação, principalmente no trauma. Veja as imagens a seguir, sendo que a primeira figura\nrepresenta o resultado normal. Assinale a alternativa que representa CORRETAMENTE a\ntrombocitopenia.","options":{"A":"A.","B":"B.","C":"C.","D":"D."},"answer":"B","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":["question_bank/media/medcurso/medcurso-cirurgia-cir-1/321187.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-321188","number":"321188","sourceNumber":"321188","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Você está examinando um paciente grave no CTI com suspeita de síndrome de\ncompartimento abdominal. Faz a medida de pressão intra-abdominal que está maior que 25mmHg.\nDiante desse cenário, é CORRETO afirmar que esse paciente apresenta:","options":{"A":"Compressão da veia cava inferior, diminuição do fluxo sanguíneo da parede abdominal, aumento\nda pressão intracraniana.","B":"Aumento da pressão de perfusão cerebral e da pressão intratorácica, e diminuição do retorno\nvenoso.","C":"Diminuição do fluxo sanguíneo renal e da resistência vascular periférica, e aumento da pressão\nendotraqueal.","D":"Aumento do fluxo sanguíneo portal por compensação, diminuição do débito urinário, diminuição\nda resistência vascular pulmonar."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-335109","number":"335109","sourceNumber":"335109","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Criança de sete anos de idade chega ao pronto-socorro vítima de queda de laje há 30\nminutos. Segundo a acompanhante, imediatamente após o trauma, o paciente apresentou perda de\nconsciência e um episódio de vômito. À admissão, encontrava-se com 15 pontos na Escala de\nComa de Glasgow, com pupilas isocóricas fotorreagentes, sem déficits. Realizado raio X simples de\ncrânio, constatou-se fratura em região temporal direita. Enquanto aguardava tomografia de crânio,\nevoluiu com rebaixamento do nível de consciência (11 pontos na Escala de Coma de Glasgow),\nhemiparesia esquerda e anisocoria D > E. A hipótese mais provável é","options":{"A":"hematoma subdural agudo com herniação uncal.","B":"lesão axonal difusa.","C":"contusão temporal esquerda.","D":"hematoma extradural com herniação uncal."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-320460","number":"320460","sourceNumber":"320460","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 30 anos, vítima de acidente automobilístico, foi levado ao\n\npronto-socorro, estando torporoso, com palidez cutânea, com sudorese, e PA 80x60 mmHg. A\navaliação radiológica inicial evidenciou fratura do anel pélvico, com alargamento da sínfise pubiana\nmaior que 3 cm. Foi realizado FAST com evidencia de líquido livre abdominal. Nesse caso clínico,\nentre as opções a seguir, a melhor conduta é:","options":{"A":"Estabilizar o anel pélvico e, em seguida, realizar a laparotomia exploradora.","B":"Estabilizar o anel pélvico e proceder à transfusão e à monitorização hemodinâmica rigorosa.","C":"Monitorização clínica, expansão volêmica e manejo conservador.","D":"Proceder à laparotomia exploradora e, posteriormente, estabilizar o anel pélvico.","E":"Proceder à embolização, seguida de estabilização externa do anel pélvico."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-320463","number":"320463","sourceNumber":"320463","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Um homem de 25 anos, vítima de colisão automobilística deu entrada na emergência,\ncom frequência respiratória de 32 irpm, glasgow 8 e\ncom grande quantidade de sangue na\ncavidade oral, na face e no nariz, além da presença de múltiplos dentes fraturados. À inspeção,\nsinal do Guaxinim bilateral, sinal de Battle e otorragia à direita. À palpação, apresentou\ncrepitação\nem região mandibular. Nesse caso clínico, além de estabilizar a coluna cervical do paciente,\n\ndeve-se, nesse momento:","options":{"A":"Aspirar cavidade oral, nasal e suporte com cateter de oxigênio.","B":"Proceder à intubação nasotraqueal.","C":"Colocar cânula orofaríngea e iniciar ventilação.","D":"Realizar traqueostomia.","E":"Realizar cricotireoidostomia."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-306695","number":"306695","sourceNumber":"306695","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Diante de um acidente de trânsito, com múltiplas vítimas, assinale qual dos pacientes\nabaixo deverá receber atendimento prioritário:","options":{"A":"A.D.S., 27 anos, gestante de 30 semanas, apresentando sangramento vaginal, eupneica, com\ntempo de enchimento capilar = 2 segundos, consciente e respondendo a comandos.","B":"J.P.D., 16 anos, sexo masculino, inconsciente na cena, sem movimentos respiratórios e sem\npulsos centrais palpáveis.","C":"K.L.T, 36 anos, sexo feminino, apresentando ferimento cortocontuso em coxa direita, com\nsangramento local, deambulando próximo ao carro que dirigia.","D":"T.R.D., 42 anos, sexo masculino, encontrado em decúbito dorsal, eupneico, com tempo de\nenchimento capilar = 4 segundos, com sangramento em região de mão direita."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-304853","number":"304853","sourceNumber":"304853","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Homem de 27 anos e 72 kg, vítima de acidente automobilístico, apresenta frequência\ncardíaca de 140 bpm, pressão arterial de\n100/60 mmHg e frequência respiratória de 28 irpm. É\nlevado à sala de cirurgia e após a abertura cirúrgica do abdomen a pressão arterial diminui para\n80/40 mmHg. A perda de sangue estimada é de cerca de 3.000 mL. Após administrar 2.500 mL de\nhidroxietilamido, o paciente apresenta sangramento difuso na ferida operatória. Qual o mecanismo\nprovável para essa complicação?","options":{"A":"Plaquetopenia.","B":"Deficiência de proteína C.","C":"Diluição de fatores da coagulação.","D":"Coagulação intravascular disseminada."},"answer":"C","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-305005","number":"305005","sourceNumber":"305005","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Considere que um paciente vítima de agressão por arma branca no sexto espaço\nintercostal esquerdo, na linha hemiclavicular,\nchega à Emergência com pulso de 140 bpm, PA de\n60 x 30 mmHg e FR de 28 mov/min. Não há desvio de traqueia e o murmúrio vesicular é simétrico\nbilateralmente. Nesse caso, o quadro é mais compatível com:","options":{"A":"Lesão de vasos do estreito superior.","B":"Lesão de artéria pulmonar esquerda.","C":"Lesão de vasos pericárdio-frênicos.","D":"Lesão cardíaca com tamponamento."},"answer":"A","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-313290","number":"313290","sourceNumber":"313290","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre a Contusão Pulmonar, considere os itens, abaixo: I- Lesão torácica,\npotencialmente letal mais comum, é produzida\npelo impacto do trauma ou por desaceleração\nsúbita; II- A lesão produz ruptura do parênquima pulmonar, lesando alvéolos e vasos; III- A região\nlesada perde a capacidade de troca gasosa e perfusão sanguínea. Dos itens acima:","options":{"A":"Nenhum dos itens está correto.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Todos os itens estão corretos."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-313291","number":"313291","sourceNumber":"313291","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"Sobre o trauma cervical, as zonas cervicais, para avaliação, são divididas da seguinte\nforma: I- Abrange do ângulo da mandíbula\naté a base do crânio; II- Abrange da cartilagem cricoide\naté o ângulo da mandíbula; III- Base do pescoço ? Abrange da clavícula até a cartilagem cricoide.\nRespectivamente, os itens acima discorrem sobre as:","options":{"A":"Zona I / Zona II / Zona III.","B":"Zona I / Zona III / Zona II.","C":"Zona II / Zona III / Zona I.","D":"Zona II / Zona I / Zona III.","E":"Zona III / Zona II / Zona I."},"answer":"E","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cirurgia-cir-1-304857","number":"304857","sourceNumber":"304857","collectionBlock":"medcurso:medcurso-cirurgia-cir-1","collectionLabel":"Medcurso · CIR 1","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"CIR 1","subtopic":"","stem":"A equipe de socorro pré-hospitalar atende um homem, de 36 anos, vítima de queda de\naproximadamente 4 metros de altura. O paciente encontrava-se em decúbito dorsal, irresponsivo e\ncom a cabeça e cervical mantidas alinhadas por um vizinho. Ao exame apresentava respiração\nirregular, que aumentava em profundidade e depois diminuía e presença de sangue em narinas e\norelhas. O paciente aceitou a cânula orofaríngea e a via aérea está pérvia. Foi posicionado o\ndispositivo ventilatório máscara-bolsa e ventilado com frequência de 12 vezes/minuto. A pupila\ndireita está midriática; frequência de pulso de 54 bpm, com pulso regular; saturação periférica de\noxigênio de 96%; pele fria, seca e pálida; pontuação de Glasgow = 7 (abertura ocular 2; resposta\nverbal 1; melhor resposta motora 4). A avaliação secundária foi realizada a caminho do hospital. O\npaciente é coberto com cobertor quente, a pressão arterial é 190/100 mmHg e o eletrocardiograma\nrevela bradicardia sinusal, com contrações ventriculares isoladas. Sobre o caso acima, assinale a\nalternativa correta.","options":{"A":"As lesões traumáticas cerebrais são extremamente complexas e o atendimento pré-hospitalar\nagrega pouco valor ao desfecho final, devendo o\npaciente chegar ao hospital o mais rápido\npossível.","B":"A assistência especializada a esse paciente, visa, principalmente, prevenir a lesão cerebral\nprimária, já que não há meios de controlar a lesão cerebral secundária.","C":"A descrição clínica do quadro do paciente aponta para uma importante gravidade, porém, não\nhá critérios que apontem para um alto risco de\nherniação cerebral.","D":"O padrão ventilatório descrito na avaliação inicial do paciente pela equipe de emergencistas\naponta para um padrão ventilatório denominado\nrespiração de Cheyne-Stokes."},"answer":"D","source":"Cirurgia/CIR 1/CIR 1.txt","sourceLabel":"Medcurso · CIR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","CIR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
